  ui_story_5020_50200101_39_dialog_content = "そして、長い間封印されていた「冥土の幽刀」を解放し、\n彼女は夜の闇の中へと消えて行った。",
  ui_story_5020_50200101_40_dialog_content = "ちょっと待って？\nそれだと僕たちが悪人みたいに聞こえない？",
  ui_story_5020_50200101_41_dialog_content = "巫女様は江富の人々を守るため、\n将軍様の許可なしで雲照鏡を使い、鬼をはらった…",
  ui_story_5020_50200101_42_dialog_content = "だけど、そのせいで、封印の間に駆けつけた\n将軍様を怒らせてしまった。",
  ui_story_5020_50200101_43_dialog_content = "将軍は怒って、みんなと戦って…",
  ui_story_5020_50200101_44_dialog_content = "その後は？",
  ui_story_5020_50200101_45_dialog_content = "まだないよ。今、君たちが見ての通りの状況だよ。",
  ui_story_5020_50200101_46_dialog_content = "ヨウはお城に取り残されたっきりだし、\nアメモリは師匠を追いかけていっちゃったんだ。",
  ui_story_5020_50200101_47_dialog_content = "それで、僕らはここで\n追っ手に見つからないようにしてるってわけ。",
  ui_story_5020_50200101_48_dialog_content = "それから、ヨウが追いついてくることを\n待っているのでございます。",
  ui_story_5020_50200101_49_dialog_content = "どう？覚えた？",
  ui_story_5020_50200101_50_dialog_content = "覚えたよ！今度お客さんに話すネタができたね。\nでも、まだタイトルが決まってないよ。",
  ui_story_5020_50200101_51_dialog_content = "ううん…じゃあ『空の末裔、極東へ行く』とか！",
  ui_story_5020_50200101_52_dialog_content = "でも、この話、これだけじゃあまり興味をそそられない気がするよ。\nもう少しストーリー性を足さない？",
  ui_story_5020_50200101_53_dialog_content = "ラブロマンスか、それとも悲恋？",
