  ui_story_5020_50200101_55_dialog_content = "ラブロマンス？",
  ui_story_5020_50200101_56_dialog_content = "何でもないよ！",
  ui_story_5020_50200101_57_dialog_content = "今、ドアのすき間から様子をうかがってみたんだけど…",
  ui_story_5020_50200101_58_dialog_content = "外は本当に…まったく、何の動きもないわ。",
  ui_story_5020_50200101_59_dialog_content = "おかしいわよね。\n城にいた人たち、界町を探すって言ってなかった？",
  ui_story_5020_50200101_60_dialog_content = "せっかく初めて「指名手配犯」になったのに、\n何も始まらないうちに終わっちゃったのかしら。",
  ui_story_5020_50200101_61_dialog_content = "惜しむことじゃないよ！？",
  ui_story_5020_50200101_62_dialog_content = "おそらく…<color=#FFB400>夜行</color>が間もなく始まるからでございましょう。",
  ui_story_5020_50200101_63_dialog_content = "夜行？",
  ui_story_5020_50200101_64_dialog_content = "「春日祭」前の最後の準備で、\n「<color=#FFB400>提灯夜行</color>（ちょうちんやこう）」というものです。",
  ui_story_5020_50200101_65_dialog_content = "<color=#e8d9bb>ドン――</color>",
  ui_story_5020_50200101_66_dialog_content = "<color=#e8d9bb>ドン、ドン――</color>",
  ui_story_5020_50200101_67_dialog_content = "あ、酉（とり）の刻の太鼓だ――",
  ui_story_5020_50200101_68_dialog_content = "さあさあ、行くよ！",
  ui_story_5020_50200101_69_dialog_content = "街中に上客さんがあふれてる！\n<size=45>突撃～！</size>",
  ui_story_5020_50200101_70_dialog_content = "<size=45>かき入れ時ね！</size>",
  ui_story_5020_50200101_71_dialog_content = "外はにぎやかみたいですね。",
  ui_story_5020_50200101_72_dialog_content = "ええ…今なら人混みに紛れて、\nここを離れられるかもしれません。",
  ui_story_5020_50200101_73_dialog_content = "追っ手も今、この人混みの中を探そうとはしないでしょう。\n大混乱になりかねませんから。",
  ui_story_5020_50200101_74_dialog_content = "…ヨウとの約束の刻限になりましたが…",
  ui_story_5020_50200101_75_dialog_content = "まだ姿が見えないということは、\nあちらの状況も楽観できないようです。",
  ui_story_5020_50200101_76_dialog_content = "ヨウのことだから、道に迷ってる可能性も…",
  ui_story_5020_50200101_77_dialog_content = "確かに、あり得ないことではございませんね。",
  ui_story_5020_50200101_78_dialog_content = "とにかく、まずは合流することが肝要…",
  ui_story_5020_50200101_79_dialog_content = "町へ出るといたしましょう。",
  ui_story_5020_50200101_80_dialog_content = "わぁ！！",
  ui_story_5020_50200101_81_dialog_content = "父さん、アレ！見て見て！",
  ui_story_5020_50200101_82_dialog_content = "おい！そんなに走るんじゃない！\nお面を付けてるんじゃ、迷子になったら見つけられないぞ！",
  ui_story_5020_50200101_83_dialog_content = "見つけられない？",
  ui_story_5020_50200101_84_dialog_content = "じゃあ、かくれんぼしようよ！",
  ui_story_5020_50200101_85_dialog_content = "ほら、つかまえた！もう走り回るんじゃないぞ。",
  ui_story_5020_50200101_86_dialog_content = "ハハハ…ハハ…父さん、くすぐったいよ！\n分かったよ、もう走らないって！",
  ui_story_5020_50200101_87_dialog_content = "皆、変わったお面を付けてるわね？\nちょっと可愛いわ。何かに似てる…",
  ui_story_5020_50200101_88_dialog_content = "ネコでございます。",
  ui_story_5020_50200101_89_dialog_content = "ネコは昼に寝て、夜に動くもの。\nそのため、人と鬼との橋渡し役だと考えられているのです。",
  ui_story_5020_50200101_90_dialog_content = "生きている人が亡くなった人と\nつながっていたいという気持ちの表れ、ってことですか？",
  ui_story_5020_50200101_91_dialog_content = "故人に今一度会いたいという…\nむしろ、切望でございましょうか。",
  ui_story_5020_50200101_92_dialog_content = "故人…",
  ui_story_5020_50200101_93_dialog_content = "PlayerName？",
  ui_story_5020_50200101_94_dialog_content = "え？",
  ui_story_5020_50200101_95_dialog_content = "このお面、とっても可愛いわ。\n私たちも買っていかない？",
  ui_story_5020_50200101_96_dialog_content = "今はそれどころじゃないよ、\n僕たちはこれから…",
  ui_story_5020_50200101_97_dialog_content = "いいお考えだと思いますよ。\n正体を隠すのに都合がよいかもしれません。",
  ui_story_5020_50200101_98_dialog_content = "ひとまず、わたくしたちも人の流れに乗って進みましょう。",
  ui_story_5020_50200101_99_dialog_content = "お面を売っているお店があったら、ついでに買うことにいたしましょう。",
  ui_story_5020_50200101_100_dialog_content = "わかったよ。",
  ui_story_5020_50200101_101_dialog_content = "あら？PlayerName、動かないで…",
  ui_story_5020_50200101_102_dialog_content = "どうしたの？バイス。",
  ui_story_5020_50200101_103_dialog_content = "髪の毛にお豆がついてるわよ？",
  ui_story_5020_50200101_104_dialog_content = "豆？確かに何か、すごく軽い物がぶつかった気はしたけど。",
  ui_story_5020_50200101_105_dialog_content = "一体どこから？",
  ui_story_5020_50200101_106_dialog_content = "鬼は外、福は内！",
  ui_story_5020_50200101_107_dialog_content = "えっ！？",
  ui_story_5020_50200101_108_dialog_content = "なんで豆を投げられてるの！？",
  ui_story_5020_50200101_109_dialog_content = "豆には鬼を追い出す力があると言われておりますゆえ…\nそのようにして、人の中に紛れ込んでいる悪鬼をはらうのでございます。",
  ui_story_5020_50200101_110_dialog_content = "僕が鬼だと思われてるってこと？",
  ui_story_5020_50200101_111_dialog_content = "いいえ、これは己の中の鬼を追い出す儀式…\nつまり、祝福でもございます。",
  ui_story_5020_50200101_112_dialog_content = "そういうことならいいけど…",
  ui_story_5020_50200101_113_dialog_content = "あっ！申し訳ありません！\nうちの子がわんぱくで…",
  ui_story_5020_50200101_114_dialog_content = "いいえ、構いませんよ。祝福なんですよね？",
  ui_story_5020_50200101_115_dialog_content = "そうそう。祝福されてるなら、\n怒ることじゃないよね。",
  ui_story_5020_50200101_116_dialog_content = "お兄ちゃん、この福豆をあげる！\n平和に暮らせますように！",
  ui_story_5020_50200101_117_dialog_content = "一緒に叫ぼう！鬼は外、福は内！",
  ui_story_5020_50200101_118_dialog_content = "…鬼は外、福は内！",
  ui_story_5020_50200101_119_dialog_content = "なかなか様になっておいでですよ、PlayerName様。",
  ui_story_5020_50200101_120_dialog_content = "…",
  ui_story_5020_50200101_121_dialog_content = "…ねぇ、あれを見て。",
  ui_story_5020_50200101_122_dialog_content = "あそこのお面をつけてる人…",
  ui_story_5020_50200101_123_dialog_content = "アメモリ？",
  ui_story_5020_50200101_124_dialog_content = "どうしてここに…",
  ui_story_5020_50200101_125_dialog_content = "シーッ――",
  ui_story_5020_50200101_126_dialog_content = "お主ら、今夜は街を歩かぬ方がよいぞ。",
  ui_story_5020_50200101_127_dialog_content = "えっ？",
  ui_story_5020_50200101_128_dialog_content = "身を隠せ。もしくは、遠くへ逃げろ。",
  ui_story_5020_50200101_129_dialog_content = "これから江富城は…",
  ui_story_5020_50200101_130_dialog_content = "苦しみながら再生を果たす。",
  ui_story_5020_50200101_131_dialog_content = "どういう意味？",
  ui_story_5020_50200101_132_dialog_content = "アメモリ、何をするつもりなの？",
  ui_story_5020_50200101_133_dialog_content = "消えた！？",
  ui_story_5020_50200101_134_dialog_content = "相変わらず、言葉の少ないお方でございますね。",
  ui_story_5020_50200101_135_dialog_content = "ただ…",
  ui_story_5020_50200101_136_dialog_content = "わざわざその一言を\n伝えるためだけに来たというのは…",
  ui_story_5020_50200101_137_dialog_content = "父さん、父さん！あそこにいる人、見て！\nすごくカッコいいお面を付けてる！",
  ui_story_5020_50200101_138_dialog_content = "あれは――",
  ui_story_5020_50200101_139_dialog_content = "<anim type=Shake><size=45>グアアア――！</size></anim>",
  ui_story_5020_50200101_140_dialog_content = "鬼だ！鬼が出たぞ！",
  ui_story_5020_50200101_141_dialog_content = "鬼が出たぞ！！！",
  ui_story_5020_50200101_142_dialog_content = "早く逃げろ！",
  ui_story_5020_50200101_143_dialog_content = "助けてくれぇ！",
  ui_story_5020_50200101_144_dialog_content = "！？",
  ui_story_5020_50200101_145_dialog_content = "PlayerName、戦闘準備よ！",
  ui_story_5020_50200202_1_dialog_content = "<anim type=Shake>グゥ――</anim>",
  ui_story_5020_50200202_2_dialog_content = "わ！こ、来ないで！",
  ui_story_5020_50200202_3_dialog_content = "<color=#e8d9bb>ヒュ――</color>",
  ui_story_5020_50200202_4_dialog_content = "ケガはないか？",
  ui_story_5020_50200202_5_dialog_content = "うう…大丈夫だよ。\nありがとう、お姉ちゃん。",
  ui_story_5020_50200202_6_dialog_content = "<anim type=Shake>グガァ…</anim>",
  ui_story_5020_50200202_7_dialog_content = "面倒な…これではキリがない。",
  ui_story_5020_50200202_8_dialog_content = "お姉ちゃん、僕たちどうすればいいの！？",
  ui_story_5020_50200202_9_dialog_content = "あちらへ逃げろ。振り返ってはならんぞ。",
  ui_story_5020_50200202_10_dialog_content = "<anim type=Shake>グアア――</anim>",
  ui_story_5020_50200202_11_dialog_content = "PlayerName、何してるの？",
  ui_story_5020_50200202_12_dialog_content = "さっきからおかしいわよ。\n何か叫んでたみたいだけど。",
  ui_story_5020_50200202_13_dialog_content = "地面に落ちてる福豆の袋を見てよ。\nもう何袋も投げたんだ。",
  ui_story_5020_50200202_14_dialog_content = "ちゃんと叫びながら――",
  ui_story_5020_50200202_15_option_content = "「鬼は外、福は内！」",
  ui_story_5020_50200202_16_dialog_content = "<color=#e8d9bb>バシャッ――</color>",
  ui_story_5020_50200202_17_option_content = "「鬼は外、福は内！」",
  ui_story_5020_50200202_18_dialog_content = "<color=#e8d9bb>バシャッ――</color>",
  ui_story_5020_50200202_19_option_content = "「鬼は外！福はいち…！」",
  ui_story_5020_50200202_20_dialog_content = "イタッ…舌を噛んじゃった。",
  ui_story_5020_50200202_21_dialog_content = "で、効果はあったの？",
  ui_story_5020_50200202_22_dialog_content = "ううん…見ての通り、戦いはみんなに任せた方がよさそう…",
  ui_story_5020_50200202_23_dialog_content = "<size=45>うわあああ！！</size>",
  ui_story_5020_50200202_24_dialog_content = "こちらへ来てはなりません。皆様、お戻りください！",
  ui_story_5020_50200202_25_dialog_content = "速射感知！",
  ui_story_5020_50200202_26_dialog_content = "どうして鬼が町に出てきてるの！？\n将軍の手下とか、兵士は何してるの！？",
  ui_story_5020_50200202_27_dialog_content = "まさか本当に、全員で城門でも守ってる訳じゃないよね？",
  ui_story_5020_50200202_28_dialog_content = "それはないでしょ…本当にそうだったら、\n私たちも逃げられてないでしょうし。",
  ui_story_5020_50200202_29_dialog_content = "ここは危険でございます。\n何とかして民を避難させましょう。",
  ui_story_5020_50200202_30_dialog_content = "PlayerName様、\n町の人たちを連れて、後方へ退いてください。",
  ui_story_5020_50200202_31_dialog_content = "みんな、僕に付いて来て！\nこっちだよ！",
  ui_story_5020_50200202_32_dialog_content = "おい…あれは巫女じゃないか？",
  ui_story_5020_50200202_33_dialog_content = "知らない異郷人もいるぞ。",
  ui_story_5020_50200202_34_dialog_content = "ついて行って大丈夫なのか？",
  ui_story_5020_50200202_35_dialog_content = "どうしよう…信用されてないみたい。",
  ui_story_5020_50200202_36_dialog_content = "命が危ないって言うのに、\nそんなこと考えてる場合なのかしら…",
  ui_story_5020_50200202_37_dialog_content = "<size=45>わ！！なんでこんなに鬼がいるの！？</size>",
  ui_story_5020_50200202_38_dialog_content = "あれ、PlayerName。まだ逃げてなかったの？",
  ui_story_5020_50200202_39_dialog_content = "早く撤収よ、撤収！屋台もひっくり返されちゃった！！",
  ui_story_5020_50200202_40_dialog_content = "ちょっと待って！",
  ui_story_5020_50200202_41_dialog_content = "モモ、アンズ！君たちの助けが必要なんだ！",
  ui_story_5020_50200202_42_dialog_content = "用事なら後に…",
  ui_story_5020_50200202_43_dialog_content = "そうそう！今は逃げるのが先だよ！",
  ui_story_5020_50200202_44_dialog_content = "まずは落ち着いて…",
  ui_story_5020_50200202_45_dialog_content = "お店の評判、もっと上げたくない？",
  ui_story_5020_50200202_46_dialog_content = "<size=45>あげたい！</size>",
  ui_story_5020_50200202_47_dialog_content = "雲島でいちばんのお店になりたくない？",
  ui_story_5020_50200202_48_dialog_content = "<size=45>もちろん！</size>",
  ui_story_5020_50200202_49_dialog_content = "じゃあ、いつもの…ええと、呼び込みの力で、\n皆を安全な所まで避難させてくれない？",
  ui_story_5020_50200202_50_dialog_content = "<anim type=Shake><size=50>みんな～！こっちよ！！ついてきて～！</size></anim>",
  ui_story_5020_50200202_51_dialog_content = "うわあ、耳が…！！",
  ui_story_5020_50200301_1_dialog_content = "公方様、御用達の商人が\nお目にかかりたいとのことで、城の外に控えております。",
  ui_story_5020_50200301_2_dialog_content = "今宵は夜行で稼ぐのに忙しいはずであろう？\nわざわざ余を訪ねてくるとは、いかなる用だ…？",
  ui_story_5020_50200301_3_dialog_content = "まあよい、通せ。",
  ui_story_5020_50200301_4_dialog_content = "公方様、どうかお助けください！",
  ui_story_5020_50200301_5_dialog_content = "苦しゅうない、おもてを上げよ…一体何事だ？",
  ui_story_5020_50200301_6_dialog_content = "公方様のお耳にはまだ入っていないのですか…？\n界町が先程、鬼に襲撃されたのでございます。",
  ui_story_5020_50200301_7_dialog_content = "そうでございます！",
  ui_story_5020_50200301_8_dialog_content = "あっしらの店もひっくり返されたんです。\nとんだ大損ですよ…",
  ui_story_5020_50200301_9_dialog_content = "これじゃ今年の春日祭も、\n何の儲けも上げられなくなりそうです！",
  ui_story_5020_50200301_10_dialog_content = "オッホン…お前は黙ってろ。\nそんなことは後回しだ。",
  ui_story_5020_50200301_11_dialog_content = "公方様、界町が大騒ぎになり、\nこうして急ぎ、ご報告に上がりました。",
  ui_story_5020_50200301_12_dialog_content = "鬼の襲撃？まことか？",
  ui_story_5020_50200301_13_dialog_content = "私どもの失態であります。\n兵士どもは今、城内の――",
  ui_story_5020_50200301_14_dialog_content = "ただちに城兵を向かわせい！",
  ui_story_5020_50200301_15_dialog_content = "これ以上の大ごとになれば、お主も生かしておかぬぞ！",
  ui_story_5020_50200301_16_dialog_content = "はっ！",
  ui_story_5020_50200301_17_dialog_content = "公方様、ありがとうございます！",
  ui_story_5020_50200301_18_dialog_content = "部下の失態は余の失態だ。許せ…",
  ui_story_5020_50200301_19_dialog_content = "と、とんでもない！",
  ui_story_5020_50200301_20_dialog_content = "先ほど、リンネ様が町で民を避難させてくださっているのを拝見いたしました。",
  ui_story_5020_50200301_21_dialog_content = "何？リンネが？",
  ui_story_5020_50200301_22_dialog_content = "提灯夜行のご準備のため、町におられたのでしょう。\nすぐさま私どもの保護に駆けつけてくださいました。",
  ui_story_5020_50200301_23_dialog_content = "私どもも勇ましいお姿に感激いたしまして…",
  ui_story_5020_50200301_24_dialog_content = "何かお手伝いせねばと思いました。",
  ui_story_5020_50200301_25_dialog_content = "あの騒ぎでは、リンネ様が公方様にお伝えする余裕もないだろうと思い、\n勝手ながら、こうしてご報告に参上したのでございます。",
  ui_story_5020_50200301_26_dialog_content = "そうか、大儀であった。",
  ui_story_5020_50200301_27_dialog_content = "謀反人（むほんにん）どもが鬼を町におびきよせたに違いあるまい。\n民の命もかえりみず、混乱に乗じて反乱を起こすつもりなのであろう。",
  ui_story_5020_50200301_28_dialog_content = "しかし、もはや恐れることはない。城兵どもはすでに発った。\n皆の者の安全は、余が必ず保証しよう。",
  ui_story_5020_50200301_29_dialog_content = "雲島にあなた様がいらしたことは、まことに幸運でございます！",
  ui_story_5020_50200301_30_dialog_content = "それでは、私どもはこれにて失礼いたします。",
  ui_story_5020_50200301_31_dialog_content = "…フン、雲島の民草どもは平和の何たるかを理解しておらぬ。\nただ誰かの作った平和にあずかることしか知らぬのだ。",
  ui_story_5020_50200301_32_dialog_content = "理想を叶えるためには、\n必ずや犠牲を払うことになる。",
  ui_story_5020_50200301_33_dialog_content = "しかし、<color=#FFB400>幽燭の者</color>どもがまだ動かんとは、\n意外であるな。",
  ui_story_5020_50200301_34_dialog_content = "ナギの足取りは？",
  ui_story_5020_50200301_35_dialog_content = "まだ何も…",
  ui_story_5020_50200301_36_dialog_content = "<size=45>この役立たずどもめが…！</size>",
  ui_story_5020_50200301_37_dialog_content = "将軍様、どうかお怒りをお静めください…",
  ui_story_5020_50200301_38_dialog_content = "鬼ども連れて界町へ向かい、\n奴らをおびき出せ。",
  ui_story_5020_50200301_39_dialog_content = "今日こそ奴らを根絶やしにせよ。",
  ui_story_5020_50200301_40_dialog_content = "春日祭も、必ずいつも通り開催させる。",
  ui_story_5020_50200301_41_dialog_content = "はっ。",
  ui_story_5020_50200301_42_dialog_content = "リンネは時おり、そなたに似ている。",
  ui_story_5020_50200301_43_dialog_content = "そなたがおれば、リンネを好いたことであろうな。",
  ui_story_5020_50200301_44_dialog_content = "余はそなたに代わる、\n新たな巫女を育てることに希望を託したが…",
  ui_story_5020_50200301_45_dialog_content = "間違いようもなく、失敗に終わったようだ。",
  ui_story_5020_50200301_46_dialog_content = "そなたはやはり、この世に2人といない者であったのだ。",
  ui_story_5020_50200301_47_dialog_content = "しかし、安心して見ているがいい。\n約束は必ず守ってみせよう。",
  ui_story_5020_50200301_48_dialog_content = "そなたの望み、\nそして余とそなた、2人の望みを。",
  ui_story_5020_50200301_49_dialog_content = "<anim type=Shake><size=45>グアアア――</size></anim>",
  ui_story_5020_50200301_50_dialog_content = "数が多すぎる！",
  ui_story_5020_50200301_51_dialog_content = "あの将軍、まさか本当に民を見殺しにするつもりじゃ…",
  ui_story_5020_50200301_52_dialog_content = "速射感知――",
  ui_story_5020_50200301_53_dialog_content = "今度の鬼、さっきより手強くなってるわ。",
  ui_story_5020_50200301_54_dialog_content = "集中して…今一番大事なのは、みんなを避難させることだ。",
  ui_story_5020_50200301_55_dialog_content = "リンネ、バイス、もう少しがんばって！",
  ui_story_5020_50200302_1_dialog_content = "モモとアンズの方はどうなってるかな…",
  ui_story_5020_50200302_2_dialog_content = "<size=33>PlayerName！</size>",
  ui_story_5020_50200302_3_dialog_content = "…誰か、僕を呼んだ？",
  ui_story_5020_50200302_4_dialog_content = "え？私には聞こえなかったわよ。",
  ui_story_5020_50200302_5_dialog_content = "PlayerName！",
  ui_story_5020_50200302_6_dialog_content = "あっ、今のは私にも聞こえたわ。",
  ui_story_5020_50200302_7_dialog_content = "あちらから、突進してくる人影が見えますね？",
  ui_story_5020_50200302_8_dialog_content = "<size=50>PlayerName！！！</size>",
  ui_story_5020_50200302_9_option_content = "モモ！？",
  ui_story_5020_50200302_10_dialog_content = "アンズと一緒にみんなを連れて避難したはずじゃ？",
  ui_story_5020_50200302_11_option_content = "アンズ！？",
  ui_story_5020_50200302_12_dialog_content = "モモと一緒にみんなを連れて避難したはずじゃ？",
  ui_story_5020_50200302_13_dialog_content = "PlayerName、あたしがモモだよ！",
  ui_story_5020_50200302_14_dialog_content = "あ、ごめん…2人ともそっくりだから…",
  ui_story_5020_50200302_15_dialog_content = "なぜ戻っていらしたのです？\nアンズと町の皆様は？",
  ui_story_5020_50200302_16_dialog_content = "わたしはここよ！",
  ui_story_5020_50200302_17_dialog_content = "どうして戻ってきたの！？",
  ui_story_5020_50200302_18_dialog_content = "違うって。後ろに集中してたから気づいてないんだろうけど、\n前の方にも、鬼がいたんだよ！",
  ui_story_5020_50200302_19_dialog_content = "わたしたち、囲まれてるの！",
  ui_story_5020_50200302_20_dialog_content = "「こうとなっちゃぁ、道は切って開くしかねぇ！」でございますね。",
  ui_story_5020_50200302_21_dialog_content = "どこかで聞いたような…？",
  ui_story_5020_50200302_22_dialog_content = "そうですか？",
  ui_story_5020_50200302_23_dialog_content = "ヨウの『雲島旅行ガイド』を拝見した時…",
  ui_story_5020_50200302_24_dialog_content = "「季節の服装」の宣伝文句にそう書かれていたのです。",
  ui_story_5020_50200302_25_dialog_content = "正直言うと、リンネにはあまり似合わないよ…",
  ui_story_5020_50200302_26_dialog_content = "そう？カッコいいじゃない！",
  ui_story_5020_50200302_27_dialog_content = "僕にはどうしても…",
  ui_story_5020_50200302_28_dialog_content = "浪人みたいな服を着たサメヤマが\n思い浮かんできちゃうんだ…",
  ui_story_5020_50200302_29_dialog_content = "あ…わかるかも…",
  ui_story_5020_50200302_30_dialog_content = "まぁ、いいわ。道を切って開くとしましょ！",
  ui_story_5020_50200302_31_dialog_content = "皆の者、かかれ！",
  ui_story_5020_50200302_32_dialog_content = "突撃だ！！！",
  ui_story_5020_50200302_33_dialog_content = "な、なに！？",
  ui_story_5020_50200302_34_dialog_content = "将軍が心変わりでもして、\n援軍を送ってくれたとか？",
  ui_story_5020_50200302_35_dialog_content = "服装からして、武士じゃないね。",
  ui_story_5020_50200302_36_dialog_content = "反乱軍の者です。",
  ui_story_5020_50200302_37_dialog_content = "我々は<color=#FFB400>幽燭の軍</color>の者だ！",
  ui_story_5020_50200302_38_dialog_content = "お前ら、何者だ？",
  ui_story_5020_50200302_39_dialog_content = "僕たちは…",
  ui_story_5020_50200302_40_dialog_content = "巫女とよそ者が一緒にいるぞ？",
  ui_story_5020_50200302_41_dialog_content = "捕まえろ！",
  ui_story_5020_50200401_1_dialog_content = "<anim type=Shake>ハクション！</anim>",
  ui_story_5020_50200401_2_dialog_content = "フン…どこのどいつ？\nアタシの悪口を言ったのは…",
  ui_story_5020_50200401_3_dialog_content = "すっかり足がしびれちゃったわ。\n今なら、外に誰もいないみたいね？",
  ui_story_5020_50200401_4_dialog_content = "ふふふ、やっぱり身体は動かしてないと！",
  ui_story_5020_50200401_5_dialog_content = "<anim type=Shake>グゥ――</anim>",
  ui_story_5020_50200401_6_dialog_content = "お城の中に鬼がいるの、\n秘密じゃないのかしら？",
  ui_story_5020_50200401_7_dialog_content = "<size=45>ハッ！</size>",
  ui_story_5020_50200401_8_dialog_content = "あのじいさん、自分の住んでるお城も守れないの？\nさすがにそんなワケないよね？",
  ui_story_5020_50200401_9_dialog_content = "はぁ、髪の毛が乱れちゃったわ。\nこの髪型、セットに手間がかかるのに！",
  ui_story_5020_50200401_10_dialog_content = "それはそうと、アタシ、\n今どこにいるんだろ？",
  ui_story_5020_50200401_11_dialog_content = "お城、広すぎでしょ？\nどの階も同じに見えるし…",
  ui_story_5020_50200401_12_dialog_content = "この廊下、さっき通ったような？",
  ui_story_5020_50200401_13_dialog_content = "このままじゃダメね、\n目印になるものを残しておこっと。",
  ui_story_5020_50200401_14_dialog_content = "ふぅ、この鬼、重い…いい物食べてるのかな？",
  ui_story_5020_50200401_15_dialog_content = "向きはこう…手はこう…で、指はあっちに向けて…",
  ui_story_5020_50200401_16_dialog_content = "ふぅ、これで方向が分かるわね！",
  ui_story_5020_50200401_17_dialog_content = "ん？この匂いは？",
  ui_story_5020_50200401_18_dialog_content = "出口は一体どこおぉぉ！？\nアタシ、鬼はもう触りたくないよ…",
  ui_story_5020_50200401_19_dialog_content = "縁起も悪そうだし…帰ったら、\n10回はお風呂に入らなきゃ！",
  ui_story_5020_50200401_20_dialog_content = "<color=#e8d9bb>ドン――</color>",
  ui_story_5020_50200401_21_dialog_content = "<color=#e8d9bb>ドン、ドン――</color>",
  ui_story_5020_50200401_22_dialog_content = "あ、マズイわ。この音…\nリンネの言ってた酉の刻の太鼓じゃない？",
  ui_story_5020_50200401_23_dialog_content = "ウソでしょ！？\nアタシ、そんなに長い間迷ってたの？",
  ui_story_5020_50200401_24_dialog_content = "ヨウ、ちゃんと頭を動かして！\nアタシは賢いはず！！",
  ui_story_5020_50200401_25_dialog_content = "そうだ…PlayerNameが直感に頼れって言ってた。",
  ui_story_5020_50200401_26_dialog_content = "直感では、ううん、こっちね…",
  ui_story_5020_50200401_27_dialog_content = "直感では、この先を左…",
  ui_story_5020_50200401_28_dialog_content = "お願いお願い、次の角の先は\n初めて行く道でありますように――",
  ui_story_5020_50200401_29_dialog_content = "…",
  ui_story_5020_50200401_30_dialog_content = "PlayerNameのウソつき！\n直感なんて役に立たないわ！",
  ui_story_5020_50200401_31_dialog_content = "…もういいわ！",
  ui_story_5020_50200401_32_dialog_content = "いっそのこと思い切って、\n師匠みたいに飛び降りようかな。",
  ui_story_5020_50200401_33_dialog_content = "そうよ、そうしよ！",
  ui_story_5020_50200401_34_dialog_content = "…うーん、こうして上から見ると…",
  ui_story_5020_50200401_35_dialog_content = "そんなに高くはないみたい？",
  ui_story_5020_50200401_36_dialog_content = "師匠はたぶん、あの桜の木を足場にしたのね？",
  ui_story_5020_50200401_37_dialog_content = "お願い、桜の木さん！アタシを受け止めて！",
  ui_story_5020_50200401_38_dialog_content = "…",
  ui_story_5020_50200401_39_dialog_content = "や、やっぱりダメ…！",
  ui_story_5020_50200401_40_dialog_content = "やっぱり師匠ってすごいんだ、\nアタシにはマネできない！",
  ui_story_5020_50200401_41_dialog_content = "どう見たって高すぎでしょ！！うぅ…",
  ui_story_5020_50200401_41X1_dialog_content = "自信が持てないことはやらない！\n一人前の侠客として！",
  ui_story_5020_50200401_41X2_dialog_content = "ええと、縄か何かないかな。\n見つかれば降りられそうだけど…",
  ui_story_5020_50200401_41X3_dialog_content = "うーん…この部屋の中で、\n何か物を入れるとしたら…",
  ui_story_5020_50200401_41X4_dialog_content = "このタンスしかない！",
  ui_story_5020_50200401_41X5_dialog_content = "え！？",
  ui_story_5020_50200401_41X6_dialog_content = "何だろう…今の感じ…",
  ui_story_5020_50200401_41X7_dialog_content = "よく分からないけど、\nどこか<color=#FFB400>懐かしい</color>感じがした…？",
  ui_story_5020_50200401_41X8_dialog_content = "ま、いいわ！今は縄を探すのが先よ！",
  ui_story_5020_50200401_42_dialog_content = "<color=#e8d9bb>チリン――</color>",
  ui_story_5020_50200401_43_dialog_content = "<color=#e8d9bb>チリン、チリン――</color>",
  ui_story_5020_50200401_44_dialog_content = "なに！？",
  ui_story_5020_50200401_45_dialog_content = "神楽鈴？",
  ui_story_5020_50200401_46_dialog_content = "<color=#e8d9bb>チリン、チリン――チリン、チリン！</color>",
  ui_story_5020_50200401_47_dialog_content = "あ、なんだ。\nタンスに<color=#FFB400>風鈴</color>が入ってたのね。",
  ui_story_5020_50200401_48_dialog_content = "ヘンなの。神楽鈴を風鈴にしてるの？",
  ui_story_5020_50200401_49_dialog_content = "…ちょっと待って。これ…",
  ui_story_5020_50200401_50_dialog_content = "<color=#e8d9bb>10年前</color>",
  ui_story_5020_50200401_51_dialog_content = "<color=#e8d9bb>チリン、チリン――</color>",
  ui_story_5020_50200401_52_dialog_content = "シーッ、ヨウ…\nいい子だから、声を出さず、ここでじっとしていなさい…",
  ui_story_5020_50200401_53_dialog_content = "外で何があったの？ツキお姉ちゃん、怖いよ…",
  ui_story_5020_50200401_54_dialog_content = "アタシを閉じ込めないで…",
  ui_story_5020_50200401_55_dialog_content = "お願い…",
  ui_story_5020_50200401_56_dialog_content = "<color=#FFB400>タンス</color>の中で眠っててね。\n目が覚めた時には、何もかも終わってるから…",
  ui_story_5020_50200401_57_dialog_content = "ツキお姉ちゃん…",
  ui_story_5020_50200401_58_dialog_content = "<size=45>開けろ！</size>",
  ui_story_5020_50200401_58X1_dialog_content = "（誰か来る！）",
  ui_story_5020_50200401_58X2_dialog_content = "扉の守りを固めてください！\nいかなる不浄も中に入れてはなりません！",
  ui_story_5020_50200401_58X3_dialog_content = "「…我、すなわち陰陽を誦み、この曲、\n汝の魂とともに彼岸へと帰らん…」",
  ui_story_5020_50200401_58X4_dialog_content = "<color=#e8d9bb>チリン、チリン――</color>",
  ui_story_5020_50200401_58X5_dialog_content = "（鬼ばらいの神楽鈴…！）",
  ui_story_5020_50200401_58X6_dialog_content = "<color=#e8d9bb>ドン…</color>",
  ui_story_5020_50200401_59_dialog_content = "待ちなさい！何者です！\n中に入っては…",
  ui_story_5020_50200401_60_dialog_content = "<size=45>退け！</size>",
  ui_story_5020_50200401_61_dialog_content = "（この声は…師匠？）",
  ui_story_5020_50200401_62_dialog_content = "ナギ？",
  ui_story_5020_50200401_63_dialog_content = "その名で呼ぶな、<color=#FFB400>「巫女サマ」</color>。",
  ui_story_5020_50200401_64_dialog_content = "お前にはもう、その資格はない。",
  ui_story_5020_50200401_65_dialog_content = "お前、なぜ幽燭の者たちに降伏を勧めた？",
  ui_story_5020_50200401_66_dialog_content = "巫女になったのは雲島の民のためだと、\n皆のためにより多くの福をもたらすためだと言ったな。",
  ui_story_5020_50200401_67_dialog_content = "…",
  ui_story_5020_50200401_68_dialog_content = "ならばなぜ！？",
  ui_story_5020_50200401_69_dialog_content = "！？",
  ui_story_5020_50200401_70_dialog_content = "ツキ！",
  ui_story_5020_50200401_71_dialog_content = "ナギ、気でも触れたか！？",
  ui_story_5020_50200401_72_dialog_content = "ツキはおぬしの実の姉であろう！",
  ui_story_5020_50200401_73_dialog_content = "皆の者、ナギを止めろ、斬り捨てて構わん！",
  ui_story_5020_50200401_74_dialog_content = "お止めください…！",
  ui_story_5020_50200401_75_dialog_content = "公方様、このようなことは…",
  ui_story_5020_50200401_76_dialog_content = "私たちの足元を流れるこの川は、\n稲田村に沿って、西へと流れております…",
  ui_story_5020_50200401_77_dialog_content = "山麓の庭には…\n白い桜が、すでに咲いていることでしょう…",
  ui_story_5020_50200401_78_dialog_content = "どうか、桜の花を\n血で染めないでくださいませ…",
  ui_story_5020_50200401_79_dialog_content = "私が世を去ったら…\nあの白い桜と一緒に眠らせて下さい…",
  ui_story_5020_50200401_80_dialog_content = "お願い致します、どうか…",
  ui_story_5020_50200401_81_dialog_content = "ツキ、しっかりせい！\n今から余が…",
  ui_story_5020_50200401_82_dialog_content = "「即ち陰陽を…誦み」",
  ui_story_5020_50200401_83_dialog_content = "な…何をする気だ！？",
  ui_story_5020_50200401_84_dialog_content = "ツキ！今のそなたでは身体が持たんぞ！！",
  ui_story_5020_50200401_85_dialog_content = "「この曲…」",
  ui_story_5020_50200401_86_dialog_content = "「わが魂とともに彼岸へと帰らん…」",
  ui_story_5020_50200401_87_dialog_content = "うっ――！？",
  ui_story_5020_50200401_88_dialog_content = "…",
  ui_story_5020_50200401_89_dialog_content = "……",
  ui_story_5020_50200401_90_dialog_content = "こうまでして、そなたは彼奴を守りたいのか…？",
  ui_story_5020_50200401_91_dialog_content = "誰かある！",
  ui_story_5020_50200401_92_dialog_content = "今後、この場は鬼武者に厳重に守らせよ！",
  ui_story_5020_50200401_93_dialog_content = "この女は死ぬまでここに捕らえておく。\n二度と日の目を見せてはならん！",
  ui_story_5020_50200401_94_dialog_content = "はっ…！",
  ui_story_5020_50200401_95_dialog_content = "その他のことは…ツキの言った通りにせよ。",
  ui_story_5020_50200401_96_dialog_content = "心得ました。",
  ui_story_5020_50200401_97_dialog_content = "おぬしは…",
  ui_story_5020_50200401_98_dialog_content = "おぬしはツキを殺した。だが、あやつはおぬしを守ろうとしていた。\n大した皮肉ではないか！？",
  ui_story_5020_50200401_99_dialog_content = "あやつの守りなど必要ない。\nお前を始末することぐらい、私にはたやすいことだ。",
  ui_story_5020_50200401_100_dialog_content = "ナギ、何も分かっておらぬようだな…",
  ui_story_5020_50200401_101_dialog_content = "あやつがあの時、なぜ余に付くことを選んだか…",
  ui_story_5020_50200401_102_dialog_content = "あやつは本来知るべきではなかったことを知った。\nそれを余は黙認した。",
  ui_story_5020_50200401_103_dialog_content = "「鬼祓い」と「鬼使い」、たった1文字の違い…\nそれが雲島に長年続く法と理を表すものだ。",
  ui_story_5020_50200401_104_dialog_content = "あやつは余の立場を理解し、\n雲島の平和を追求するものとして生涯をかけ、そして余を信用したのだ。",
  ui_story_5020_50200401_105_dialog_content = "あやつがおぬしを守ろうとしたのは、\nすべてを知っていたあやつの、無知なおぬしへのあわれみ…",
  ui_story_5020_50200401_106_dialog_content = "そんなものではない！",
  ui_story_5020_50200401_107_dialog_content = "では、なんだと言うのだ？",
  ui_story_5020_50200401_108_dialog_content = "おぬしがとうの昔に捨てた\n姉妹の情だとでも、言いたいのか！？",
  ui_story_5020_50200401_109_dialog_content = "あやつはおぬしと同い年の生まれだと言うのに、\n年にそぐわぬ大きな器で、いつも物事を見ていた…",
  ui_story_5020_50200401_110_dialog_content = "…それを、おぬしが殺めたのだ！",
  ui_story_5020_50200401_111_dialog_content = "あやつが雲島にかけていた望みもろとも、\nおぬしが斬り捨ててしまったのだ！",
  ui_story_5020_50200401_112_dialog_content = "そんなおぬしが、のうのうと生きている資格などあるのか！？",
  ui_story_5020_50200401_113_dialog_content = "…",
  ui_story_5020_50200401_114_dialog_content = "<size=33>あやつはなぜ、最期までおぬしを…</size>",
  ui_story_5020_50200401_115_dialog_content = "すばらしい。うわべだけはご立派だな！",
  ui_story_5020_50200401_116_dialog_content = "自分の企みのために一方的に「利用した」だけのことを、\n「信用」と「理解」などという言葉で飾ろうとするなど…",
  ui_story_5020_50200401_117_dialog_content = "そうやって姉もだましたのだろう？",
  ui_story_5020_50200401_118_dialog_content = "あやつは賢い女だ。",
  ui_story_5020_50200401_119_dialog_content = "余とあやつの目的は同じだった。あやつも余も、この地を守りたいだけだ。\n利用する、されるなどという関係はない。",
  ui_story_5020_50200401_120_dialog_content = "…だが、まあよい。あやつがおぬしに掛けたこの封印も、\nある種の罰であろう。",
  ui_story_5020_50200401_121_dialog_content = "おぬしはここで怒りと恨みにおぼれながら、\n永遠の時を過ごすがよい。",
  ui_story_5020_50200401_122_dialog_content = "お前を殺す！必ず！！",
  ui_story_5020_50200401_123_dialog_content = "その日が来ることを、せいぜい祈っておこう…",
  ui_story_5020_50200401_124_dialog_content = "…ツキ？",
  ui_story_5020_50200401_125_dialog_content = "師匠が…<size=45>巫女のお姉ちゃんを殺したの！？</size>",
  ui_story_5020_50200401_126_dialog_content = "師匠は、そんな人じゃない…",
  ui_story_5020_50200401_127_dialog_content = "あの女も、こうして利用したのか？",
  ui_story_5020_50200401_128_dialog_content = "リンネとやら、お前は道具として選ばれたに過ぎん。",
  ui_story_5020_50200401_129_dialog_content = "前の巫女がどうなったか、知っているか？",
  ui_story_5020_50200401_130_dialog_content = "口入れは無用！",
  ui_story_5020_50200401_131_dialog_content = "皆の者、あやつを取り押さえろ！",
  ui_story_5020_50200401_132_dialog_content = "違う…きっと、何かの間違いよ…",
  ui_story_5020_50200401_133_dialog_content = "うっ、頭が痛い…",
  ui_story_5020_50200401_134_dialog_content = "早くPlayerNameと合流して、\nこのことを伝えないと…！",
  ui_story_5020_50200501_1_dialog_content = "ちょっと！放してよ！ちゃんと話をしましょ！？",
  ui_story_5020_50200501_2_dialog_content = "そうだよ！きっと何かの間違いだ！",
  ui_story_5020_50200501_3_dialog_content = "…",
  ui_story_5020_50200501_4_dialog_content = "ここまで来ればひとまず安全だ。",
  ui_story_5020_50200501_5_dialog_content = "民のことは頼んだ。",
  ui_story_5020_50200501_6_dialog_content = "はい！",
  ui_story_5020_50200501_7_dialog_content = "このいっこうに黙らん奴らは…",
  ui_story_5020_50200501_8_dialog_content = "柱にでもくくりつけておけ。",
  ui_story_5020_50200501_9_dialog_content = "え！？",
  ui_story_5020_50200501_10_dialog_content = "はっ！",
  ui_story_5020_50200501_11_dialog_content = "動くんじゃない！大人しくしろ！",
  ui_story_5020_50200501_12_dialog_content = "話が通じないわ…",
  ui_story_5020_50200501_13_dialog_content = "ちょっと待って、ひとつ聞きたいんだけど！",
  ui_story_5020_50200501_14_dialog_content = "君たちはみんなを守ろうとしてる。\n僕たちもそうだよ！同じ立場じゃないの？",
  ui_story_5020_50200501_15_dialog_content = "そんなわけがないだろう。",
  ui_story_5020_50200501_16_dialog_content = "お前たちは巫女と共にいる。\n我らとは火と水の関係だ。",
  ui_story_5020_50200501_17_dialog_content = "巫女？巫女に何かあるの？",
  ui_story_5020_50200501_18_dialog_content = "なるほど…",
  ui_story_5020_50200501_19_dialog_content = "わたくしの予想が正しければ、\nアメモリはあなた方のお仲間でいらっしゃいますね？",
  ui_story_5020_50200501_20_dialog_content = "おい、巫女。自分のおかれた状況が分かってるのか？",
  ui_story_5020_50200501_21_dialog_content = "お前に質問する資格などない。",
  ui_story_5020_50200501_22_dialog_content = "ふふ…確かに。分かってはおりませんね。",
  ui_story_5020_50200501_23_dialog_content = "でしたらせめて、あなたがたが何者か、\n教えていただけませんか？",
  ui_story_5020_50200501_24_dialog_content = "幽燭の軍というのは、一体どのような…",
  ui_story_5020_50200501_25_dialog_content = "ハハハハ！こいつはケッサクだ！",
  ui_story_5020_50200501_26_dialog_content = "雲島の巫女が我らの名さえ聞いたことがないなんて日が\n来ようとは思わなかったぞ。",
  ui_story_5020_50200501_27_dialog_content = "代替わりが進めば、\n「雲島」の名さえ忘れてしまうのだろうな！",
  ui_story_5020_50200501_28_dialog_content = "お前たちからすれば、\nどうでもいいことなのだから。",
  ui_story_5020_50200501_29_dialog_content = "巫女なんぞ、城でぬくぬくと暮らして、\n「公方様」のご機嫌でも取っていればよいのだ。",
  ui_story_5020_50200501_30_dialog_content = "…",
  ui_story_5020_50200501_31_dialog_content = "どうしてそんなにひどいことを言うの？",
  ui_story_5020_50200501_32_dialog_content = "リンネさんはずっと江富城の人たちを守ってきたわ。\nそれはあなたたちだって見たでしょ！",
  ui_story_5020_50200501_33_dialog_content = "守る？言葉でごまかそうったって、そうは行くか！",
  ui_story_5020_50200501_34_dialog_content = "巫女にとっちゃ、\n飼ってたネズミが飼いネコにかみ殺されただけのことだ。",
  ui_story_5020_50200501_35_dialog_content = "そんなのは「守る」と言わない。\n「猿芝居」と言うんだ。",
  ui_story_5020_50200501_36_dialog_content = "「猿芝居」？どういうこと…？",
  ui_story_5020_50200501_37_dialog_content = "お前たち、この町中の鬼はどこから来たか知ってるか？",
  ui_story_5020_50200501_38_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5020_50200501_39_dialog_content = "巫女、あんたなら陰陽の変化のことはよく分かってるだろう。\n皆に話してやれよ。",
  ui_story_5020_50200501_40_dialog_content = "…陰の気が極まりし時、未練や恨みを抱く魂がさまよったままでいると、\n鬼の姿となって現れます。",
  ui_story_5020_50200501_41_dialog_content = "なら、どうやって「陰が極まる」んだ？\n何もないのに突然起こるのか？",
  ui_story_5020_50200501_42_dialog_content = "…",
  ui_story_5020_50200501_43_dialog_content = "答えられないなら、俺が教えてやるよ。\n<color=#FFB400>人の手で引き起こす</color>んだ。",
  ui_story_5020_50200501_44_dialog_content = "雲島にはいにしえから伝わる、\n3つの<color=#FFB400>霊器</color>がある。",
  ui_story_5020_50200501_45_dialog_content = "陽の霊器であり、鬼を斬る剣「<color=#FFB400>天雲斬</color>」は、\nどこにいったか分からない。",
  ui_story_5020_50200501_46_dialog_content = "陰陽を調和する「<color=#FFB400>斥鬼凌人</color>」のまが玉は、\n我々幽燭の軍が持っている。",
  ui_story_5020_50200501_47_dialog_content = "そして、陰の霊器「<color=#FFB400>雲照鏡</color>」は、\nずっと将軍が握っているのだ。",
  ui_story_5020_50200501_48_dialog_content = "将軍がリンネさんの手から奪った鏡ね…！",
  ui_story_5020_50200501_49_dialog_content = "「陰の雲、日をおおえば、冥土、人の世に現れるがごとし…」",
  ui_story_5020_50200501_50_dialog_content = "つまり、鬼が好き放題してる今の状況を作りだせるのは、\n「<color=#FFB400>雲照鏡</color>」だけってことだ。",
  ui_story_5020_50200501_51_dialog_content = "フン…それなら、黒幕が誰かは、言わずと知れたことだろう！？",
  ui_story_5020_50200501_52_dialog_content = "…実は、僕たちも同じような推測をしてたんだ。",
  ui_story_5020_50200501_53_dialog_content = "ただ、1つつじつまの合わないことがある。",
  ui_story_5020_50200501_54_dialog_content = "将軍が鬼を操ってるなら、\nなんで将軍は鬼ばらいの巫女を育ててたの？",
  ui_story_5020_50200501_55_dialog_content = "だから言っただろ、「猿芝居」だと。",
  ui_story_5020_50200501_56_dialog_content = "鬼は将軍の支配を助ける。\n代わりに巫女が、人の心をつかむ。",
  ui_story_5020_50200501_57_dialog_content = "「人の心をつかむ」？",
  ui_story_5020_50200501_58_dialog_content = "将軍が鬼を操って、\n雲島の人にじわじわと恐怖を植え付けていく…",
  ui_story_5020_50200501_59_dialog_content = "だが、恐怖だけじゃ雲島は治められない。\n人の操り方をよく分かってる奴らなら、知ってて当然だろうな。",
  ui_story_5020_50200501_60_dialog_content = "だから、巫女を育てるんだ。\n巫女は民の前に出て、恐怖の対象である鬼に立ち向かってみせる。",
  ui_story_5020_50200501_61_dialog_content = "民は巫女を頼る。巫女は将軍に従う。\nそれが奴の思い描く統治のしくみってことだ。",
  ui_story_5020_50200501_62_dialog_content = "だが、そんな簡単にいくもんじゃない。",
  ui_story_5020_50200501_63_dialog_content = "そんな猿芝居にだまされるほど、\n雲島の者はバカじゃない。",
  ui_story_5020_50200501_64_dialog_content = "お前ら巫女は陰と陽を調和し、鬼をはらうとか言うが、\n何代経っても、鬼の災いが収まる様子なんてないじゃないか。",
  ui_story_5020_50200501_65_dialog_content = "…",
  ui_story_5020_50200501_66_dialog_content = "ここが「江富」なんて名前じゃないことを\n俺たちは忘れちゃいない。",
  ui_story_5020_50200501_67_dialog_content = "どんなに高くて立派な城を立てようが、\nどれだけの金銀財宝を持っていようが…",
  ui_story_5020_50200501_68_dialog_content = "侵略者はいつまで経っても侵略者だ。",
  ui_story_5020_50200501_69_dialog_content = "真に雲島を守れるのは、俺たち幽燭の軍だけだ。",
  ui_story_5020_50200501_70_dialog_content = "俺たちはここで生まれ育った人間だからな。",
  ui_story_5020_50200501_71_dialog_content = "侵略者？君たちには、本島の人たちがそう見えてるの…？",
  ui_story_5020_50200501_72_dialog_content = "当然だ。雲島の歴史を知らないのか？",
  ui_story_5020_50200501_73_dialog_content = "ヘッ、それもそうか。\n雲島の本当の歴史なんて、今じゃどこで聞けるっていうんだろうな。",
  ui_story_5020_50200501_74_dialog_content = "（前にアンズとモモが話してくれたけど…）",
  ui_story_5020_50200501_75_dialog_content = "（この人たちの知ってる歴史とは、また違うかもしれない）",
  ui_story_5020_50200501_76_dialog_content = "ごめん、僕たちは外から来たから、\n聞いたことないんだ。",
  ui_story_5020_50200501_77_dialog_content = "なら、今日の俺は気分がいい。\nほどこし代わりに聞かせてやろう。",
  ui_story_5020_50200501_78_dialog_content = "何年も前…本島の武士が踏み込んでくる前のことだ。\n雲島は今よりもさらに美しい場所だった。",
  ui_story_5020_50200501_79_dialog_content = "島には何の不足もなく、争いごともなかった。\n唯一、たまに鬼やら霊やらが出てくるのが怖いぐらいだった。",
  ui_story_5020_50200501_80_dialog_content = "幽燭の軍もその頃、\n鬼と戦い、雲島の平和を守るために誕生したのだ。",
  ui_story_5020_50200501_81_dialog_content = "だが、結局この地の平和は鬼じゃなく、人に壊された。",
  ui_story_5020_50200501_82_dialog_content = "本島の奴らは昔から、雲島という肥えた地を自分のものにしようと企んでいたんだ。\nそれで、初代の将軍が派遣されてきた。",
  ui_story_5020_50200501_83_dialog_content = "幽燭の軍は命がけで抵抗した。\nだが、もともと戦争の経験なんかない。",
  ui_story_5020_50200501_84_dialog_content = "当然、将軍は連戦連勝だ。\nそれでも雲島を完全に飲みこむことは、なかなかできなかった。",
  ui_story_5020_50200501_85_dialog_content = "それで、奴らは最低の方法に手を染めたんだ。\n将軍は鬼を操る方法を知り、人ではない化け物を戦いに持ち込んだ。",
  ui_story_5020_50200501_86_dialog_content = "戦争をしてた時代だ。\n未練を抱いてさまよう魂なんか、どこにもあふれてたさ。",
  ui_story_5020_50200501_87_dialog_content = "鬼は幽燭の軍を壊滅させ、雲島は落ちた。それから将軍は海辺に江富城を建てた。\n自分がこの地を統治すると宣言するためにな。",
  ui_story_5020_50200501_88_dialog_content = "落ちのびた幽燭の残党は地下に身を隠し、\nその時の恨みを胸に刻んで、代々伝えてきた。",
  ui_story_5020_50200501_89_dialog_content = "俺たちは戦いの中で、待つことを学んだ。\n待って…時が来たら、失ったすべてを取り戻すんだ。",
  ui_story_5020_50200501_90_dialog_content = "（それが雲島の争いの真相…）",
  ui_story_5020_50200501_91_dialog_content = "（人と鬼の対立のウラで、人同士の戦いが隠れてたんだ…）",
  ui_story_5020_50200501_92_dialog_content = "その時が…",
  ui_story_5020_50200501_93_dialog_content = "もうすぐ、来る。",
  ui_story_5020_50200501_94_dialog_content = "お頭、民草は落ち着かせました。",
  ui_story_5020_50200501_95_dialog_content = "この後は…",
  ui_story_5020_50200501_96_dialog_content = "分かった、あっちで話そう。",
  ui_story_5020_50200501_97_dialog_content = "…",
  ui_story_5020_50200501_98_dialog_content = "先程の話、真実だとお考えですか？",
  ui_story_5020_50200501_99_dialog_content = "私にもわかりません…\n情報がまだ消化しきれてなくて…",
  ui_story_5020_50200501_100_dialog_content = "わたくしはずっと、ただ1つの単純な目的のために\n行動していると思っていました…",
  ui_story_5020_50200501_101_dialog_content = "養父の言うことを聞いて、江富の人々を守るのだと…",
  ui_story_5020_50200501_102_dialog_content = "ですが…",
  ui_story_5020_50200501_103_dialog_content = "その2つは矛盾することだったようです…",
  ui_story_5020_50200501_104_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5020_50200501_105_dialog_content = "わたくしは、ただ「猿芝居」を\n演じさせられていただけなのでしょうか？",
  ui_story_5020_50200501_106_dialog_content = "あ、あの人たちの話が真実だって決まったわけじゃ…",
  ui_story_5020_50200501_107_dialog_content = "そもそも、私たちを有無も言わせず縛り上げるような奴らよ？",
  ui_story_5020_50200501_108_dialog_content = "そうでしょ？PlayerName…",
  ui_story_5020_50200501_109_dialog_content = "…どうしたの？考えごと？",
  ui_story_5020_50200501_110_dialog_content = "シーッ…",
  ui_story_5020_50200501_111_dialog_content = "今、盗み聞きしてるんだ…",
  ui_story_5020_50200501_112_dialog_content = "盗み聞き！？",
  ui_story_5020_50200501_113_dialog_content = "面白そうね！私も聞きたい！",
  ui_story_5020_50200501_114_dialog_content = "じゃあ、もう少し寄って。",
  ui_story_5020_50200501_115_dialog_content = "ええ。",
  ui_story_5020_50200501_116_dialog_content = "お頭、もう行く所がありません…",
  ui_story_5020_50200501_117_dialog_content = "町はもう鬼だらけで、\n他の場所にいる仲間とも連絡がつかず…",
  ui_story_5020_50200501_118_dialog_content = "分かっている。ここを死守するしかあるまい。",
  ui_story_5020_50200501_119_dialog_content = "アメモリ様が頭領を救い出したとのことでしたが…",
  ui_story_5020_50200501_120_dialog_content = "お二人は…助けに来てくださるでしょうか？",
  ui_story_5020_50200501_121_dialog_content = "あの「冥土の幽刀」が来てくださるなら、\n鬼がいくら出ようと怖がることはない！",
  ui_story_5020_50200501_122_dialog_content = "（やっぱり、アメモリの仲間だったのね！）",
  ui_story_5020_50200501_123_dialog_content = "（うん。しかも、アメモリはけっこう上の立場みたいだ）",
  ui_story_5020_50200501_124_dialog_content = "腰抜けめ、幽燭の者が援軍に頼ることなどない！",
  ui_story_5020_50200501_125_dialog_content = "例えおのれ一人となったとしても、\n最後まで戦い抜かねばならんのだ。",
  ui_story_5020_50200501_126_dialog_content = "それはつまり、お二人が…",
  ui_story_5020_50200501_127_dialog_content = "頭領とアメモリ様には他にやるべきことがあるのだ。",
  ui_story_5020_50200501_128_dialog_content = "俺があれこれ心配しても何ともならんのだ。\nお前なら、なおさらだ。",
  ui_story_5020_50200501_129_dialog_content = "（そうだ、アメモリ…今どうしてるんだろう…）",
  ui_story_5020_50200501_130_dialog_content = "（心配いらないわ。アメモリは強いし、きっと大丈夫よ）",
  ui_story_5020_50200501_131_dialog_content = "…",
  ui_story_5020_50200501_132_dialog_content = "頭領が救出されたと聞いて、皆興奮しています。",
  ui_story_5020_50200501_133_dialog_content = "でも…その頭領が、顔さえ見せてくれません。",
  ui_story_5020_50200501_134_dialog_content = "仲間の中には、知らせはウソだと言う者も大勢います。",
  ui_story_5020_50200501_135_dialog_content = "しかも…",
  ui_story_5020_50200501_136_dialog_content = "10年も経ってるんだから、\n頭領はとうの昔に我々のことなど忘れてるって言う奴も…",
  ui_story_5020_50200501_137_dialog_content = "…",
  ui_story_5020_50200501_138_dialog_content = "分かっている。",
  ui_story_5020_50200501_139_dialog_content = "<color=#e8d9bb>ガタッ――</color>",
  ui_story_5020_50200501_140_dialog_content = "（！？）",
  ui_story_5020_50200501_141_dialog_content = "何事だ！？",
  ui_story_5020_50200501_142_dialog_content = "<color=#e8d9bb>バンッ！</color>",
  ui_story_5020_50200501_143_dialog_content = "（壁の向こうからだわ！近い！）",
  ui_story_5020_50200501_144_dialog_content = "来るぞ！！",
  ui_story_5020_50200501_145_dialog_content = "<color=#e8d9bb>ドカン！！</color>",
  ui_story_5020_50200501_146_dialog_content = "<anim type=Shake><size=45>グアアア――！</size></anim>",
  ui_story_5020_50200501_147_dialog_content = "もうここまで来たか…",
  ui_story_5020_50200501_148_dialog_content = "まあ、いい。\n遅かれ早かれ、こうなることは分かっていた。",
  ui_story_5020_50200501_149_dialog_content = "幽燭の兄弟たちよ！",
  ui_story_5020_50200501_150_dialog_content = "おうっ！！！",
  ui_story_5020_50200501_151_dialog_content = "ふるい立て！",
  ui_story_5020_50200501_152_dialog_content = "悪霊悪鬼どもを冥土に返してやろうぞ！",
  ui_story_5020_50200501_153_dialog_content = "大変だ、鬼が来た！",
  ui_story_5020_50200501_154_dialog_content = "ええ！？どうするの！？",
  ui_story_5020_50200501_155_dialog_content = "縛られてるんじゃ、何もできないわ！",
  ui_story_5020_50200501_156_dialog_content = "<size=45>ねえ、誰か！！僕たちの縄をほどいて！！</size>",
  ui_story_5020_50200501_157_dialog_content = "<size=45>僕たちなら力になれる！！</size>",
  ui_story_5020_50200501_158_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5020_50200501_159_dialog_content = "…聞こえないのかな？",
  ui_story_5020_50200501_160_dialog_content = "感知能力を使ってみたら？",
  ui_story_5020_50200501_161_dialog_content = "あ、その手があった…",
  ui_story_5020_50200501_162_dialog_content = "<color=#e8d9bb>ドカン！！</color>",
  ui_story_5020_50200501_163_dialog_content = "<anim type=Shake>グオォ――</anim>",
  ui_story_5020_50200501_164_dialog_content = "まずいわ、よりによってこんな時に…",
  ui_story_5020_50200501_165_dialog_content = "どんどん近づいてくるよ！？",
  ui_story_5020_50200501_166_dialog_content = "今から助けを呼んで…間に合うかな？",
  ui_story_5020_50200501_167_dialog_content = "私に聞かないでくれる？",
  ui_story_5020_50200501_168_dialog_content = "ふふ…縄さえ解ければよいのでございます。",
  ui_story_5020_50200501_169_dialog_content = "人にほどいてもらえないのでしたら、\n鬼にほどかせるとしましょう。",
  ui_story_5020_50200501_170_dialog_content = "それって、どういう…",
  ui_story_5020_50200501_170X1_dialog_content = "<anim type=Shake>グゥ――</anim>",
  ui_story_5020_50200501_170X2_dialog_content = "縄より先に僕らがバラバラにされそうだよ！？",
  ui_story_5020_50200501_170X3_dialog_content = "まずは隠れていた方がよろしいかと。",
  ui_story_5020_50200501_171_dialog_content = "<color=#e8d9bb>バン――！</color>",
  ui_story_5020_50200501_172_dialog_content = "<anim type=Shake>グアア――</anim>",
  ui_story_5020_50200501_173_dialog_content = "ご覧ください…",
  ui_story_5020_50200501_174_dialog_content = "時として、人より鬼の方が話が通じることもございます。",
  ui_story_5020_50200502_1_dialog_content = "お頭、どの道も敵だらけです！",
  ui_story_5020_50200502_2_dialog_content = "囲まれました！",
  ui_story_5020_50200502_3_dialog_content = "今しがた襲ってきたばかりだというのに、\nもう取り囲まれているとは…",
  ui_story_5020_50200502_4_dialog_content = "これほど素早い布陣、偶然ではあるまい。",
  ui_story_5020_50200502_5_dialog_content = "お頭、それはつまり…",
  ui_story_5020_50200502_6_dialog_content = "我々幽燭の軍は鬼と長年戦っているが、\nこのような追い詰められ方があったか？",
  ui_story_5020_50200502_7_dialog_content = "鬼の感覚は鈍いのだ。\n戦いの匂いを嗅ぎつけて寄って来たにしては…速すぎる。",
  ui_story_5020_50200502_8_dialog_content = "敵の位置をあらかじめ知って囲んでおき、\nそれから奇襲を仕掛けたのでなければ、こうはならん。",
  ui_story_5020_50200502_9_dialog_content = "おそらく、裏で糸を引いている者がいる…",
  ui_story_5020_50200502_10_dialog_content = "あの将軍がじっとしていられなかったということか？",
  ui_story_5020_50200502_11_dialog_content = "お頭、どうしますか！？",
  ui_story_5020_50200502_12_dialog_content = "まずは状況を安定させねばならん。\n打開の方法がないか、探るのだ。",
  ui_story_5020_50200502_13_dialog_content = "少なくとも、民を江富城から避難させられるよう…",
  ui_story_5020_50200502_14_dialog_content = "（君たち、後ろに気を付けて！）",
  ui_story_5020_50200502_15_dialog_content = "！？",
  ui_story_5020_50200502_16_dialog_content = "誰の声だ！？",
  ui_story_5020_50200502_17_dialog_content = "（僕だよ、さっき君たちに柱に括りつけられた…）",
  ui_story_5020_50200502_18_dialog_content = "縄を抜けたのか！？",
  ui_story_5020_50200502_19_dialog_content = "話をするつもりなら、隠れてないで出てこい！",
  ui_story_5020_50200502_20_dialog_content = "（ええと…実は、君の近くにはいないんだ）",
  ui_story_5020_50200502_21_dialog_content = "（僕の能力を使って、遠くから話しかけてるんだよ）",
  ui_story_5020_50200502_22_dialog_content = "どういうことだ？",
  ui_story_5020_50200502_23_dialog_content = "（つまり…ええと、その話は後にしよう。\n今は大事なことじゃない。）",
  ui_story_5020_50200502_24_dialog_content = "（大事なのは、僕たちが君たちの助けになれるってことだけだ）",
  ui_story_5020_50200502_25_dialog_content = "助け！？フン、幽燭の軍は\n捕虜の助けまで借りるほど落ちぶれちゃいない！",
  ui_story_5020_50200502_26_dialog_content = "（こんな状況だし、強がらずに、使えるものは使おうよ。）",
  ui_story_5020_50200502_27_dialog_content = "チッ…",
  ui_story_5020_50200502_28_dialog_content = "（もうすぐ右の街道から鬼が出てくるよ）",
  ui_story_5020_50200502_29_dialog_content = "右？",
  ui_story_5020_50200502_30_dialog_content = "<anim type=Shake>グゥ――</anim>",
  ui_story_5020_50200502_31_dialog_content = "本当に右から…",
  ui_story_5020_50200502_32_dialog_content = "皆の者！敵は右だ、かかれ！",
  ui_story_5020_50200502_33_dialog_content = "（まぁ、実は左側にもいるんだけど…）",
  ui_story_5020_50200502_34_dialog_content = "<anim type=Shake>グゥ――</anim>",
  ui_story_5020_50200502_35_dialog_content = "そういうことは早く言え！！",
  ui_story_5020_50200502_36_dialog_content = "（左側は気にしないで。僕たちが片づける。）",
  ui_story_5020_50200502_37_dialog_content = "お礼は要らないわ！",
  ui_story_5020_50200502_38_dialog_content = "なぜ助けた？",
  ui_story_5020_50200502_39_dialog_content = "巫女がいるのだ。\n将軍はお前たちを悪いようにはしないだろう。",
  ui_story_5020_50200502_40_dialog_content = "（話せば長くなるんだけど、\n実は僕たちと将軍も「ちょっと」考えの違いがあって…）",
  ui_story_5020_50200502_41_dialog_content = "考え方の違い？",
  ui_story_5020_50200502_42_dialog_content = "（要は戦いになったってことなんだけど…\n僕にはうまく説明できないや）",
  ui_story_5020_50200502_43_dialog_content = "（君の話を聞いて、ようやく分かったんだ。\n雲島の争いは、思ってたよりずっと複雑だった）",
  ui_story_5020_50200502_44_dialog_content = "（僕たちみたいなよそ者が口を挟めるようなことじゃない…）",
  ui_story_5020_50200502_45_dialog_content = "（でも、鬼は人の敵だ。そのことに間違いはないはず）",
  ui_story_5020_50200502_46_dialog_content = "（だから、少なくとも今は、一緒に戦おう！）",
  ui_story_5020_50200502_47_dialog_content = "…",
  ui_story_5020_50200502_48_dialog_content = "わかった。",
  ui_story_5020_50200502_49_dialog_content = "ひとまず信じるとしよう。\nお前も鬼に立ち向かう戦士だというのなら。",
  ui_story_5020_50200502_50_dialog_content = "リンネさん！大丈夫ですか？",
  ui_story_5020_50200502_51_dialog_content = "…ええ、ありがとうございます。",
  ui_story_5020_50200502_52_dialog_content = "どこか具合が悪いんですか？",
  ui_story_5020_50200502_53_dialog_content = "今まで通りなら、これぐらいの鬼、\nとっくに消せてましたよね。",
  ui_story_5020_50200502_54_dialog_content = "…",
  ui_story_5020_50200502_55_dialog_content = "申し訳ございません。ご心配をおかけしました。",
  ui_story_5020_50200502_56_dialog_content = "ただ少し、集中を欠いているだけでございます。",
  ui_story_5020_50200502_57_dialog_content = "さっきの話のせいですか？",
  ui_story_5020_50200502_58_dialog_content = "…はい…",
  ui_story_5020_50200502_59_dialog_content = "「猿芝居」という言葉がどうしても\n頭から離れないのでございます。",
  ui_story_5020_50200502_60_dialog_content = "その言葉が頭の中から消せず、\nどうしても手に力が入らないのです…",
  ui_story_5020_50200502_61_dialog_content = "わたくしは…戦う理由を\n見失ってしまったのかもしれません…",
  ui_story_5020_50200502_62_dialog_content = "お城で将軍と戦った時に\nもう心を決めたものとばかり…",
  ui_story_5020_50200502_63_dialog_content = "あの時のわたくしはただ、怒っていただけでございます。\nそして、分かっていなかったのです。",
  ui_story_5020_50200502_64_dialog_content = "ですが、今は得心が行きました。",
  ui_story_5020_50200502_65_dialog_content = "納得ができたってことですか？何に対して？",
  ui_story_5020_50200502_66_dialog_content = "公方様は、わたくしが鬼をはらうことを\n望んだことはございませんでした。",
  ui_story_5020_50200502_67_dialog_content = "ただ、わたくしが巫女の衣装をまとい、\n人々の前で美しい「舞」を踊ることだけを望んでいたのでございます。",
  ui_story_5020_50200502_68_dialog_content = "わたくしはずっと「猿芝居」の中に生きていただけ。\nそのくせ、己は「巫女」だと自負していたのでございます。",
  ui_story_5020_50200502_69_dialog_content = "こうして舞台の外に投げ出され、\n己の演じてきた役割が何であったかを聞かされた、今…",
  ui_story_5020_50200502_70_dialog_content = "わたくしは…何を演じれば\nよいのでございましょう…？",
  ui_story_5020_50200502_71_dialog_content = "わたくしに望まれている役か、\nそれとも、己の思う役を演じるべきなのか…",
  ui_story_5020_50200601_1_dialog_content = "戦えない者は全員、俺についてこい！",
  ui_story_5020_50200601_2_dialog_content = "どうしてまた逃げるの？\nどこへ行くつもり？",
  ui_story_5020_50200601_3_dialog_content = "界町からどんどん遠ざかってるよ！？",
  ui_story_5020_50200601_4_dialog_content = "江富城を離れるんだ！",
  ui_story_5020_50200601_5_dialog_content = "え！？なんで！？",
  ui_story_5020_50200601_6_dialog_content = "野原の真ん中じゃ商売なんかできないよ！",
  ui_story_5020_50200601_7_dialog_content = "鬼どもが「奴」の命令で町の中に押し寄せてるんだ。\n今は外の方が安全だ。",
  ui_story_5020_50200601_8_dialog_content = "え…？",
  ui_story_5020_50200601_9_dialog_content = "モモ、奴って、将軍様のこと？",
  ui_story_5020_50200601_10_dialog_content = "そうみたいだけど、でも、どうしてだろ？",
  ui_story_5020_50200601_11_dialog_content = "まさか、あたしたち全員を殺す気…？",
  ui_story_5020_50200601_12_dialog_content = "それはないよ…だって、将軍様は江富城を治めてるんだよ？",
  ui_story_5020_50200601_13_dialog_content = "わたしたちがみんな死んじゃったら、\n仕事が無くなるじゃない？",
  ui_story_5020_50200601_14_dialog_content = "代わりに鬼を統治するとか？",
  ui_story_5020_50200601_15_dialog_content = "コワイこと言わないでよ！",
  ui_story_5020_50200601_16_dialog_content = "<color=#e8d9bb>バンッ！</color>",
  ui_story_5020_50200601_17_dialog_content = "！？",
  ui_story_5020_50200601_18_dialog_content = "<size=45>お前たち、止まれ！</size>",
  ui_story_5020_50200601_19_dialog_content = "！！！",
  ui_story_5020_50200601_20_dialog_content = "まずいぞ…",
  ui_story_5020_50200601_21_dialog_content = "このような夜更けに、\n大勢でどこへ行こうというのだ？",
  ui_story_5020_50200601_21X1_dialog_content = "<color=#e8d9bb>江富城の大通り、屋根の上</color>",
  ui_story_5020_50200601_21X2_dialog_content = "けっこう高い！き、気をつけて！",
  ui_story_5020_50200601_21X3_dialog_content = "耐えてくださいませ。\n遠回りせず、戦いを避けられる道は屋根の上しかないのです。",
  ui_story_5020_50200601_22_dialog_content = "PlayerName、道がなくなったわ！",
  ui_story_5020_50200601_23_dialog_content = "どうする？",
  ui_story_5020_50200601_24_dialog_content = "こうなったら…",
  ui_story_5020_50200601_25_dialog_content = "飛び降りるのでございますか？",
  ui_story_5020_50200601_26_dialog_content = "うん…",
  ui_story_5020_50200601_27_dialog_content = "分かったわ！",
  ui_story_5020_50200601_28_dialog_content = "え！？みんな思い切りがいいなぁ…",
  ui_story_5020_50200601_29_dialog_content = "ま、また取り残されちゃった…",
  ui_story_5020_50200601_30_dialog_content = "急いで、PlayerName！",
  ui_story_5020_50200601_31_dialog_content = "鬼に捕まってからじゃ、遅いわよ！",
  ui_story_5020_50200601_32_dialog_content = "分かったよ！",
  ui_story_5020_50200601_33_dialog_content = "ふぅ…",
  ui_story_5020_50200601_34_dialog_content = "ええい！！",
  ui_story_5020_50200601_35_dialog_content = "<anim type=Shake><size=45>うわあぁぁぁ…</size></anim>",
  ui_story_5020_50200601_36_dialog_content = "<color=#e8d9bb>ドサッ</color>",
  ui_story_5020_50200601_37_dialog_content = "ま、まだ…生きてる？",
  ui_story_5020_50200601_38_dialog_content = "目を閉じてたら、安全に着地できないでしょ…",
  ui_story_5020_50200601_39_dialog_content = "私が受け止められてよかったわね。",
  ui_story_5020_50200601_40_dialog_content = "バイスがいてくれて助かったよ…",
  ui_story_5020_50200601_41_dialog_content = "まずは自分で立ってから話してくれる？",
  ui_story_5020_50200601_42_dialog_content = "あっ…",
  ui_story_5020_50200601_43_dialog_content = "それで、これから…",
  ui_story_5020_50200601_44_dialog_content = "また会ったな、異郷人。",
  ui_story_5020_50200601_45_dialog_content = "お前たち、ずっと屋根の上に隠れていたのか。",
  ui_story_5020_50200601_46_dialog_content = "うん…",
  ui_story_5020_50200601_47_dialog_content = "君たちとは距離を取っておいた方がよさそうだったから。",
  ui_story_5020_50200601_48_dialog_content = "でも今は、そんな余裕もない…",
  ui_story_5020_50200601_49_dialog_content = "ほう、助けて欲しいという訳か？",
  ui_story_5020_50200601_50_dialog_content = "こんな時でも、まだ強気みたいね…",
  ui_story_5020_50200601_51_dialog_content = "いや、君たちに迷惑をかけるつもりはないよ。",
  ui_story_5020_50200601_52_dialog_content = "ただ、伝えておきたいことがあるんだ。\nもうすぐ鬼が屋根を伝って、ここにくる。",
  ui_story_5020_50200601_53_dialog_content = "君たちに抵抗する気がないなら、\n僕たちはこのまま逃げる。",
  ui_story_5020_50200601_54_dialog_content = "でも、もしまだ戦う気が残ってるなら、\n僕たちも喜んで手助けするよ。",
  ui_story_5020_50200601_55_dialog_content = "フン、口のうまい小僧だ。",
  ui_story_5020_50200601_56_dialog_content = "戦場でも、その威勢を保てるといいがな。",
  ui_story_5020_50200601_57_dialog_content = "すぐに分かるよ！",
  ui_story_5020_50200601_58_dialog_content = "ただ、先に言っておくが、\nそいつには離れていてもらおう。",
  ui_story_5020_50200601_59_dialog_content = "巫女と肩を並べるつもりはない。",
  ui_story_5020_50200601_60_dialog_content = "…",
  ui_story_5020_50200601_61_dialog_content = "え？でも、リンネは…",
  ui_story_5020_50200601_62_dialog_content = "よろしゅうございます。",
  ui_story_5020_50200601_63_dialog_content = "皆様がかばってくださるというのでしたら…",
  ui_story_5020_50200601_64_dialog_content = "ありがたきことでございます。",
  ui_story_5020_50200601_65_dialog_content = "チッ…",
  ui_story_5020_50200601_66_dialog_content = "<color=#e8d9bb>ドスン！</color>",
  ui_story_5020_50200601_67_dialog_content = "<anim type=Shake>グゥ――</anim>",
  ui_story_5020_50200601_68_dialog_content = "…仕方ない。",
  ui_story_5020_50200601_69_dialog_content = "幽燭の者ども！戦いに備えろ！",
  ui_story_5020_50200602_1_dialog_content = "あとどれだけいる！？",
  ui_story_5020_50200602_2_dialog_content = "あと少しだ…辺りのエネルギーが弱くなってる…",
  ui_story_5020_50200602_3_dialog_content = "バイス！",
  ui_story_5020_50200602_4_dialog_content = "分かってるわ！",
  ui_story_5020_50200602_5_dialog_content = "大丈夫？まだ戦える？",
  ui_story_5020_50200602_6_dialog_content = "誰と話してるつもりだ、小僧？",
  ui_story_5020_50200602_7_dialog_content = "まずは自分の身を守れ。",
  ui_story_5020_50200602_8_dialog_content = "もう身体がボロボロじゃない。\n隠してても感知で分かるよ。",
  ui_story_5020_50200602_9_dialog_content = "その感知とやらがホンモノなら、\n今の俺の魂がどれだけ激しく燃えてるかも分かるだろ。",
  ui_story_5020_50200602_10_dialog_content = "身体がダメになったら、\n気持ちがいくらあっても無意味だよ？",
  ui_story_5020_50200602_11_dialog_content = "俺たちが立ち向かっている相手だって、\n肉体がなくなっても、戦える奴らだ。",
  ui_story_5020_50200602_12_dialog_content = "わずかでも魂が残ってるからな。",
  ui_story_5020_50200602_13_dialog_content = "雲島ではいつでも、肉体より精神こそが強く、とうといものなのだ。",
  ui_story_5020_50200602_14_dialog_content = "幽燭の軍が破れようと、皆が討ち死にしようと、\n絶対に抵抗を止めたりはしない！",
  ui_story_5020_50200602_15_dialog_content = "本当に恐ろしいほどの覚悟だね…",
  ui_story_5020_50200602_16_dialog_content = "でも、今はまだ、その必要はないよ。",
  ui_story_5020_50200602_17_dialog_content = "もうすぐ終わるから。",
  ui_story_5020_50200602_18_dialog_content = "フン……",
  ui_story_5020_50200602_19_dialog_content = "これが最後の1匹か。",
  ui_story_5020_50200602_20_dialog_content = "ふぅ――疲れたわ！",
  ui_story_5020_50200602_21_dialog_content = "小僧、この後はどっちへ行けばいい？",
  ui_story_5020_50200602_22_dialog_content = "急いで民たちと合流しなければ…",
  ui_story_5020_50200602_23_dialog_content = "ちょっと待って…安心するのはまだ早いよ！",
  ui_story_5020_50200602_24_dialog_content = "人の群れ…部隊みたいだ。\n誰かがこっちへ来る…",
  ui_story_5020_50200602_25_dialog_content = "人？いったい誰が…",
  ui_story_5020_50200602_26_dialog_content = "<color=#e8d9bb>ザッ…ザッ…</color>",
  ui_story_5020_50200602_27_dialog_content = "僕の予想が正しければ、\n歓迎できる相手じゃないよ…",
  ui_story_5020_50200602_28_dialog_content = "<color=#e8d9bb>ザッ…ザッ…ザッ…</color>",
  ui_story_5020_50200602_29_dialog_content = "謀反人の残党ども。",
  ui_story_5020_50200602_30_dialog_content = "貴様らは江富を混乱におとしいれた。",
  ui_story_5020_50200602_31_dialog_content = "今日こそ…",
  ui_story_5020_50200602_32_dialog_content = "<size=40>貴様らを一網打尽にしてやる！！</size>",
  ui_story_5020_50200602_33_dialog_content = "さむらい！？こんなに大勢！？",
  ui_story_5020_50200602_34_dialog_content = "フン、犬というのは群れるのが好きで困る。",
  ui_story_5020_50200602_35_dialog_content = "大声で吠えることしかできん奴らだ。\n恐れるほどのことはない。",
  ui_story_5020_50200602_36_dialog_content = "皆の者、武器をとれ！",
  ui_story_5020_50200602_37_dialog_content = "待って！",
  ui_story_5020_50200602_38_dialog_content = "あいつらの後ろに…他にもまだ誰かいる…",
  ui_story_5020_50200602_39_dialog_content = "他の？",
  ui_story_5020_50200602_40_dialog_content = "わ、バイス、PlayerName！",
  ui_story_5020_50200602_41_dialog_content = "大丈夫だった！？",
  ui_story_5020_50200602_42_dialog_content = "アンズとモモ？",
  ui_story_5020_50200602_43_dialog_content = "あなたたち、町の人たちと一緒じゃ…",
  ui_story_5020_50200602_44_dialog_content = "父さん…",
  ui_story_5020_50200602_45_dialog_content = "シッ。",
  ui_story_5020_50200602_46_dialog_content = "お前ら…この卑怯者どもめが！",
  ui_story_5020_50200602_47_dialog_content = "罪のない者まで巻き込むつもりか！？",
  ui_story_5020_50200602_48_dialog_content = "それはこちらの台詞だ。",
  ui_story_5020_50200602_49_dialog_content = "幽燭軍の悪党どもは、民を人質に取り、町の外へ向かった。",
  ui_story_5020_50200602_50_dialog_content = "これが貴様らの1つ目の罪。",
  ui_story_5020_50200602_51_dialog_content = "人質？フン、言いがかりにもほどがある！",
  ui_story_5020_50200602_52_dialog_content = "町が襲われた時にはツラも見せなかったくせに、\n今さら何の英雄気取りだ、えらそうに！",
  ui_story_5020_50200602_53_dialog_content = "そのうえ将軍に背き、\n裏で結託し、徒党を組んだ。",
  ui_story_5020_50200602_54_dialog_content = "それが貴様らの第2の罪だ。",
  ui_story_5020_50200602_55_dialog_content = "チッ…",
  ui_story_5020_50200602_56_dialog_content = "平和を乱し、悪事の限りを尽そうとし…",
  ui_story_5020_50200602_57_dialog_content = "禁忌の術を用い、町中に鬼を呼びよせた。",
  ui_story_5020_50200602_58_dialog_content = "それが貴様らの3つ目の罪だ。",
  ui_story_5020_50200602_59_dialog_content = "何ですって！？",
  ui_story_5020_50200602_60_dialog_content = "幽燭軍の人たちはずっと鬼と戦ってたわ！？",
  ui_story_5020_50200602_61_dialog_content = "いや、これは…",
  ui_story_5020_50200602_62_dialog_content = "町の人たちに聞かせるために、\nわざとこんなことを言ってるんだ。",
  ui_story_5020_50200602_63_dialog_content = "お侍様、今おっしゃったことは本当ですか？",
  ui_story_5020_50200602_64_dialog_content = "幽燭軍どもが鬼を！？",
  ui_story_5020_50200602_65_dialog_content = "でも、さっきは皆を助けてたぞ…",
  ui_story_5020_50200602_66_dialog_content = "本当のところがどうかなんて、\n分かったもんじゃない！",
  ui_story_5020_50200602_67_dialog_content = "そうだ、俺たちのような何の権力もない庶民にゃ、\n難しいことなんか分かりゃしない…",
  ui_story_5020_50200602_68_dialog_content = "だから、俺たちをちゃんと守ってくれた奴を信じりゃいいんだ…",
  ui_story_5020_50200602_69_dialog_content = "…",
  ui_story_5020_50200602_70_dialog_content = "侍どもにも人として最低限の一線はあると思っていたが…",
  ui_story_5020_50200602_71_dialog_content = "どうやら、高く見すぎていたらしい。",
  ui_story_5020_50200602_72_dialog_content = "本当に皆をだましおおせると思っているのか？\nこんな卑劣な方法で、白黒までは変えられん！",
  ui_story_5020_50200602_73_dialog_content = "きちんと目を開いて、見るがいい！\n必ず分かる者がいるはずだ！",
  ui_story_5020_50200602_74_dialog_content = "鬼と戦い、死んでいったのは誰か！",
  ui_story_5020_50200602_75_dialog_content = "高い塀の後ろに隠れて、寝ぼけていたのは誰か！",
  ui_story_5020_50200602_76_dialog_content = "今日皆の者が見るのは、逆賊が法に服する姿だ。",
  ui_story_5020_50200602_77_dialog_content = "民を連れ、府城に戻れ。\n罪のない者を巻き込んではならん。",
  ui_story_5020_50200602_78_dialog_content = "また戦いか…",
  ui_story_5020_50200602_79_dialog_content = "急ごう、ここから離れるんだ…",
  ui_story_5020_50200602_80_dialog_content = "何て世の中だ…",
  ui_story_5020_50200602_81_dialog_content = "ちょっと！そっちにはわたしたちの友だちがいるの。\n傷つけないでよ！",
  ui_story_5020_50200602_82_dialog_content = "バイス！PlayerName！早く、あたしたちと一緒に逃げよう…",
  ui_story_5020_50200602_83_dialog_content = "この後は、雲島の人たち同士の争いになりそうよ。\n私たちはどうする？",
  ui_story_5020_50200602_84_dialog_content = "いや、そんな簡単なことじゃなさそうだ。",
  ui_story_5020_50200602_85_dialog_content = "まずは様子を見よう…",
  ui_story_5020_50200602_86_dialog_content = "いいだろう。民草に危害が及ぶことを避けるなら、\n良心の欠片くらいは残っているようだな。",
  ui_story_5020_50200602_87_dialog_content = "江富の平和を守ることが、我らの務めだ。",
  ui_story_5020_50200602_88_dialog_content = "そうか？それは俺たちの務めと思っていたが。",
  ui_story_5020_50200602_89_dialog_content = "貴様らが真に平和を望むなら、抵抗を止め、\n法の裁きに服するがいい。",
  ui_story_5020_50200602_90_dialog_content = "<size=45>ハハハハハ！！</size>",
  ui_story_5020_50200602_91_dialog_content = "将軍の法などには従わん！！",
  ui_story_5020_50200602_92_dialog_content = "むむ、あくまで歯向かうか。ならば報いを受けるがいい！",
  ui_story_5020_50200602_93_dialog_content = "フン、望むところだ！",
  ui_story_5020_50200602_94_dialog_content = "<color=#e8d9bb>チリン――</color>",
  ui_story_5020_50200602_95_dialog_content = "！？",
  ui_story_5020_50200602_96_dialog_content = "！！！",
  ui_story_5020_50200602_97_dialog_content = "申し訳ございません。\n水を差すつもりはなかったのですが…",
  ui_story_5020_50200602_98_dialog_content = "少しだけ、お話しさせていただきたいのです。",
  ui_story_5020_50200602_99_dialog_content = "巫女様！？",
  ui_story_5020_50200602_100_dialog_content = "逆賊どもに囚われていらっしゃったのですか！？",
  ui_story_5020_50200602_101_dialog_content = "我らの手抜かりです。今すぐお助け…",
  ui_story_5020_50200602_102_dialog_content = "あなたたちは、幽燭の者が鬼を呼び寄せたと\nおっしゃっていましたね。",
  ui_story_5020_50200602_103_dialog_content = "そのことに証しはあるのですか？",
  ui_story_5020_50200602_104_dialog_content = "…証し？",
  ui_story_5020_50200602_105_dialog_content = "それをいつ、どこで、どう聞かれたのでしょうか。",
  ui_story_5020_50200602_106_dialog_content = "…",
  ui_story_5020_50200602_107_dialog_content = "巫女様、それがしはしょせん下っ端…\nすべてを知っているわけではございません。",
  ui_story_5020_50200602_108_dialog_content = "しかし、ご安心ください。\nすべては将軍様のおっしゃったことです。",
  ui_story_5020_50200602_109_dialog_content = "そうですか…",
  ui_story_5020_50200602_110_dialog_content = "確かに将軍様がおっしゃったこと。\n間違いなく、他の何者かの作り話ではない、ということですね？",
  ui_story_5020_50200602_111_dialog_content = "間違いはございません。",
  ui_story_5020_50200602_112_dialog_content = "…",
  ui_story_5020_50200602_113_dialog_content = "…分かりました。",
  ui_story_5020_50200602_114_dialog_content = "将軍様にはお礼を申し上げなくては。\nおかげで、わたくしのとるべき立場が分かりました。",
  ui_story_5020_50200602_115_dialog_content = "分かってくださればよいのです。",
  ui_story_5020_50200602_116_dialog_content = "おケガなどなさらないよう、\nどうぞ我らの後ろへおさがりください。",
  ui_story_5020_50200602_117_dialog_content = "<color=#e8d9bb>チリン――</color>",
  ui_story_5020_50200602_118_dialog_content = "いいえ…",
  ui_story_5020_50200602_119_dialog_content = "ここがわたくしの立つべき場でございます。",
  ui_story_5020_50200602_120_dialog_content = "…",
  ui_story_5020_50200602_121_dialog_content = "巫女様、我らの前に立つことが何を意味するか、\nお分かりになっての行いでございますか？",
  ui_story_5020_50200602_122_dialog_content = "はて…？",
  ui_story_5020_50200602_123_dialog_content = "わたくしはただ、元いた場所から動かずにいるだけでございますよ。\nあなたがどこへ行こうと、何をしようと、わたくしには関わりのないこと。",
  ui_story_5020_50200602_124_dialog_content = "戦場の中央でお立ちになる…\n我らを敵に回すと言うも同然です。",
  ui_story_5020_50200602_125_dialog_content = "将軍様を敵に回すということでもございます。",
  ui_story_5020_50200602_126_dialog_content = "わたくしは巫女。\n巫女はいかなる人とも対立したことはございません。",
  ui_story_5020_50200602_127_dialog_content = "他の者がわたくしを敵と見なしているだけのことにございます。",
  ui_story_5020_50200602_128_dialog_content = "将軍様を責めておいでか？",
  ui_story_5020_50200602_129_dialog_content = "責めてはおりません。\nわたくしはやっと、公方様のことが分かったのです。",
  ui_story_5020_50200602_130_dialog_content = "あなた方の言った――\n「幽燭の軍が鬼を呼び寄せた」という言葉のおかげで…",
  ui_story_5020_50200602_131_dialog_content = "…",
  ui_story_5020_50200602_132_dialog_content = "城で鬼を見た時には、分かりませんでした。",
  ui_story_5020_50200602_133_dialog_content = "雲照鏡が鬼を蘇らせた時にも、まだ分かりませんでした。",
  ui_story_5020_50200602_134_dialog_content = "公方様の言うこととなさっていることが違う。わたくしは惑いました。\nどうしてこのようなことをされるのか、分かっておりませんでしたが…",
  ui_story_5020_50200602_135_dialog_content = "あなた方が現れて、その答えがようやく出たのでございます。",
  ui_story_5020_50200602_136_dialog_content = "巫女と鬼は、代々にわたって敵対する者。\nしかし、公方様にとっては、どちらも同じ。",
  ui_story_5020_50200602_137_dialog_content = "敵味方の別などなく、\n陰と陽、一対の道具にすぎない…",
  ui_story_5020_50200602_138_dialog_content = "武力が必要となれば、鬼を使い、敵を制圧する。",
  ui_story_5020_50200602_139_dialog_content = "民の心をつかむ必要があらば、巫女を使い、\n人々の敵意を鬼に向かわせる…",
  ui_story_5020_50200602_140_dialog_content = "巫女様、お分かりにはなりますまい。",
  ui_story_5020_50200602_141_dialog_content = "ええ…ですから、わたくしは、\n己に分かるものを信じることにしたのです。",
  ui_story_5020_50200602_142_dialog_content = "今日まで学んできたすべて、\n巫女としての信条を。",
  ui_story_5020_50200602_143_dialog_content = "わたくしの敵は、鬼…",
  ui_story_5020_50200602_144_dialog_content = "…",
  ui_story_5020_50200602_145_dialog_content = "それこそ、わたくしが今、\nここに立っている理由でございます。",
  ui_story_5020_50200602_146_dialog_content = "あなたの後ろの武者どもは…",
  ui_story_5020_50200602_147_dialog_content = "<color=#FFB400>生者ではない</color>、そうでございますね？",
  ui_story_5020_50200602_148_dialog_content = "…",
  ui_story_5020_50200602_149_dialog_content = "そこまでお分かりなら、\nこれ以上お話しすることもありますまい。",
  ui_story_5020_50200602_150_dialog_content = "…",
  ui_story_5020_50200602_151_dialog_content = "<color=#e8d9bb>チリン――</color>",
  ui_story_5020_50200602_152_dialog_content = "「…我、すなわち陰陽を誦み、この曲、\n汝の魂とともに彼岸へと帰らん…」",
  ui_story_5020_50200701_1_dialog_content = "（鬼武者が真っ黒な波のように押し寄せてくる。\nすさまじい光景に圧倒されて、動けない）",
  ui_story_5020_50200701_2_dialog_content = "（立ち上る波が頂点に達して、今にも落ちて来そうだ）",
  ui_story_5020_50200701_3_dialog_content = "（リンネは道の真ん中に立って、\nたったひとりで波に立ち向かってる）",
  ui_story_5020_50200701_4_dialog_content = "（リンネの目の前に冥土が、背後に人の世が広がっている。\nまるで彼女が境界線にでもなったみたいに…）",
  ui_story_5020_50200701_5_dialog_content = "おや…？",
  ui_story_5020_50200701_6_dialog_content = "幽燭の軍の皆様、\n巫女とは肩を並べないのでは？",
  ui_story_5020_50200701_7_dialog_content = "…",
  ui_story_5020_50200701_8_dialog_content = "それより、巫女にただ守られることの方が\nしゃくに触るもんでな。",
  ui_story_5020_50200701_9_dialog_content = "まあ、残念でございます。",
  ui_story_5020_50200701_10_dialog_content = "皆様が舞台に上がられてしまったら、\nどなたがわたくしの「猿芝居」をご覧になるのでしょうか？",
  ui_story_5020_50200701_11_dialog_content = "「猿芝居」か。耳が痛いな。",
  ui_story_5020_50200701_12_dialog_content = "あなたのお言葉でございますよ。",
  ui_story_5020_50200701_13_dialog_content = "根に持つとは、そうとう気に入ってもらえたみたいだな。",
  ui_story_5020_50200701_14_dialog_content = "ええ、その通りでございます。",
  ui_story_5020_50200701_15_dialog_content = "巫女の敵を名乗られるだけあって、\nわたくしよりも巫女のことを分かっていらっしゃるようです。",
  ui_story_5020_50200701_16_dialog_content = "何もかも知った時には、\nきっと自分のことが嫌いになっちまうだろうな。",
  ui_story_5020_50200701_17_dialog_content = "ふふ…推し測りはなさらぬ方がよろしいでしょう。",
  ui_story_5020_50200701_18_dialog_content = "「猿芝居」という言葉…確かに鋭いものですが、\n嫌いというわけではありません。",
  ui_story_5020_50200701_19_dialog_content = "操り人形に甘んじる、と？",
  ui_story_5020_50200701_20_dialog_content = "あなた方が関心を持っているのは、\n誰が人形を操っているか…",
  ui_story_5020_50200701_21_dialog_content = "ですが、わたくしが気にしていることは、\n人形がきちんと芝居を演じられているかだけでございます。",
  ui_story_5020_50200701_22_dialog_content = "お前の先代はとんだダイコン役者だったな。",
  ui_story_5020_50200701_23_dialog_content = "そうですか…\nわたくしは、演じきれると思われますか？",
  ui_story_5020_50200701_24_dialog_content = "…",
  ui_story_5020_50200701_25_dialog_content = "…それが巫女を殺（あや）めることにこだわる理由ですか？",
  ui_story_5020_50200701_26_dialog_content = "ずいぶんとしつこいお方でございます。",
  ui_story_5020_50200701_27_dialog_content = "…",
  ui_story_5020_50200701_28_dialog_content = "少しはアメモリ様に敬意を示せ。",
  ui_story_5020_50200701_29_dialog_content = "おや？",
  ui_story_5020_50200701_30_dialog_content = "失敗したところしか見たことがございませんから、\nとうの昔に誰にも頭は上がらないものと思っておりました…",
  ui_story_5020_50200701_31_dialog_content = "お前なぁ…",
  ui_story_5020_50200701_32_dialog_content = "あなた方の中では、どのような者なのですか？",
  ui_story_5020_50200701_33_dialog_content = "アメモリ様は我らが頭領の弟子だ。",
  ui_story_5020_50200701_34_dialog_content = "頭領が囚われていたこの数年間は、\nアメモリ様が幽燭軍の頭だったのだ。",
  ui_story_5020_50200701_35_dialog_content = "そうでしたか。\n口数の少ないお方ですから、聞いても答えてくださらないのです。",
  ui_story_5020_50200701_36_dialog_content = "ときに、\nあなた方の頭領は「冥土の幽刀」その人でございますね？",
  ui_story_5020_50200701_37_dialog_content = "頭領に会ったのか？",
  ui_story_5020_50200701_38_dialog_content = "ええ、刃を交えた仲でございます。",
  ui_story_5020_50200701_39_dialog_content = "さすがは、公方様に手向かわれた方です…\n恐ろしい強さでございました。",
  ui_story_5020_50200701_40_dialog_content = "あの方の代わりを務めるとなると、\n大変な苦労をしていたのでしょう。",
  ui_story_5020_50200701_41_dialog_content = "アメモリ様は頭領とよく似ていらっしゃる。\n頭領のやろうとしていたことを、アメモリ様は見事にこなしていらした。",
  ui_story_5020_50200701_42_dialog_content = "むしろ、頭領よりも…よくやってるかもしれん。",
  ui_story_5020_50200701_43_dialog_content = "そうでございましたか。",
  ui_story_5020_50200701_44_dialog_content = "巫女の闇討ちにかけては、\nさほどでもなかったと思いますが…",
  ui_story_5020_50200701_45_dialog_content = "本当に頭領よりも腕がよいのでございますか？",
  ui_story_5020_50200701_46_dialog_content = "…",
  ui_story_5020_50200701_47_dialog_content = "答えはお前も分かってるはずだ。",
  ui_story_5020_50200701_48_dialog_content = "なぜお前が巫女になったのか、考えてみるがいい。",
  ui_story_5020_50200701_49_dialog_content = "…",
  ui_story_5020_50200701_50_dialog_content = "ふふ…そういうことでしたか。",
  ui_story_5020_50200701_51_dialog_content = "となると、巫女の命を狙うことも、あなた方にとっての\n「猿芝居」だったわけでございますね。",
  ui_story_5020_50200701_52_dialog_content = "お前と一緒にするな。",
  ui_story_5020_50200701_53_dialog_content = "しかし、今わたくしたちは共に戦っている。\nそうではございませんか？",
  ui_story_5020_50200701_54_dialog_content = "あなたがご自分で舞台に上がられたのでございますよ。",
  ui_story_5020_50200702_1_dialog_content = "後ろから、また鬼武者だ！！",
  ui_story_5020_50200702_2_dialog_content = "援軍が来やがった！",
  ui_story_5020_50200702_3_dialog_content = "…分かった。",
  ui_story_5020_50200702_4_dialog_content = "このままでは持ちません…",
  ui_story_5020_50200702_5_dialog_content = "お頭、どうしますか？",
  ui_story_5020_50200702_6_dialog_content = "…",
  ui_story_5020_50200702_7_dialog_content = "もはや、この戦いに勝ち目はないだろう。",
  ui_story_5020_50200702_8_dialog_content = "お頭…",
  ui_story_5020_50200702_9_dialog_content = "まさか、本当に…",
  ui_story_5020_50200702_10_dialog_content = "だが、まだ捕まってはおらん。",
  ui_story_5020_50200702_11_dialog_content = "<color=#FFB400>次の戦い</color>には…勝てるかもしれん。",
  ui_story_5020_50200702_12_dialog_content = "次の戦い？",
  ui_story_5020_50200702_13_dialog_content = "ここで負けてしまったら、\n次も何もないでしょう…",
  ui_story_5020_50200702_14_dialog_content = "今までやったことのない方法を\n試してみようじゃないか。",
  ui_story_5020_50200702_15_dialog_content = "異郷の小僧！！こっちへ来い！！",
  ui_story_5020_50200702_16_dialog_content = "あの、すぐ側にいるよ。\nそんなに大声で叫ばなくても…",
  ui_story_5020_50200702_17_dialog_content = "小僧、ここから逃げきる自信はあるか？",
  ui_story_5020_50200702_18_dialog_content = "逃げる？",
  ui_story_5020_50200702_19_dialog_content = "敵の数が多すぎて、どうにもならないよ…",
  ui_story_5020_50200702_20_dialog_content = "俺たちが足止めしても、逃げられんか？",
  ui_story_5020_50200702_21_dialog_content = "えっ？",
  ui_story_5020_50200702_22_dialog_content = "いいか、よく聞け。\nお前たち異郷人2人で、今すぐ巫女を連れて逃げろ。",
  ui_story_5020_50200702_23_dialog_content = "俺たちが援護する。ただ、そう長くは持たん。",
  ui_story_5020_50200702_24_dialog_content = "お前のうさんくさい能力とやら、全部出しきれ。",
  ui_story_5020_50200702_25_dialog_content = "分かったな？",
  ui_story_5020_50200702_26_dialog_content = "分かったけど、でも、どうして…",
  ui_story_5020_50200702_27_dialog_content = "どうして、そのようなことを？",
  ui_story_5020_50200702_28_dialog_content = "…",
  ui_story_5020_50200702_29_dialog_content = "巫女、お前の「猿芝居」には観客が足りん。",
  ui_story_5020_50200702_30_dialog_content = "…",
  ui_story_5020_50200702_31_dialog_content = "今の俺たちに、将軍とやり合う力はない。",
  ui_story_5020_50200702_32_dialog_content = "だが、お前たちなら…\nわずかでも、まだ希望があるやも知れん。",
  ui_story_5020_50200702_33_dialog_content = "負けると決まったからには、ただ泣いて待つより、\n大勝負をしたいってことさ。",
  ui_story_5020_50200702_34_dialog_content = "皆の者！守りきるぞ！一歩も退くな！",
  ui_story_5020_50200702_35_dialog_content = "僕たちが逃げた後は、どうするの？",
  ui_story_5020_50200702_36_dialog_content = "<size=45>さっさと行け！</size>",
  ui_story_5020_50200702_37_dialog_content = "…",
  ui_story_5020_50200702_38_dialog_content = "まいりましょう、PlayerName様。",
  ui_story_5020_50200702_39_dialog_content = "皆様の覚悟を無駄にしてはなりません。",
  ui_story_5020_50200702_40_dialog_content = "幽燭軍への貸しってことにしといてやる。",
  ui_story_5020_50200702_41_dialog_content = "必ず返せよ。",
  ui_story_5020_50200702_42_dialog_content = "わあ！！",
  ui_story_5020_50200702_43_dialog_content = "大きな太鼓！",
  ui_story_5020_50200702_44_dialog_content = "大きいな！",
  ui_story_5020_50200702_45_dialog_content = "父さん、これ、何に使うの？",
  ui_story_5020_50200702_46_dialog_content = "春日祭の始まりの合図の太鼓だよ。",
  ui_story_5020_50200702_47_dialog_content = "太鼓打ちがこれを叩けば、太鼓の音が江富の隅々まで響く。\n春日祭が始まったって皆に知らせてくれるんだ。",
  ui_story_5020_50200702_48_dialog_content = "へえ～！",
  ui_story_5020_50200702_49_dialog_content = "じゃあ、なんでこんなところに捨てられてるの？\n太鼓打ちは？",
  ui_story_5020_50200702_50_dialog_content = "鬼が来たんだ。\nそりゃ当然、逃げちまったんだろう。",
  ui_story_5020_50200702_51_dialog_content = "残念だな…",
  ui_story_5020_50200702_52_dialog_content = "じゃあ、遊んでもいい？",
  ui_story_5020_50200702_53_dialog_content = "今はよせ、隊列からはぐれるな。",
  ui_story_5020_50200702_54_dialog_content = "明日になったら、父さんがまた連れてきてやるよ。",
  ui_story_5020_50200702_55_dialog_content = "ねぇ、モモ。",
  ui_story_5020_50200702_56_dialog_content = "なに？",
  ui_story_5020_50200702_57_dialog_content = "太鼓の持ち主、いなくなっちゃったんだよね？",
  ui_story_5020_50200702_58_dialog_content = "まぁ、捨てられたんじゃない？",
  ui_story_5020_50200702_59_dialog_content = "これを持ち帰って…",
  ui_story_5020_50200702_60_dialog_content = "屋台の側に置いたら…",
  ui_story_5020_50200702_61_dialog_content = "呼び込みに使える？",
  ui_story_5020_50200702_62_dialog_content = "<size=40>あいつらを捕まえろ！</size>",
  ui_story_5020_50200702_63_dialog_content = "<size=40>急げ！</size>",
  ui_story_5020_50200702_64_dialog_content = "ん？どうしたんだろ？",
  ui_story_5020_50200702_65_dialog_content = "あれは…",
  ui_story_5020_50200702_66_dialog_content = "誰かがすごい勢いでこっちに来てるよ！？",
  ui_story_5020_50200702_67_dialog_content = "アンズ！モモ！手伝って！早く！！",
  ui_story_5020_50200702_68_dialog_content = "あっ…",
  ui_story_5020_50200702_69_dialog_content = "あーらら…",
  ui_story_5020_50200702_70_dialog_content = "…ごめん、うまく止まれなかった。",
  ui_story_5020_50200702_71_dialog_content = "でも今、本当にマズい状況で…\n侍たちに追われてるんだ！",
  ui_story_5020_50200702_72_dialog_content = "追われてる？",
  ui_story_5020_50200702_73_dialog_content = "PlayerName、何しちゃったの？",
  ui_story_5020_50200702_74_dialog_content = "説明してる時間はないんだ。\nどこか隠れる場所はない？",
  ui_story_5020_50200702_75_dialog_content = "早くしないと、追いつかれちゃう！",
  ui_story_5020_50200702_76_dialog_content = "隠れる場所？",
  ui_story_5020_50200702_77_dialog_content = "急に言われても…",
  ui_story_5020_50200702_78_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5020_50200702_79_dialog_content = "<size=40>ふぅ――</size>",
  ui_story_5020_50200702_80_dialog_content = "PlayerName、もうちょっと向こうに寄ってよ…",
  ui_story_5020_50200702_81_dialog_content = "きゅうくつだわ…",
  ui_story_5020_50200702_82_dialog_content = "僕だってそうしたいけど、中が丸いんだよ…",
  ui_story_5020_50200702_83_dialog_content = "どうしても身体が下に滑っちゃうんだ。",
  ui_story_5020_50200702_84_dialog_content = "はあ…太鼓の中に隠れるなんて、\nおかしなこと考えつくからでしょ！",
  ui_story_5020_50200702_85_dialog_content = "アンズとモモの思いつきだよ！僕じゃない！",
  ui_story_5020_50200702_86_dialog_content = "ふふ…とは申しましても、\nこれよりほかに案はございません。",
  ui_story_5020_50200702_87_dialog_content = "今はこらえましょう。",
  ui_story_5020_50200702_88_dialog_content = "そうね…",
  ui_story_5020_50200702_89_dialog_content = "シーッ…追っ手が来た！",
  ui_story_5020_50200702_90_dialog_content = "お前たち、大急ぎの3人組を見なかったか？",
  ui_story_5020_50200702_91_dialog_content = "1人は紅い巫女の服を着ていて、とても目立ったはずだ。",
  ui_story_5020_50200702_92_dialog_content = "ええ？3人組限定？なんで？",
  ui_story_5020_50200702_93_dialog_content = "青い服でもいい？",
  ui_story_5020_50200702_94_dialog_content = "…「見た」か、「見てない」かだけ答えればいい。",
  ui_story_5020_50200702_95_dialog_content = "見なかったわ！",
  ui_story_5020_50200702_96_dialog_content = "そうか、分かった。",
  ui_story_5020_50200702_97_dialog_content = "（ふぅ…これで大丈夫かな…）",
  ui_story_5020_50200702_98_dialog_content = "…それにしてもお前たち、\nこんなところに2人で何をしている？",
  ui_story_5020_50200702_99_dialog_content = "なぜ皆の列から外れているのだ？",
  ui_story_5020_50200702_100_dialog_content = "わ、わたしたちは…その…",
  ui_story_5020_50200702_101_dialog_content = "この太鼓が…",
  ui_story_5020_50200702_102_dialog_content = "太鼓？",
  ui_story_5020_50200702_103_dialog_content = "（！！！）",
  ui_story_5020_50200702_104_dialog_content = "太鼓がどうかしたか？",
  ui_story_5020_50200702_105_dialog_content = "（まずい…）",
  ui_story_5020_50200702_106_dialog_content = "そうそう、太鼓！",
  ui_story_5020_50200702_107_dialog_content = "わたしたち、太鼓打ちなの！",
  ui_story_5020_50200702_108_dialog_content = "そ…そう！春日祭の準備をしてるんだよ！",
  ui_story_5020_50200702_109_dialog_content = "太鼓打ち？",
  ui_story_5020_50200702_110_dialog_content = "そんな背で太鼓が打てるのか？",
  ui_story_5020_50200702_111_dialog_content = "背は低いけど…",
  ui_story_5020_50200702_112_dialog_content = "あたしたちは二人で一組だもんね！",
  ui_story_5020_50200702_113_dialog_content = "2人で叩くのか？",
  ui_story_5020_50200702_114_dialog_content = "面白い、叩いて見せろ。",
  ui_story_5020_50200702_115_dialog_content = "え…ほんとに？",
  ui_story_5020_50200702_116_dialog_content = "お侍さん、今は止めとこうよ、皆においてかれちゃう…",
  ui_story_5020_50200702_117_dialog_content = "かまわん、後ろから他の連中も来る。\n少しぐらいなら遅れても危険はない。",
  ui_story_5020_50200702_118_dialog_content = "ほら、早くしないか。",
  ui_story_5020_50200702_119_dialog_content = "（…）",
  ui_story_5020_50200702_120_dialog_content = "（アンズ、モモ、まさか本当に叩くつもりじゃ…）",
  ui_story_5020_50200702_121_dialog_content = "<size=30>PlayerName、ごめん…</size>",
  ui_story_5020_50200702_122_dialog_content = "<size=30>ちょっと我慢しててね…</size>",
  ui_story_5020_50200702_123_dialog_content = "（待って！まさか…）",
  ui_story_5020_50200702_124_dialog_content = "ハイ！",
  ui_story_5020_50200702_125_dialog_content = "<color=#e8d9bb><size=50>ドン！！！</size></color>",
  ui_story_5020_50200702_126_dialog_content = "ハイ！",
  ui_story_5020_50200702_127_dialog_content = "<color=#e8d9bb><size=50>ドン！！！</size></color>",
  ui_story_5020_50200702_128_dialog_content = "ほう、なかなか見事なものだな。",
  ui_story_5020_50200702_129_dialog_content = "<anim type=Shake>アハハ…</anim>",
  ui_story_5020_50200702_130_dialog_content = "…それほどでもないよ…",
  ui_story_5020_50200702_131_dialog_content = "そう謙そんするな。春日祭は平常通りに開催すると、将軍様がおおせだ。\nちょうどいい、太鼓を城まで持って行ってくれ。",
  ui_story_5020_50200702_132_dialog_content = "怪しい3人組を見かけたら、大声で知らせてくれ。",
  ui_story_5020_50200702_133_dialog_content = "は～い！",
  ui_story_5020_50200702_134_dialog_content = "ふぅ…",
  ui_story_5020_50200702_135_dialog_content = "PlayerName…",
  ui_story_5020_50200702_136_dialog_content = "3人とも大丈夫…？",
  ui_story_5020_50200702_137_dialog_content = "<size=45>大丈夫なはずないでしょ！！</size>",
  ui_story_5020_50200702_138_dialog_content = "<size=45>鼓膜が破れるかと思ったよ！！</size>",
  ui_story_5020_50200702_139_dialog_content = "え？でも、ちゃんと聞こえてるんじゃ…",
  ui_story_5020_50200702_140_dialog_content = "耳は聞こえてない！\n感知能力を使ってるんだよ！",
  ui_story_5020_50200702_141_dialog_content = "PlayerName、何か話してるの？",
  ui_story_5020_50200702_142_dialog_content = "ごめん！本当にごめん！",
  ui_story_5020_50200702_143_dialog_content = "はぁ…",
  ui_story_5020_50200702_144_dialog_content = "気にしないで、あの状況じゃ仕方なかった。",
  ui_story_5020_50200702_145_dialog_content = "シーッ！",
  ui_story_5020_50200702_146_dialog_content = "また来た！",
  ui_story_5020_50200702_147_dialog_content = "なんでこんなに…",
  ui_story_5020_50200702_148_dialog_content = "どうしよう？",
  ui_story_5020_50200702_149_dialog_content = "このまま太鼓の中に隠れてるしかないね…",
  ui_story_5020_50200702_150_dialog_content = "あたしとアンズで人通りの少ない所に運んであげる。\nそうすれば、少しは逃げやすくなるよ。",
  ui_story_5020_50200702_151_dialog_content = "それしかなさそうだね…",
  ui_story_5020_50200702_152_dialog_content = "でしょ！",
  ui_story_5020_50200702_153_dialog_content = "あたしたち、アイデアはいつも\nいっぱい思いつくもんね！",
  ui_story_5020_50200702_154_dialog_content = "でも、先に言っておくけど…",
  ui_story_5020_50200702_155_dialog_content = "太鼓はもう叩かないで…！",
  ui_story_5020_50200702_156_dialog_content = "もう絶対叩かない！",
  ui_story_5020_50200702_157_dialog_content = "（幽燭軍の人たちは僕たちを逃がしてくれたけど、\n僕たちは一体何を期待されてるんだろう）",
  ui_story_5020_50200702_158_dialog_content = "（今頃は…どうなったかな…）",
  ui_story_5020_50200702_159_dialog_content = "降参だ！降参する！",
  ui_story_5020_50200702_160_dialog_content = "おい！聞こえないのか！\n手を止めろ！降参する！",
  ui_story_5020_50200702_161_dialog_content = "分かった分かった！\n将軍様の言う通りだ！",
  ui_story_5020_50200702_162_dialog_content = "俺たちは罪を犯した！\n法の裁きを受けないとな！",
  ui_story_5020_50200702_163_dialog_content = "…",
  ui_story_5020_50200702_164_dialog_content = "お侍さん、将軍の犬…いや、右腕として…",
  ui_story_5020_50200702_165_dialog_content = "あんたも法には従うんだろ？",
  ui_story_5020_50200702_166_dialog_content = "お前たち…なぜ捨て身してまで巫女を逃がした？",
  ui_story_5020_50200702_167_dialog_content = "巫女は勝手に逃げたんだ、俺たちは知らん。",
  ui_story_5020_50200702_168_dialog_content = "…敵の敵が友とは限らんぞ。",
  ui_story_5020_50200702_169_dialog_content = "巫女は将軍様の養女だ。\n何かしでかしたとて、大ごとにはなるまい。",
  ui_story_5020_50200702_170_dialog_content = "それならいいじゃないか。とにかく、この戦いは終わりだ！\n平和がもうすぐやって来る！",
  ui_story_5020_50200702_171_dialog_content = "…",
  ui_story_5020_50200702_172_dialog_content = "こいつらを縛り上げて、城に連行しろ！",
  ui_story_5020_50200801_1_dialog_content = "手折りし花をわぎもに贈らん――",
  ui_story_5020_50200801_2_dialog_content = "玉雪の上に花落つる。",
  ui_story_5020_50200801_3_dialog_content = "師匠…どうするおつもりですか？",
  ui_story_5020_50200801_4_dialog_content = "まだいたのか。",
  ui_story_5020_50200801_5_dialog_content = "いつまでも追って来て、疲れはしないのか？",
  ui_story_5020_50200801_6_dialog_content = "お手伝いをさせてください…",
  ui_story_5020_50200801_7_dialog_content = "何を手伝うというのだ？必要はない。",
  ui_story_5020_50200801_8_dialog_content = "これは私ひとりで決着をつけねばならんことだ。",
  ui_story_5020_50200801_9_dialog_content = "ことが済んだらお前を訪ねる。\n今は言うことを聞け。",
  ui_story_5020_50200801_10_dialog_content = "…",
  ui_story_5020_50200801_11_dialog_content = "師匠はあの時もおひとりで出かけられて、そのまま…",
  ui_story_5020_50200801_12_dialog_content = "同じことを繰り返させるわけにまいりませぬ。",
  ui_story_5020_50200801_13_dialog_content = "拙者も大きくなりました。\n少しはお役に立てます…",
  ui_story_5020_50200801_14_dialog_content = "拙者だけではありません。\n幽燭の者たちも…",
  ui_story_5020_50200801_15_dialog_content = "ああ…何年だ？",
  ui_story_5020_50200801_16_dialog_content = "10年になります…",
  ui_story_5020_50200801_17_dialog_content = "10年か！ハハハ、長かったな。",
  ui_story_5020_50200801_18_dialog_content = "私の記憶の中のお前は、背たけもまだ打刀に届かないほどだった。\n風が吹けば、飛ばされてしまいそうだったな。",
  ui_story_5020_50200801_19_dialog_content = "今はもう、大人になったのだな。\n腕も上がったようだ。ここまでしても振り切れん。",
  ui_story_5020_50200801_20_dialog_content = "師匠…",
  ui_story_5020_50200801_21_dialog_content = "だが、頭は相変わらずのようだな。",
  ui_story_5020_50200801_22_dialog_content = "私の「役に立つ」というが、\n何の役に立つというのだ？",
  ui_story_5020_50200801_23_dialog_content = "師匠がずっとやろうとしていたことです。",
  ui_story_5020_50200801_24_dialog_content = "江富城を真の主に返すこと…",
  ui_story_5020_50200801_25_dialog_content = "ハハハ！分かったぞ…",
  ui_story_5020_50200801_26_dialog_content = "どうしても私を助け出そうとしていた理由はそれか。",
  ui_story_5020_50200801_27_dialog_content = "私がすべてを解決してくれると思っているのだろう。",
  ui_story_5020_50200801_28_dialog_content = "私が城の下で刀を振りかざし、お前たちを連れて、共に将軍を倒す。\nそう期待しているのであろう？",
  ui_story_5020_50200801_29_dialog_content = "師匠、あなたなら…",
  ui_story_5020_50200801_30_dialog_content = "目を覚ませ。",
  ui_story_5020_50200801_31_dialog_content = "我が弟子よ、お前が抱いているのは幻想だ。現実にはならん。",
  ui_story_5020_50200801_32_dialog_content = "私は聖人ではない。そんな連中とはかけ離れたものだ。",
  ui_story_5020_50200801_33_dialog_content = "お前たちの期待で私を縛ろうとするな。\n期待通りの「正義」を演じる役者にはならん。",
  ui_story_5020_50200801_34_dialog_content = "…",
  ui_story_5020_50200801_35_dialog_content = "ですが、師匠がずっとやって来たことは…",
  ui_story_5020_50200801_36_dialog_content = "そうだ、私はずっと将軍に抗ってきた。",
  ui_story_5020_50200801_37_dialog_content = "しかし、それは私がそうしたかったからだ。\n天下のためでも、民のためでもない。",
  ui_story_5020_50200801_38_dialog_content = "そんなもの、私には背負いきれん。",
  ui_story_5020_50200801_39_dialog_content = "…",
  ui_story_5020_50200801_40_dialog_content = "実を言えば、私は幽燭の頭領にふさわしくないとずっと思っていた。",
  ui_story_5020_50200801_41_dialog_content = "あの頃は、私より強い者がいなかっただけだ。\n何も分からぬまま、皆にかつぎあげられた。",
  ui_story_5020_50200801_42_dialog_content = "頭領などと、私にはわずらわしい。\n骨が折れるだけだ。",
  ui_story_5020_50200801_43_dialog_content = "一人で城へ乗り込む方が、\n私にはずっと向いている。",
  ui_story_5020_50200801_44_dialog_content = "城の侍どもがどれだけ厳重に守りを固めようと、\n誰一人として私を止められない。",
  ui_story_5020_50200801_45_dialog_content = "私はやりたいようにやる。\nそれがあるべき姿なのだ。",
  ui_story_5020_50200801_46_dialog_content = "お前はどうだ？我が弟子よ。",
  ui_story_5020_50200801_47_dialog_content = "一体何をしたいのだ？",
  ui_story_5020_50200801_48_dialog_content = "拙者は…",
  ui_story_5020_50200801_49_dialog_content = "考えたこともないか？",
  ui_story_5020_50200801_50_dialog_content = "…",
  ui_story_5020_50200801_51_dialog_content = "ずっと師匠のようになりたいと思っておりました。",
  ui_story_5020_50200801_52_dialog_content = "ほう？",
  ui_story_5020_50200801_53_dialog_content = "幽燭の者たちからは、\n拙者が師匠を継ぐ者だと見られていました。",
  ui_story_5020_50200801_54_dialog_content = "拙者も…皆の者の期待に応えようと努め、\n師匠のいない間、その代わりを果たそうとしてきました。",
  ui_story_5020_50200801_55_dialog_content = "しかし、師匠の代わりなど、拙者の器では…\nどれほど努力しても、満足に務めを果たせませんでした。",
  ui_story_5020_50200801_56_dialog_content = "…",
  ui_story_5020_50200801_57_dialog_content = "師匠の封印が解かれた時、\nやっと肩の荷が下りたと思ったのです。",
  ui_story_5020_50200801_58_dialog_content = "拙者の使命は終わった、と。",
  ui_story_5020_50200801_59_dialog_content = "バカな奴め。お前は私の代わりなどではない。",
  ui_story_5020_50200801_60_dialog_content = "幽燭の軍は私の下で、どうしようもないほど追い詰められた。\nそれが、お前の下では10年も続いたのだ。",
  ui_story_5020_50200801_61_dialog_content = "お前は私よりもずっとよくやっている。",
  ui_story_5020_50200801_62_dialog_content = "そのようなことは…",
  ui_story_5020_50200801_63_dialog_content = "お前も自分のやりたいことを見つけるがいい。",
  ui_story_5020_50200801_64_dialog_content = "そればかりは、私にも教えられん。",
  ui_story_5020_50200801_65_dialog_content = "…",
  ui_story_5020_50200801_66_dialog_content = "私の弟子だというなら、それらしくしていろ。\nぼんやりしていてはならん。",
  ui_story_5020_50200801_67_dialog_content = "己のすべきことをやれ。",
  ui_story_5020_50200801_68_dialog_content = "<color=#e8d9bb>ザッ…ザッ…</color>",
  ui_story_5020_50200801_69_dialog_content = "…",
  ui_story_5020_50200801_70_dialog_content = "なぜまだ付いてくる？",
  ui_story_5020_50200801_71_dialog_content = "拙者にはやりたいことが何か、まだ分かりませぬ。\nですから、ひとまず師匠についていきます。",
  ui_story_5020_50200801_72_dialog_content = "フン…",
  ui_story_5020_50200801_73_dialog_content = "好きにするがいい。",
  ui_story_5020_50200801_74_dialog_content = "<color=#e8d9bb>ザッ…ザッ…</color>",
  ui_story_5020_50200801_75_dialog_content = "手折りし花をわぎもに贈らん――",
  ui_story_5020_50200801_76_dialog_content = "玉…",
  ui_story_5020_50200801_77_dialog_content = "玉雪の上に花落つる。",
  ui_story_5020_50200801_78_dialog_content = "…",
  ui_story_5020_50200801_79_dialog_content = "思い出したぞ。お前は小さい頃から歌がうまかった。",
  ui_story_5020_50200801_80_dialog_content = "今はますます響くようになったな。",
  ui_story_5020_50200801_81_dialog_content = "お褒めにあずかり、感謝します。",
  ui_story_5020_50200801_82_dialog_content = "もう1人の弟子は歌詞もロクに覚えられなかったな。",
  ui_story_5020_50200801_83_dialog_content = "…それどころか、今はもっと多くの事を\n忘れてしまっております。",
  ui_story_5020_50200801_84_dialog_content = "知っている。あいつは何でも身体で覚えるタイプだ。\nケンカの腕だけは誰よりも速く上がった。",
  ui_story_5020_50200801_85_dialog_content = "お前がいつも負けていたな。今はどうだ？",
  ui_story_5020_50200801_86_dialog_content = "…",
  ui_story_5020_50200801_87_dialog_content = "ちょうどいい…\n何が何でもついてくるというなら、手伝え。",
  ui_story_5020_50200801_88_dialog_content = "その縄を持っていろ。",
  ui_story_5020_50200801_89_dialog_content = "師匠、お店の物ですよ…",
  ui_story_5020_50200801_90_dialog_content = "分かっている。借りるだけだ。\n返さないわけではない。",
  ui_story_5020_50200801_91_dialog_content = "よし、同時に力を入れるぞ。",
  ui_story_5020_50200801_92_dialog_content = "<color=#e8d9bb>ハッ！</color>",
  ui_story_5020_50200801_93_dialog_content = "よし、その縄を背負っておけ。",
  ui_story_5020_50200801_94_dialog_content = "…はい。",
  ui_story_5020_50200801_95_dialog_content = "<color=#e8d9bb>ザッ…ザッ…</color>",
  ui_story_5020_50200801_96_dialog_content = "そうだ。",
  ui_story_5020_50200801_97_dialog_content = "私が封印された後…",
  ui_story_5020_50200801_98_dialog_content = "将軍は葬儀をしなかったか？",
  ui_story_5020_50200801_99_dialog_content = "葬儀…？",
  ui_story_5020_50200801_100_dialog_content = "いえ、覚えは…",
  ui_story_5020_50200801_101_dialog_content = "そうか。",
  ui_story_5020_50200801_102_dialog_content = "どなたの葬儀でしょうか？",
  ui_story_5020_50200801_103_dialog_content = "…",
  ui_story_5020_50200801_104_dialog_content = "「ツキ」だ。覚えているか？",
  ui_story_5020_50200801_105_dialog_content = "もともと、お前たち2人はツキが私に託したのだ。",
  ui_story_5020_50200801_106_dialog_content = "覚えております。",
  ui_story_5020_50200801_107_dialog_content = "師匠の姉上でしたね？",
  ui_story_5020_50200801_108_dialog_content = "可愛がってくださいました。",
  ui_story_5020_50200801_109_dialog_content = "とても優しい方だったと覚えております。",
  ui_story_5020_50200801_110_dialog_content = "そうだ、優しい姉だった。",
  ui_story_5020_50200801_111_dialog_content = "ツキ様に、何があったのですか？",
  ui_story_5020_50200801_112_dialog_content = "…",
  ui_story_5020_50200801_113_dialog_content = "私が殺した。",
  ui_story_5020_50200801_114_dialog_content = "！？",
  ui_story_5020_50200801_115_dialog_content = "ツキは「巫女」だったからだ。",
  ui_story_5020_50200801_116_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5020_50200801_117_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5020_50200801_118_dialog_content = "巫女になるべきではなかった。\n私は初めからそう言っていたのだ。",
  ui_story_5020_50200801_119_dialog_content = "しかし、ツキは私の言うことに耳も貸さなかった。\n姉だから、いつでも妹よりも賢いと思っていたのだろうな。",
  ui_story_5020_50200801_120_dialog_content = "巫女は雲島に平和をもたらすと姉は言い張り…",
  ui_story_5020_50200801_121_dialog_content = "私はそんなことをいう姉をあざ笑い、巫女は将軍に平和をもたらすだけ、\n雲島に平和をもたらすのは刃しかないと言った。",
  ui_story_5020_50200801_122_dialog_content = "しかし結局、どちらも相手を説き伏せられぬまま、\nそれぞれの道を歩み出したというわけだ。",
  ui_story_5020_50200801_123_dialog_content = "ツキは本島に修行へ行った。\n私はあちこちで鬼を殺し、腕を磨いた。",
  ui_story_5020_50200801_124_dialog_content = "何年か後、ツキは将軍の巫女となり、\n私は「冥土の幽刀」となっていた。",
  ui_story_5020_50200801_125_dialog_content = "…",
  ui_story_5020_50200801_126_dialog_content = "再会した時、ツキは昔話の一つもせず、\n私と鬼退治の腕を比べたいと言ってきた。",
  ui_story_5020_50200801_127_dialog_content = "それを聞いて、私は笑いが止まらなかったよ。\nもちろん、喜んで勝負を受けた。",
  ui_story_5020_50200801_128_dialog_content = "ところが、ツキは自信たっぷりに剣を抜いた。",
  ui_story_5020_50200801_129_dialog_content = "見たこともない剣だ。あふれるような陽の力を放っていた。\nまさに鬼を斬るために生まれたものといってよかった。",
  ui_story_5020_50200801_130_dialog_content = "私は負けた。ツキは嬉しそうに目の前で舞を踊りながら、\n何度も言った――",
  ui_story_5020_50200801_131_dialog_content = "「巫女は平和をもたらすと言ったでしょう」と。",
  ui_story_5020_50200801_132_dialog_content = "あの時は、ツキならきっとやり遂げるだろうと\n私は本当に信じていた。",
  ui_story_5020_50200801_133_dialog_content = "師匠に勝つとは…",
  ui_story_5020_50200801_134_dialog_content = "あの剣がなければ負けはしなかった。",
  ui_story_5020_50200801_135_dialog_content = "「天雲斬」…あれさえあれば、3歳の赤子でも鬼がはらえる。\nあいつが使えば、力は言うまでもない。",
  ui_story_5020_50200801_136_dialog_content = "だが、「天雲斬」を見たのはあれが最後だった。",
  ui_story_5020_50200801_137_dialog_content = "それ以来、鬼をはらうことは、もはや彼女の目標ではなくなった。\nただの手段になったのだ。",
  ui_story_5020_50200801_138_dialog_content = "…",
  ui_story_5020_50200801_139_dialog_content = "ツキは雲照鏡を使い、人々に鬼をはらう様子を見せはじめた。",
  ui_story_5020_50200801_140_dialog_content = "しかし、私には分かっていた。あれは芝居だった。",
  ui_story_5020_50200801_141_dialog_content = "10年前の祭りで、ツキは雲照鏡を使って\n鬼を呼んでははらい、疲れ知らずで芝居をしていた。",
  ui_story_5020_50200801_142_dialog_content = "私はウソを見破れる。\nだが他の者は分からず、それを信じた。",
  ui_story_5020_50200801_143_dialog_content = "民は巫女が江富城に平和をもたらすと信じ、\n巫女を育てる将軍も素晴らしい統治者だと信じた。",
  ui_story_5020_50200801_144_dialog_content = "その時、悟ったのだ。\n私とツキはもはや、それぞれの平和をおびやかす敵同士となった。",
  ui_story_5020_50200801_145_dialog_content = "幽燭の者たちはまとまりを失い、少なくない数が抗う意志を失った。\n将軍側について、従順な民になろうという者も出はじめた。",
  ui_story_5020_50200801_146_dialog_content = "武力で押さえつけられるより恐ろしいことだ。",
  ui_story_5020_50200801_147_dialog_content = "なぜ？",
  ui_story_5020_50200801_148_dialog_content = "将軍に殺された者どもの子は、仇を胸に刻み、\nいずれ前人たちの意志を継いで戦いを続けるだろう。",
  ui_story_5020_50200801_149_dialog_content = "しかし、巫女の術にはまった者たちは徐々に恨みを忘れる。\n自分が何人であるかを忘れ、やがて将軍の家畜となる。",
  ui_story_5020_50200801_150_dialog_content = "幽燭の者は負けを恐れはしない。そもそも真の勝利など得ることはないのだ。\nだが、我々の反抗が一時たりとも途絶えたことはない。",
  ui_story_5020_50200801_151_dialog_content = "真に恐れるべきものは、妥協と同化だ。\nそして移り変わってしまうことだ。",
  ui_story_5020_50200801_152_dialog_content = "戦士たちが次々と己の戦う理由を忘れてしまえば…",
  ui_story_5020_50200801_153_dialog_content = "我々がなぜ存在したのかさえ、\n覚えている者もいなくなる。",
  ui_story_5020_50200801_154_dialog_content = "この島はまだ雲島と呼ばれてはいるが、\n本来の姿はとうに失われている。",
  ui_story_5020_50200801_155_dialog_content = "…",
  ui_story_5020_50200801_156_dialog_content = "だから、私はお前に、そして幽燭の軍のすべての者に、\nかならず巫女を殺せと言ったのだ。",
  ui_story_5020_50200801_157_dialog_content = "将軍に幽燭の軍を倒すことは出来ない。\nだが、巫女にはできる。",
  ui_story_5020_50200801_158_dialog_content = "<color=#e8d9bb>ザッ…ザッ…</color>",
  ui_story_5020_50200801_159_dialog_content = "さあ、着いたぞ。",
  ui_story_5020_50200801_160_dialog_content = "手伝え。\nここにある<color=#FFB400>酒</color>を全部運び出す。",
  ui_story_5020_50200801_161_dialog_content = "背負った縄をくくりつけて、まとめろ。",
  ui_story_5020_50200801_162_dialog_content = "…師匠、これは…",
  ui_story_5020_50200801_163_dialog_content = "構わんさ、この店の主人ならよく知った顔だ。",
  ui_story_5020_50200801_164_dialog_content = "書置きを残しておいた。金は後できちんと払う。",
  ui_story_5020_50200801_165_dialog_content = "さっさとやれ。",
  ui_story_5020_50200801_166_dialog_content = "…",
  ui_story_5020_50200801_167_dialog_content = "<color=#e8d9bb>サッ…サッ…</color>",
  ui_story_5020_50200801_168_dialog_content = "ふぅ――",
  ui_story_5020_50200801_169_dialog_content = "よし、しっかり結べたな。",
  ui_story_5020_50200801_170_dialog_content = "この酒を背負って、私に付いてこい。",
  ui_story_5020_50200801_171_dialog_content = "疲れたらそう言うがいい。\nしばらく替わってやる。",
  ui_story_5020_50200801_172_dialog_content = "…この程度、師匠の手は借りませぬ。",
  ui_story_5020_50200801_173_dialog_content = "本当か？この先の道はもっと険しいぞ。",
  ui_story_5020_50200801_174_dialog_content = "どちらへ？",
  ui_story_5020_50200801_175_dialog_content = "<color=#FFB400>城</color>だ。",
  ui_story_5020_50200801_176_dialog_content = "城！？",
  ui_story_5020_50200801_177_dialog_content = "そうだ。",
  ui_story_5020_50200801_178_dialog_content = "屋根の上には行ったことがあるか？\nあそこは景色がいい。酒を飲むには絶好の場所だ。",
  ui_story_5020_50200801_179_dialog_content = "お前も私の弟子なら、\nあそこへ忍び込むぐらい、造作もなかろう？",
  ui_story_5020_50200801_180_dialog_content = "はい…",
  ui_story_5020_50200801_181_dialog_content = "師匠の行ける所であれば…",
  ui_story_5020_50200801_182_dialog_content = "<color=#e8d9bb>ザッ…ザッ…</color>",
  ui_story_5020_50200801_183_dialog_content = "またこの道か。",
  ui_story_5020_50200801_184_dialog_content = "10年前もこの道を通った。\n城がどんどん大きくなるのを見ながら歩いたものだ。",
  ui_story_5020_50200801_185_dialog_content = "太陽と月をも隠す城の姿を見て、あれほど大きな所に一度入ったら、\n二度と出てこられないだろうとさえ思った。",
  ui_story_5020_50200801_186_dialog_content = "師匠は出てくるおつもりがなかったのでしょう？",
  ui_story_5020_50200801_187_dialog_content = "それで「斥鬼凌人の玉」を拙者たちに託された。",
  ui_story_5020_50200801_188_dialog_content = "ハハ…その通りだ。",
  ui_story_5020_50200801_189_dialog_content = "「斥鬼凌人の玉」は何があっても、\n将軍の手に渡ってはならない。",
  ui_story_5020_50200801_190_dialog_content = "それほどの危険を冒してまで、\n殺さねばならなかったのですか？",
  ui_story_5020_50200801_191_dialog_content = "実の姉上を…",
  ui_story_5020_50200801_192_dialog_content = "そうだ…実の姉でもだ。",
  ui_story_5020_50200801_193_dialog_content = "互いにその日が来ると分かっていた。",
  ui_story_5020_50200801_194_dialog_content = "私は姉を殺して死ぬ覚悟でいた。\n姉は私に殺される覚悟でいた。",
  ui_story_5020_50200801_195_dialog_content = "私たちはあの城の中で、共に雲島の平和のために死ぬ。\nそう、私は思っていた。",
  ui_story_5020_50200801_196_dialog_content = "だが…",
  ui_story_5020_50200801_197_dialog_content = "ツキは私を死なせようとしなかった。",
  ui_story_5020_50200801_198_dialog_content = "そして私も、死ぬ前にもう一つやらねばならぬことがあった。",
  ui_story_5020_50200801_199_dialog_content = "！？",
  ui_story_5020_50200801_200_dialog_content = "もう一人、地獄の道連れにせねばならない者がいたのだ。",
  ui_story_5020_50200801_201_dialog_content = "…",
  ui_story_5020_50200801_202_dialog_content = "…将軍ですか？",
  ui_story_5020_50200801_203_dialog_content = "そう、奴だ。他にいるはずもない。",
  ui_story_5020_50200801_204_dialog_content = "ツキが死ぬという時になってようやく、\n何が彼女を変えたのかが分かった。",
  ui_story_5020_50200801_205_dialog_content = "死ぬというその時まで、\nツキはヤツを信じていた。",
  ui_story_5020_50200801_206_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5020_50200801_207_dialog_content = "ツキが自ら堕落したか、\n誰かに操られていたという方がマシだった。",
  ui_story_5020_50200801_208_dialog_content = "しかし…ツキは自ら進んで\n藤雲にだまされていた。",
  ui_story_5020_50200801_209_dialog_content = "間違ったことと頭で分かっていても、\n藤雲が正しいと信じていた。",
  ui_story_5020_50200801_210_dialog_content = "ほだされていたのだ。",
  ui_story_5020_50200801_211_dialog_content = "私は感情というものを憎んだ。",
  ui_story_5020_50200801_212_dialog_content = "それを利用し、ツキの考えをゆがめた将軍を憎んだ。",
  ui_story_5020_50200801_213_dialog_content = "言っただろう。\n私はやりたいようにやる。",
  ui_story_5020_50200801_214_dialog_content = "私か、ヤツか。\n少なくともどちらかが死ななければならない。",
  ui_story_5020_50200801_215_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5020_50200801_216_dialog_content = "やっと着いたな。",
  ui_story_5020_50200801_217_dialog_content = "建物に上るのは得意だったな？",
  ui_story_5020_50200801_218_dialog_content = "はい。",
  ui_story_5020_50200801_219_dialog_content = "では、どちらが先に着くか勝負だ。",
  ui_story_5020_50200801_220_dialog_content = "…師匠、私は酒を背負っておりますが…",
  ui_story_5020_50200801_221_dialog_content = "ほう？酒が無ければ勝てるというつもりか？",
  ui_story_5020_50200801_222_dialog_content = "…",
  ui_story_5020_50200801_223_dialog_content = "<color=#e8d9bb>ザッ…ザッ…ザッ…</color>",
  ui_story_5020_50200801_224_dialog_content = "師匠、後悔しておられるのですか？",
  ui_story_5020_50200801_225_dialog_content = "むろん、後悔などしていない。\n私がそんなことを一度でも言ったか？",
  ui_story_5020_50200801_226_dialog_content = "…ならばなぜ、葬儀のことを\nお聞きになったのですか？",
  ui_story_5020_50200801_227_dialog_content = "…",
  ui_story_5020_50200801_228_dialog_content = "殺したことは後悔していない。\nだが…",
  ui_story_5020_50200801_229_dialog_content = "私の姉だ。\n私が葬ってやるべきだった。",
  ui_story_5020_50200801_230_dialog_content = "…",
  ui_story_5020_50200801_231_dialog_content = "もう一つ気になることがあってな。",
  ui_story_5020_50200801_232_dialog_content = "「天雲斬」はツキの剣だ。\n副葬されているのではないかと思ってな。",
  ui_story_5020_50200801_233_dialog_content = "あれは、鬼斬りの剣…将軍には必要ない。",
  ui_story_5020_50200801_234_dialog_content = "「天雲斬」を探すおつもりですか？",
  ui_story_5020_50200801_235_dialog_content = "そうだ。",
  ui_story_5020_50200801_236_dialog_content = "あの宝刀が土に埋められていたら、\nツキも怒り泣きすることだろう。",
  ui_story_5020_50200801_237_dialog_content = "<color=#e8d9bb>ドサッ！</color>",
  ui_story_5020_50200801_238_dialog_content = "しばらくぶりの眺めだ。",
  ui_story_5020_50200801_239_dialog_content = "縄をほどけ。",
  ui_story_5020_50200801_240_dialog_content = "店主の酒造りの腕が、\n十年でどこまで上がったか見てやるとしよう…",
  ui_story_5020_50200801_241_dialog_content = "はい。",
  ui_story_5020_50200801_242_dialog_content = "もう酒が飲める年だったか？",
  ui_story_5020_50200801_243_dialog_content = "…いえ。",
  ui_story_5020_50200801_244_dialog_content = "つまらんな。",
  ui_story_5020_50200801_245_dialog_content = "まあ、いい。1樽は私によこせ。\n他はすべて<color=#FFB400>割れ</color>。",
  ui_story_5020_50200801_246_dialog_content = "割る？それはどうして…",
  ui_story_5020_50200801_247_dialog_content = "割れと言ったら割ればよい。\nごちゃごちゃ聞くな。",
  ui_story_5020_50200801_248_dialog_content = "…はい。",
  ui_story_5020_50200801_249_dialog_content = "<color=#e8d9bb>バシャ！</color>",
  ui_story_5020_50200801_250_dialog_content = "<color=#e8d9bb>バシャ！</color>",
  ui_story_5020_50200801_251_dialog_content = "<color=#e8d9bb>バシャ！</color>",
  ui_story_5020_50200801_252_dialog_content = "ハハハハハ！それでよし！",
  ui_story_5020_50200801_253_dialog_content = "<anim type=Shake>ゴク…ゴク…</anim>",
  ui_story_5020_50200801_254_dialog_content = "はぁ…うまい。",
  ui_story_5020_50200801_255_dialog_content = "<color=#e8d9bb>ガタッ…</color>",
  ui_story_5020_50200801_256_dialog_content = "師匠、落ちないようお気を付けください。",
  ui_story_5020_50200801_257_dialog_content = "落ちるわけがあるまい。\n私を誰だと思っている？",
  ui_story_5020_50200801_258_dialog_content = "我が弟子よ、城の下を見るがいい。",
  ui_story_5020_50200801_259_dialog_content = "今、あそこを歩いているのは誰だ？",
  ui_story_5020_50200801_260_dialog_content = "…",
  ui_story_5020_50200801_261_dialog_content = "将軍です。",
  ui_story_5020_50200801_262_dialog_content = "何をしているのでしょう？",
  ui_story_5020_50200801_263_dialog_content = "ひとつ教えておく。\n己の敵というのは、一番の理解者でもあるのだ。",
  ui_story_5020_50200801_264_dialog_content = "遠くからでも、私には\nあの男の考えていることが分かる。",
  ui_story_5020_50200801_265_dialog_content = "きっと己は今、一歩一歩\n「平和」に向かっていると思っていることだろう。",
  ui_story_5020_50200801_266_dialog_content = "なぜですか？",
  ui_story_5020_50200801_267_dialog_content = "私もそう思っているからだ。",
  ui_story_5020_50200801_268_dialog_content = "！！！",
  ui_story_5020_50200801_269_dialog_content = "師匠、まさか…",
  ui_story_5020_50200801_270_dialog_content = "ひとりで酒を飲んでもつまらんだろう。",
  ui_story_5020_50200801_271_dialog_content = "弟子が付き合ってくれないというのなら、\n江富城に付き合ってもらおうじゃないか！",
  ui_story_5020_50200901_1_dialog_content = "謀反人どもの主力は取り押さえました。\n現在、こちらに向けて護送中です。",
  ui_story_5020_50200901_2_dialog_content = "そうか。",
  ui_story_5020_50200901_3_dialog_content = "幽燭の倒れかけた旗が、今日ようやく倒れる。",
  ui_story_5020_50200901_4_dialog_content = "民に知らせよ。\n城楼の下で、罪人に裁きをくだす。",
  ui_story_5020_50200901_5_dialog_content = "町の者どもは不安な一夜を過ごした。\n誰かに責任をとらせ、この騒ぎを終わせねばならん。",
  ui_story_5020_50200901_6_dialog_content = "夜が明ければ、春日祭だ。",
  ui_story_5020_50200901_7_dialog_content = "はっ。",
  ui_story_5020_50200901_8_dialog_content = "<color=#e8d9bb>ガタン…ガタン…</color>",
  ui_story_5020_50200901_9_dialog_content = "ねえ、本当に人の少ない方に進んでるの？",
  ui_story_5020_50200901_10_dialog_content = "周りがどんどん騒がしくなってる気がするよ…？",
  ui_story_5020_50200901_11_dialog_content = "仕方ないでしょ。",
  ui_story_5020_50200901_12_dialog_content = "太鼓を押してるから、すごく目立つの。\n人混みに紛れてないと。",
  ui_story_5020_50200901_13_dialog_content = "…今、大体どの辺りに居るの？",
  ui_story_5020_50200901_14_dialog_content = "今は…",
  ui_story_5020_50200901_15_dialog_content = "そろそろお城に着くよ。",
  ui_story_5020_50200901_16_dialog_content = "城！？自分から網にかかるようなものじゃ…",
  ui_story_5020_50200901_17_dialog_content = "もう、どうにかなるわよ！",
  ui_story_5020_50200901_18_dialog_content = "どうにもならないようだったら、\n春日祭が終わるまで隠れてれば…",
  ui_story_5020_50200901_19_dialog_content = "僕たちを殺す気！？",
  ui_story_5020_50200901_20_dialog_content = "<size=45>道を開けろ！</size>",
  ui_story_5020_50200901_21_dialog_content = "<size=45>邪魔をするな！</size>",
  ui_story_5020_50200901_22_dialog_content = "今度は何なの？",
  ui_story_5020_50200901_23_dialog_content = "お侍さんね。\nたくさんの人を引き連れて…",
  ui_story_5020_50200901_24_dialog_content = "あれ？あの人たちは…",
  ui_story_5020_50200901_25_dialog_content = "幽燭軍の人たちだ！",
  ui_story_5020_50200901_26_dialog_content = "幽燭軍！？",
  ui_story_5020_50200901_27_dialog_content = "みんな、捕まっちゃったのか…",
  ui_story_5020_50200901_28_dialog_content = "そうみたい…",
  ui_story_5020_50200901_29_dialog_content = "お城に向かってるよ。",
  ui_story_5020_50200901_30_dialog_content = "…あの人たちをどうするつもりなんだろう…",
  ui_story_5020_50200901_31_dialog_content = "今夜の騒ぎの罪をなすりつけ、\n人々の怒りを鎮めようとしているのでございましょう。",
  ui_story_5020_50200901_32_dialog_content = "どうしてそんなことを…あの人たちは…",
  ui_story_5020_50200901_33_dialog_content = "皆、信じるでしょうか？",
  ui_story_5020_50200901_34_dialog_content = "鬼を呼ぶかどうかは、\nすべて公方様が意のままに決められること…",
  ui_story_5020_50200901_35_dialog_content = "幽燭の軍が捕らえられ、鬼の災いが静まった、\nということになるのでございましょうね。",
  ui_story_5020_50200901_36_dialog_content = "人々が選ぶことはできません。\n信じるしかないのでございます。",
  ui_story_5020_50200901_37_dialog_content = "でも、それじゃあ…",
  ui_story_5020_50200901_38_dialog_content = "…",
  ui_story_5020_50200901_39_dialog_content = "もしかして…",
  ui_story_5020_50200901_40_dialog_content = "それなら、とりあえず江富城から\n鬼はいなくなるってことですか？",
  ui_story_5020_50200901_41_dialog_content = "それはそれで解決…なのかしら？",
  ui_story_5020_50200901_42_dialog_content = "…うーん、そうと言えないこともないかな…",
  ui_story_5020_50200901_43_dialog_content = "まさに冷酷な統治者って感じのやり方だね…",
  ui_story_5020_50200901_44_dialog_content = "何の迷いもなく誰かを裏切って、\n犠牲にするなんて…",
  ui_story_5020_50200901_45_dialog_content = "でも、それで結局…前より良くなってるように見える、いや、見えてしまう…",
  ui_story_5020_50200901_46_dialog_content = "…",
  ui_story_5020_50200901_47_dialog_content = "見えてしまうだけ、でございましょう？",
  ui_story_5020_50200901_48_dialog_content = "雲島では魂こそ大切なものと、\n皆は心から信じております。",
  ui_story_5020_50200901_49_dialog_content = "わたくしが言った通りの事態となれば、\n人々は確かに敵のいない、幻の世界に生きることとなるでしょう。",
  ui_story_5020_50200901_50_dialog_content = "しかし、真実の罪から目を背けたままでは、\n魂など死んでいるのと何の違いがありましょう？",
  ui_story_5020_50200901_51_dialog_content = "真相を知れば、誰も現状を受け入れはしないと、\nわたくしは信じております。",
  ui_story_5020_50200901_52_dialog_content = "そうですよ！\n町をまるごとウソに巻き込むなんて！",
  ui_story_5020_50200901_53_dialog_content = "みんな、本当のことを知るべきよ！",
  ui_story_5020_50200901_54_dialog_content = "…",
  ui_story_5020_50200901_55_dialog_content = "そうだね。君たちの言う通りだよ。",
  ui_story_5020_50200901_56_dialog_content = "真実から目を背けたままの平和なんて、平和とは言わない。",
  ui_story_5020_50200901_57_dialog_content = "皆に知らせよう。",
  ui_story_5020_50200901_58_dialog_content = "<color=#e8d9bb>ドスン…ドスン…</color>",
  ui_story_5020_50200901_59_dialog_content = "アンズ、モモ、幽燭軍の護送の人たちについていける？",
  ui_story_5020_50200901_60_dialog_content = "ついていく？",
  ui_story_5020_50200901_61_dialog_content = "そんなことしたら、\nほんとに逃げられなくなっちゃうよ？",
  ui_story_5020_50200901_62_dialog_content = "逃げるのはやめるよ。\nそれに、ここで逃げたら…",
  ui_story_5020_50200901_63_dialog_content = "せっかくの春日祭を見逃すことになるしね！",
  ui_story_5020_50200901_64_dialog_content = "罪人を裁くって聞いたが、本当かな？",
  ui_story_5020_50200901_65_dialog_content = "将軍直々のお達しだぞ、本当さ！",
  ui_story_5020_50200901_66_dialog_content = "鬼を呼び出した罪人に裁きを与えるんだとよ！",
  ui_story_5020_50200901_67_dialog_content = "あれだ！広場に向かってる！",
  ui_story_5020_50200901_68_dialog_content = "待て、本当にあいつらが？\n知った顔もたくさんいるぞ！",
  ui_story_5020_50200901_69_dialog_content = "そんなこと知るかよ。\n人身御供（ひとみごくう）だっておかしくはないだろ。",
  ui_story_5020_50200901_70_dialog_content = "ヘッ、将軍様は本当にやり手だな…",
  ui_story_5020_50200901_71_dialog_content = "まぁ、これだけの騒ぎになったんだ。\n誰も裁かれねぇってわけには…",
  ui_story_5020_50200901_72_dialog_content = "<color=#e8d9bb>ドン――</color>",
  ui_story_5020_50200901_73_dialog_content = "申し上げます！",
  ui_story_5020_50200901_74_dialog_content = "逆賊、幽燭軍の者どもを全員捕らえました。",
  ui_story_5020_50200901_75_dialog_content = "賊どもにいかなる罪が与えられるべきか…\n将軍様、どうかお裁きをお願いいたします。",
  ui_story_5020_50200901_76_dialog_content = "余が江富に来て、すでに数十年…",
  ui_story_5020_50200901_77_dialog_content = "余の周りで起こる醜い争いに、\nほとほと疲れ果てていたところであった。",
  ui_story_5020_50200901_78_dialog_content = "だが今日この時、ようやく…",
  ui_story_5020_50200901_79_dialog_content = "「天下太平」の光を見ることができた。",
  ui_story_5020_50200901_80_dialog_content = "「太平」だと…？",
  ui_story_5020_50200901_81_dialog_content = "江富を長年苦しめてきた戦乱を静め…",
  ui_story_5020_50200901_82_dialog_content = "鬼が江富を苦しめれば、巫女を育て…",
  ui_story_5020_50200901_83_dialog_content = "この町に今までで最もおだやかな月日をもたらした。",
  ui_story_5020_50200901_84_dialog_content = "しかし、満足を知らぬ者はいつでもいる。",
  ui_story_5020_50200901_85_dialog_content = "その者どもは余が築いた安寧を踏みにじり、\nもっと多くのものを人から奪い取ろうとした！",
  ui_story_5020_50200901_86_dialog_content = "そやつらが、今、皆の前にいる！",
  ui_story_5020_50200901_87_dialog_content = "…",
  ui_story_5020_50200901_88_dialog_content = "幽燭軍の逆賊どもよ、罪を認めるか？",
  ui_story_5020_50200901_89_dialog_content = "罪だと？",
  ui_story_5020_50200901_90_dialog_content = "一体何のことを言っているのか、分からんな。",
  ui_story_5020_50200901_91_dialog_content = "将軍サマはよくお分かりなのだろう？\nお前が言えばいい。",
  ui_story_5020_50200901_92_dialog_content = "ならば、直々に教えてやろう。",
  ui_story_5020_50200901_93_dialog_content = "おぬしらは鬼と結託し、\n江富を混乱におとしいれた。",
  ui_story_5020_50200901_94_dialog_content = "その罪、斬首に値する！",
  ui_story_5020_50200901_95_dialog_content = "…ヘッ…",
  ui_story_5020_50200901_96_dialog_content = "お前というやつは…",
  ui_story_5020_50200901_97_dialog_content = "（聞こえる？ええと、怒ってる時に申し訳ないけど…）",
  ui_story_5020_50200901_98_dialog_content = "（しばらく大人しくして、時間を稼いでもらえないかな？）",
  ui_story_5020_50200901_99_dialog_content = "（今、君たちが殺されちゃったら、困るんだ）",
  ui_story_5020_50200901_100_dialog_content = "…",
  ui_story_5020_50200901_101_dialog_content = "（アンズとモモが縄をほどきに行くよ。チャンスは一瞬しかない）",
  ui_story_5020_50200901_102_dialog_content = "（その時、武士たち全員を確実に抑えこんでほしいんだ。\nそうでないと、全員おしまいだ）",
  ui_story_5020_50200901_103_dialog_content = "（分かったら、せきをして）",
  ui_story_5020_50200901_104_dialog_content = "オホン、オホン！",
  ui_story_5020_50200901_105_dialog_content = "（ありがとう。じゃあ、もうしばらく演技を続けてて）",
  ui_story_5020_50200901_106_dialog_content = "なあ…将軍様よ、ものは相談なんだが…",
  ui_story_5020_50200901_107_dialog_content = "斬られるのは仕方ないとして、\n斬首は止めてくれないか？",
  ui_story_5020_50200901_108_dialog_content = "…",
  ui_story_5020_50200901_109_dialog_content = "腕でも足でも、好きな所を選んでくれていい。",
  ui_story_5020_50200901_110_dialog_content = "だが、俺は頭がいいんでね。\n活かしておけば、役に立つと思うぜ…",
  ui_story_5020_50200901_111_dialog_content = "武士はこっちに3人、あっち側には5人。\n道の向こう側にも2人。",
  ui_story_5020_50200901_112_dialog_content = "バイス、覚えた？",
  ui_story_5020_50200901_113_dialog_content = "3人…5人…2人…",
  ui_story_5020_50200901_114_dialog_content = "しっかり覚えてよ？\nチャンスは1回きりなんだ！",
  ui_story_5020_50200901_115_dialog_content = "アンズとモモが太鼓の面の固定具を外してくれた。\n僕たちはこのまま頭から飛び出す。",
  ui_story_5020_50200901_116_dialog_content = "出たら、周りの侍を一気に圧倒して、注意をひきつけるんだ！",
  ui_story_5020_50200901_117_dialog_content = "でないと、アンズとモモが\n縄をほどくスキを作れない。",
  ui_story_5020_50200901_118_dialog_content = "ええ、分かったわ！3人…5人…",
  ui_story_5020_50200901_119_dialog_content = "わたくしのお役目は、\n公方様の動きを止めることでございますね？",
  ui_story_5020_50200901_120_dialog_content = "うん。出来る限り、\nあたりをかき回して。",
  ui_story_5020_50200901_121_dialog_content = "もし将軍が鬼を操って僕らを抑えようとしてきたら、\n真実をみんなに知らせるっていう目的は果たせたも同然だよ！",
  ui_story_5020_50200901_122_dialog_content = "ですが、その後はどうすれば？\n身の退き方は…",
  ui_story_5020_50200901_123_dialog_content = "そこまで先読みはできないよ…\n臨機応変だ！",
  ui_story_5020_50200901_124_dialog_content = "アンズ、モモ、準備はいい？",
  ui_story_5020_50200901_125_dialog_content = "うん！",
  ui_story_5020_50200901_126_dialog_content = "縄を切ったら、幽燭軍の人たちに\nついて逃げればいいんだね？",
  ui_story_5020_50200901_127_dialog_content = "それでいいよ！",
  ui_story_5020_50200901_128_dialog_content = "あの人たち、そんなに強くなさそうだけど…",
  ui_story_5020_50200901_129_dialog_content = "大丈夫かな？",
  ui_story_5020_50200901_130_dialog_content = "もし危険な状況になったら、\n何とか僕たちに知らせて。",
  ui_story_5020_50200901_131_dialog_content = "例えば…",
  ui_story_5020_50200901_132_dialog_content = "ちょうど太鼓があるでしょ。",
  ui_story_5020_50200901_133_dialog_content = "分かったよ！",
  ui_story_5020_50200901_134_dialog_content = "太鼓叩くの、あたし結構好き！",
  ui_story_5020_50200901_135_dialog_content = "あとは、バイスが…",
  ui_story_5020_50200901_136_dialog_content = "覚えたわ！",
  ui_story_5020_50200901_137_dialog_content = "よし！",
  ui_story_5020_50200901_138_dialog_content = "皆、行くよ。3…",
  ui_story_5020_50200901_139_dialog_content = "<size=40>2…</size>",
  ui_story_5020_50200901_140_dialog_content = "<size=45>1…</size>",
  ui_story_5020_50200901_141_dialog_content = "<size=50>作戦開始だ！</size>",
  ui_story_5020_50200901_142_dialog_content = "<color=#e8d9bb><size=50>パーン！！！</size></color>",
  ui_story_5020_50200901_143_dialog_content = "速射感知！！！",
  ui_story_5020_50200901_144_dialog_content = "早く！急いで！",
  ui_story_5020_50200901_145_dialog_content = "わかってるってば！",
  ui_story_5020_50200901_146_dialog_content = "助けてくれ！戦いだ！",
  ui_story_5020_50200901_147_dialog_content = "皆の者、得物をとれ！",
  ui_story_5020_50200901_148_dialog_content = "奇襲だ！将軍を守れ！！",
  ui_story_5020_50200901_149_dialog_content = "<color=#e8d9bb>チリン――</color>",
  ui_story_5020_50200901_150_dialog_content = "…",
  ui_story_5020_50200901_151_dialog_content = "…",
  ui_story_5020_50200901_152_dialog_content = "リンネ。そなたは選択を誤っておる。",
  ui_story_5020_50200901_153_dialog_content = "なぜでございましょう？",
  ui_story_5020_50200901_154_dialog_content = "正しくないからだ。",
  ui_story_5020_50200901_155_dialog_content = "あなた様にお教えいただいた正しさと\nあなた様が信じている正しさとは、違うもののように思えてなりません。",
  ui_story_5020_50200901_156_dialog_content = "何もかも教えられるわけではない。\nものごとを理解するには、時も必要だ。",
  ui_story_5020_50200901_157_dialog_content = "その必要はございません。\nわたくしは、己の信じるべき正しさを知りました。",
  ui_story_5020_50200901_158_dialog_content = "わたくしの前の巫女は…あなた様が「正しい」とした巫女は、\nいかなる末路をたどられましたか？",
  ui_story_5020_50200901_159_dialog_content = "そなたの見ている江富城は\nその巫女が創ったものだ。",
  ui_story_5020_50200901_160_dialog_content = "さようでございますか…",
  ui_story_5020_50200901_161_dialog_content = "では、わたくしは別の江富城が見とうございます。",
  ui_story_5020_50200901_162_dialog_content = "このようなまねをして、\nできるとでも思うのか？",
  ui_story_5020_50200901_163_dialog_content = "暴動も戦乱も、余はごまんと見てきた。\nそういうものがもたらすのは変革ではない。破壊だ。",
  ui_story_5020_50200901_164_dialog_content = "見たことのないものも、ございますでしょう？",
  ui_story_5020_50200901_165_dialog_content = "例えば、あなた様に刃を向ける巫女など…",
  ui_story_5020_50200901_166_dialog_content = "そなたの手にかかろうと、今さら恐れはせん。",
  ui_story_5020_50200901_167_dialog_content = "お前にはよく考えてもらいたいだけだ。",
  ui_story_5020_50200901_168_dialog_content = "わたくしはずっと、敵は永遠に鬼だけだと思っておりました。",
  ui_story_5020_50200901_169_dialog_content = "それが今、こうしてあなた様にお手向かいしております。",
  ui_story_5020_50200901_170_dialog_content = "生きた者を敵と見るのは、\n初めてのことでございます。",
  ui_story_5020_50200901_171_dialog_content = "己の感情が怖かろう。",
  ui_story_5020_50200901_172_dialog_content = "ふふ…",
  ui_story_5020_50200901_173_dialog_content = "怖い…？\n興奮していると言った方がよろしいかと。",
  ui_story_5020_50200902_1_dialog_content = "かかれ！！",
  ui_story_5020_50200902_2_dialog_content = "おのれ、逆賊ども！",
  ui_story_5020_50200902_3_dialog_content = "うわあぁ！！人殺し！！",
  ui_story_5020_50200902_4_dialog_content = "あわてるな！",
  ui_story_5020_50200902_5_dialog_content = "隊列を整え、逆賊どもを取り囲め！",
  ui_story_5020_50200902_6_dialog_content = "取り囲む？ハッ！",
  ui_story_5020_50200902_7_dialog_content = "どうやら状況が分かっていないようだな。",
  ui_story_5020_50200902_8_dialog_content = "鬼の手助けさえなければ、戦いはこっちのもんだ！",
  ui_story_5020_50200902_9_dialog_content = "笑止…",
  ui_story_5020_50200902_10_dialog_content = "人であろうと鬼であろうと、\n貴様ら幽燭の者が勝ったためしなどあるまい！",
  ui_story_5020_50200902_11_dialog_content = "今日は勝つさ。",
  ui_story_5020_50200902_12_dialog_content = "どうする…逃げるか？",
  ui_story_5020_50200902_13_dialog_content = "逃げる？どこに逃げるんだよ。\nここを離れたって、また鬼に遭うだけだろ…",
  ui_story_5020_50200902_14_dialog_content = "鬼は人を殺すし、人も人を殺す。はあ…",
  ui_story_5020_50200902_15_dialog_content = "今日だけで…一体どれだけの命が奪われるんだ？",
  ui_story_5020_50200902_16_dialog_content = "<color=#e8d9bb>ゴゴゴ…</color>",
  ui_story_5020_50200902_17_dialog_content = "！！！",
  ui_story_5020_50200902_18_dialog_content = "！！！",
  ui_story_5020_50200902_19_dialog_content = "あれは…",
  ui_story_5020_50200902_20_dialog_content = "…たいへんでございます…",
  ui_story_5020_50200902_21_dialog_content = "「金雲既に出で、十方に照見す。\n鬼妖、頭を垂れ、精怪、王を拝するなり」",
  ui_story_5020_50200902_22_dialog_content = "…",
  ui_story_5020_50200902_23_dialog_content = "ようやくわたくしに雲照鏡の使い方を\nお教えくださったのですね。",
  ui_story_5020_50200902_24_dialog_content = "余が望むのは今も昔も平和、ただそれのみ。",
  ui_story_5020_50200902_25_dialog_content = "しかし、そなたたちはその恩恵にあずかりながら、\n平和とは何か、まったく分かっておらぬ。",
  ui_story_5020_50200902_26_dialog_content = "これ以上教えている時間はない…",
  ui_story_5020_50200902_27_dialog_content = "余は今日、江富城の平和を必ず実現させよう。",
  ui_story_5020_50200902_28_dialog_content = "そなたらが望むか望まぬかに関わらず、な。",
  ui_story_5020_50200902_29_dialog_content = "…",
  ui_story_5020_50200902_30_dialog_content = "…",
  ui_story_5020_50200902_31_dialog_content = "お…鬼だ！鬼が出た！",
  ui_story_5020_50200902_32_dialog_content = "戦いなんかやめて、まずは鬼をはらってくれ！",
  ui_story_5020_50200902_33_dialog_content = "戦いを止める？フン…",
  ui_story_5020_50200902_34_dialog_content = "援軍が来たのだ。\n侍どもの見せ場はこれから。そうだろう？",
  ui_story_5020_50200902_35_dialog_content = "…",
  ui_story_5020_50200902_36_dialog_content = "皆の者…",
  ui_story_5020_50200902_37_dialog_content = "道をすべて塞げ。",
  ui_story_5020_50200902_38_dialog_content = "将軍の命があるまで、\n誰1人としてここを離れてはならん。",
  ui_story_5020_50200902_39_dialog_content = "なんだって！？",
  ui_story_5020_50200902_40_dialog_content = "おい、ここを離れちゃいけないってどういうことだ！\n鬼に取り囲まれるぞ！？",
  ui_story_5020_50200902_41_dialog_content = "まさか、あんたたち…",
  ui_story_5020_50200902_42_dialog_content = "幽燭の者は将軍の命など聞かん！",
  ui_story_5020_50200902_43_dialog_content = "俺が道を開く！\nお前たちは町の衆を逃がせ！",
  ui_story_5020_50200902_44_dialog_content = "はい！！！",
  ui_story_5020_50200902_45_dialog_content = "急げ！みんなあいつらについて行くんだ！",
  ui_story_5020_50200902_46_dialog_content = "ほら、言っただろ！\n信用できるのは雲島の者だけだってな！",
  ui_story_5020_50200902_47_dialog_content = "これでよく分かった。将軍は鬼と手を組んでたんだ！",
  ui_story_5020_50200902_48_dialog_content = "ぺっ！人のツラした鬼め！",
  ui_story_5020_50200902_49_dialog_content = "道を塞ぐ！？民に手を出すおつもりですか？",
  ui_story_5020_50200902_50_dialog_content = "それが民どものため、余の守る秩序のためだ。",
  ui_story_5020_50200902_51_dialog_content = "秩序に従えば、平和を享受できる。\n秩序に背けば、罰を受ける。",
  ui_story_5020_50200902_52_dialog_content = "鬼を使って秩序を保つと？",
  ui_story_5020_50200902_53_dialog_content = "どうかされている…",
  ui_story_5020_50200902_54_dialog_content = "人も鬼も、被っている皮の違いに過ぎん。",
  ui_story_5020_50200902_55_dialog_content = "リンネよ…浅はかに育ってしまったな。",
  ui_story_5020_50200902_56_dialog_content = "…",
  ui_story_5020_50200902_57_dialog_content = "リンネ、そっちは後まわしにしよう。",
  ui_story_5020_50200902_58_dialog_content = "幽燭軍の人たちが町の人たちを逃がすために\n包囲を突破しようとしてる。でも…",
  ui_story_5020_50200902_59_dialog_content = "敵が多すぎて、あの人たちだけじゃ突破は無理だ。",
  ui_story_5020_50200902_60_dialog_content = "…何か妙案が？",
  ui_story_5020_50200902_61_dialog_content = "うん。",
  ui_story_5020_50200902_62_dialog_content = "君が助けに行ってあげて。",
  ui_story_5020_50200902_63_dialog_content = "わたくしが？\nでは、こちらはどうされるのですか？",
  ui_story_5020_50200902_64_dialog_content = "僕とバイスで将軍を足止めする。",
  ui_story_5020_50200902_65_dialog_content = "え？私たち？",
  ui_story_5020_50200902_66_dialog_content = "うん。どのくらい持つか分からないけど、\nとにかく包囲を破らなきゃ。",
  ui_story_5020_50200902_67_dialog_content = "リンネ、鬼退治なら一番得意でしょ。\n君しかいない。",
  ui_story_5020_50200902_68_dialog_content = "ただ、それではあなた方が…",
  ui_story_5020_50200902_69_dialog_content = "安心して！何とかするよ！",
  ui_story_5020_50200902_70_dialog_content = "時間がない、急いで！",
  ui_story_5020_50200902_71_dialog_content = "…分かりました…",
  ui_story_5020_50200902_72_dialog_content = "くれぐれも、決してご無理はなさらないでください。",
  ui_story_5020_50200902_73_dialog_content = "…PlayerName、本当に大丈夫？",
  ui_story_5020_50200902_74_dialog_content = "私たち2人で将軍と戦えるの？",
  ui_story_5020_50200902_75_dialog_content = "ムリだよ。",
  ui_story_5020_50200902_76_dialog_content = "<size=45>じゃあどうするのよ！？</size>",
  ui_story_5020_50200902_77_dialog_content = "そうあわてないで…僕たちは2人だけじゃない。",
  ui_story_5020_50200902_78_dialog_content = "援軍がもうすぐ来る。",
  ui_story_5020_50200902_79_dialog_content = "アイヤ…また行き止まり！？",
  ui_story_5020_50200902_80_dialog_content = "なんだってこんな迷路みたいな家作ったのよ！？",
  ui_story_5020_50200902_81_dialog_content = "このままじゃ、今晩はここに泊まるしか…",
  ui_story_5020_50200902_82_dialog_content = "でも、水も…食べ物もない…",
  ui_story_5020_50200902_83_dialog_content = "それに、すっごく暑い…",
  ui_story_5020_50200902_84_dialog_content = "あれ？さっきまでこんなに暑かったっけ…？",
  ui_story_5020_50200902_85_dialog_content = "わぁ！！！！",
  ui_story_5020_50200902_86_dialog_content = "か、火事よ！？誰かいないの！？",
  ui_story_5020_50200902_87_dialog_content = "ダメだわ、これじゃ泊まれない！\n早く逃げなきゃ！",
  ui_story_5020_50200902_88_dialog_content = "<color=#e8d9bb>ダダダダダ…</color>",
  ui_story_5020_50200902_89_dialog_content = "また行き止まり！？",
  ui_story_5020_50200902_90_dialog_content = "どうしよう…\nやっぱり窓から飛び降りようかな…",
  ui_story_5020_50200902_91_dialog_content = "高い！",
  ui_story_5020_50200902_92_dialog_content = "ダメダメ、ここから飛び降りたら…",
  ui_story_5020_50200902_93_dialog_content = "…ああああ！！",
  ui_story_5020_50200902_94_dialog_content = "大丈夫大丈夫！\nやっぱりそんなに高くなさそう！",
  ui_story_5020_50200902_95_dialog_content = "頭から落ちさえしなければ、いけるわ！",
  ui_story_5020_50200902_96_dialog_content = "せーの…",
  ui_story_5020_50200902_97_dialog_content = "1、2の…",
  ui_story_5020_50200902_98_dialog_content = "3！！！",
  ui_story_5020_50200902_99_dialog_content = "<anim type=Shake><size=45>やっぱり怖いいぃぃぃぃ！！！</size></anim>",
  ui_story_5020_50200902_100_dialog_content = "<color=#e8d9bb>ドーン！！！</color>",
  ui_story_5020_50200902_101_dialog_content = "ああ…お尻が痛いわ…",
  ui_story_5020_50200902_102_dialog_content = "えっ…ヨウ！？",
  ui_story_5020_50200902_103_dialog_content = "来たね！",
  ui_story_5020_50200902_104_dialog_content = "え！？バイス！PlayerName！",
  ui_story_5020_50200902_105_dialog_content = "久しぶり！",
  ui_story_5020_50200902_106_dialog_content = "ところで…ちょっと助けてくれない？",
  ui_story_5020_50200902_107_dialog_content = "…しっかり私につかまって。",
  ui_story_5020_50200902_108_dialog_content = "PlayerName、援軍ってヨウのこと？",
  ui_story_5020_50200902_109_dialog_content = "彼女の方が私たちより助けて欲しそうだけど…",
  ui_story_5020_50200902_110_dialog_content = "ええと…まだいるよ。",
  ui_story_5020_50200902_111_dialog_content = "どけ！",
  ui_story_5020_50200902_112_dialog_content = "将軍、藤雲信虎！！\n今日こそ返してもらうぞ！",
  ui_story_5020_50200902_113_dialog_content = "なにやつだ？\n貸しを作った覚えもない。",
  ui_story_5020_50200902_114_dialog_content = "拙者への借りではない…雲島のだ！",
  ui_story_5020_50200902_115_dialog_content = "アメモリ！来てくれたのね！",
  ui_story_5020_50200902_116_dialog_content = "いや、拙者はずっと楼閣の上にいた。",
  ui_story_5020_50200902_117_dialog_content = "見物していようかとも思ったが、\nおぬしら、あまりにもふがいなさ過ぎる！",
  ui_story_5020_50200902_118_dialog_content = "面白い…",
  ui_story_5020_50200902_119_dialog_content = "若輩者めが。ネズミごときが集まったところで、\n余に対抗できると思ったか？",
  ui_story_5020_50200902_120_dialog_content = "ハハハハハ！",
  ui_story_5020_50200902_121_dialog_content = "ネズミごときとは何だ？\nあいつらにも歯があるのを忘れたか？",
  ui_story_5020_50200902_122_dialog_content = "どんなに高い城だろうと…",
  ui_story_5020_50200902_123_dialog_content = "10年、50年、100年と、\n噛み続ければいつかは倒れるものだ！",
  ui_story_5020_50200902_124_dialog_content = "し…城が燃えてる！？",
  ui_story_5020_50200902_125_dialog_content = "そうよ。だからアタシ、飛び降りてきたの！",
  ui_story_5020_50200902_126_dialog_content = "藤雲の。\nこの城がこれほど美しかったことは、今までなかろう？",
  ui_story_5020_50200902_127_dialog_content = "町の真ん中で、ずっと空を隠しているのは目ざわりだったが…",
  ui_story_5020_50200902_128_dialog_content = "うまい酒と炎が合わされば、\nなかなか見ごたえのあるものだ。",
  ui_story_5020_50200902_129_dialog_content = "この世のあらゆるものが、最も美しい一瞬を迎えるためだけに\n生まれてくるのだと思える。",
  ui_story_5020_50200902_130_dialog_content = "この城の最期にふさわしい。",
  ui_story_5020_50200902_131_dialog_content = "「冥土の幽刀」…",
  ui_story_5020_50200902_132_dialog_content = "おぬしが自由に甘んじるはずもない。\n逃げはしないと分かっていた。",
  ui_story_5020_50200902_133_dialog_content = "おぬしはやはり、\n地獄の底から余を狙う妖刀だ…",
  ui_story_5020_50200902_134_dialog_content = "藤雲の…聞きたいことがある。\nツキがいちばん美しかったのは、いつだ？",
  ui_story_5020_50200902_135_dialog_content = "…おぬしにツキの名を口にする資格はない。",
  ui_story_5020_50200902_136_dialog_content = "幼い頃は、私に歌を教えている姿が\n一番美しいと思っていた。",
  ui_story_5020_50200902_137_dialog_content = "後になって、「巫女が天下に太平をもたらす」と言う時のツキが\n一番美しいと思うようになった。",
  ui_story_5020_50200902_138_dialog_content = "今は、どう思っているか分かるか？",
  ui_story_5020_50200902_139_dialog_content = "黙れ！",
  ui_story_5020_50200902_140_dialog_content = "私のふところで死んでいくツキが、\nいちばん美しかった…",
  ui_story_5020_50200902_141_dialog_content = "…",
  ui_story_5020_50200902_142_dialog_content = "そのことに私は怒り、嫉妬した。",
  ui_story_5020_50200902_143_dialog_content = "あれがお前のための美しさだったからだ。",
  ui_story_5020_50200902_144_dialog_content = "江富城の統治者よ、十年越しの…",
  ui_story_5020_50200902_145_dialog_content = "決着をつけようではないか。",
  ui_story_5020_50200902_146_dialog_content = "お前が私を殺したいという想いが強いか、\n私がお前を殺したいという想いが強いか。",
  ui_story_5020_50201001_1_dialog_content = "おぬしにツキの名を口にする資格はない。",
  ui_story_5020_50201001_2_dialog_content = "口を閉じよ。",
  ui_story_5020_50201001_3_dialog_content = "おぬしは、ツキが造った美しきものを打ち壊したのだ。",
  ui_story_5020_50201001_4_dialog_content = "地獄でツキに詫びるがいい！",
  ui_story_5020_50201001_5_dialog_content = "！！！",
  ui_story_5020_50201001_6_dialog_content = "…藤雲の…お前はやはりどうかしている。\n手の付けられないほどにな。",
  ui_story_5020_50201001_7_dialog_content = "余に失うものなどない。",
  ui_story_5020_50201001_8_dialog_content = "…",
  ui_story_5020_50201001_9_dialog_content = "何をぼんやりしている、弟子ども。",
  ui_story_5020_50201001_10_dialog_content = "は…はい、師匠！手助けいたします！",
  ui_story_5020_50201001_11_dialog_content = "手助けなどいらん。",
  ui_story_5020_50201001_12_dialog_content = "お前たち2人は、さっさと逃げろ。",
  ui_story_5020_50201001_13_dialog_content = "しかし…",
  ui_story_5020_50201001_14_dialog_content = "早くしろ！",
  ui_story_5020_50201001_15_dialog_content = "ヒヨッコ2人も面倒は見きれん！",
  ui_story_5020_50201001_16_dialog_content = "私の足を引っ張るな！",
  ui_story_5020_50201001_17_dialog_content = "師匠…",
  ui_story_5020_50201001_18_dialog_content = "分かったわ！",
  ui_story_5020_50201001_19_dialog_content = "アメモリ、行きましょ。\n師匠は必ず勝つわ！",
  ui_story_5020_50201001_20_dialog_content = "…",
  ui_story_5020_50201001_21_dialog_content = "分かりました、師匠。",
  ui_story_5020_50201001_22_dialog_content = "それでいい。\n聞き分けのよい弟子だ。",
  ui_story_5020_50201001_23_dialog_content = "「冥土の幽刀」とまで呼ばれたおぬしに\n他人を惜しむ心があるとは、驚いた。",
  ui_story_5020_50201001_24_dialog_content = "フン、「冥土の幽刀」の伝説を\n語り継ぐ者がいなくなっては面白くないだけだ。",
  ui_story_5020_50201001_25_dialog_content = "鬼斬りの剣客が、\n人であることを止めた最強の鬼と戦い…",
  ui_story_5020_50201001_26_dialog_content = "そして、果てたとな。",
  ui_story_5020_50201001_27_dialog_content = "<color=#e8d9bb>ドカーン…！！！</color>",
  ui_story_5020_50201001_28_dialog_content = "何が起こってるのかしら…",
  ui_story_5020_50201001_29_dialog_content = "あの2人…戦ってるの？",
  ui_story_5020_50201001_30_dialog_content = "逃げて正解だよ…\n僕たちじゃ、まったく歯が立たない。",
  ui_story_5020_50201001_31_dialog_content = "町はどうなっている？",
  ui_story_5020_50201001_32_dialog_content = "リンネは？どうして一緒じゃないの？",
  ui_story_5020_50201001_33_dialog_content = "ああ、うん…少しずつ話すよ。",
  ui_story_5020_50201001_34_dialog_content = "将軍は鬼を使ってこの場を鎮圧しようとしてるんだ。\n鬼たちと侍が一緒になって、江富城の人たちを逃がさないようにしてる。",
  ui_story_5020_50201001_35_dialog_content = "幸い、町の人は全員一か所に集まってたから…\n幽燭軍の人たちとリンネが今、包囲を突破しようとしてる。",
  ui_story_5020_50201001_36_dialog_content = "洋食軍？",
  ui_story_5020_50201001_37_dialog_content = "幽燭だ！",
  ui_story_5020_50201001_38_dialog_content = "雲島で生まれた者が武装した、つわものの一団…\n師匠も拙者もその一員だ。",
  ui_story_5020_50201001_39_dialog_content = "へぇ～！",
  ui_story_5020_50201001_40_dialog_content = "本来ならおぬしも一員のはずだったのだがな。",
  ui_story_5020_50201001_41_dialog_content = "じゃあ、幽燭軍はいい人たちってことね？",
  ui_story_5020_50201001_42_dialog_content = "…。\nまぁ、そう考えて構わん。",
  ui_story_5020_50201001_43_dialog_content = "だが、巫女が幽燭の軍と共にいるとは？",
  ui_story_5020_50201001_44_dialog_content = "人質にでもとったのか？",
  ui_story_5020_50201001_45_dialog_content = "リンネを人質にしたの！？\nだったら、幽燭軍は悪者じゃない！",
  ui_story_5020_50201001_46_dialog_content = "そうじゃないよ。\nいろいろあって、リンネと幽燭軍が一緒に戦ってるんだ。",
  ui_story_5020_50201001_47_dialog_content = "今は、とりあえず味方同士って言っていいんじゃないかな？",
  ui_story_5020_50201001_48_dialog_content = "幽燭の軍と巫女が？",
  ui_story_5020_50201001_49_dialog_content = "考えられん…",
  ui_story_5020_50201001_50_dialog_content = "ううん…リンネの言葉を借りるなら、\n巫女の敵は鬼だけなんだって。",
  ui_story_5020_50201001_51_dialog_content = "だから、彼女としては\nやるべきことをやってるだけだって。",
  ui_story_5020_50201001_52_dialog_content = "…そうか。分かった。",
  ui_story_5020_50201001_53_dialog_content = "巫女がいるのならば、町の衆はひとまず安全だろう。",
  ui_story_5020_50201001_54_dialog_content = "拙者は探し物をせねばならん。",
  ui_story_5020_50201001_55_dialog_content = "何を探すの？",
  ui_story_5020_50201001_56_dialog_content = "「<color=#FFB400>天雲斬</color>」…鬼を斬る剣だ。",
  ui_story_5020_50201001_57_dialog_content = "師匠の言ったことが確かなら…\n戦局を変えられるやも知れぬ。",
  ui_story_5020_50201001_58_dialog_content = "幽燭軍の人たちから聞いたことがある！\n伝説の武器でしょ？",
  ui_story_5020_50201001_59_dialog_content = "でも、行方不明だって…",
  ui_story_5020_50201001_60_dialog_content = "前の巫女と一緒に葬られている可能性がある。",
  ui_story_5020_50201001_61_dialog_content = "手がかりがあるってことだね！",
  ui_story_5020_50201001_62_dialog_content = "でも、それだけだと、\nやっぱり見つけるのは難しいんじゃ？",
  ui_story_5020_50201001_63_dialog_content = "城外の墓をすべてひっくり返してでも…",
  ui_story_5020_50201001_64_dialog_content = "ちょっと待って！ムリだよ！",
  ui_story_5020_50201001_65_dialog_content = "他に道があるか？\nどの墓が以前の巫女のものかなど、誰も知らんだろう…",
  ui_story_5020_50201001_66_dialog_content = "ねえ…",
  ui_story_5020_50201001_67_dialog_content = "その人、ツキって名前でしょ？",
  ui_story_5020_50201001_68_dialog_content = "そうだ。",
  ui_story_5020_50201001_69_dialog_content = "覚えているのか？",
  ui_story_5020_50201001_70_dialog_content = "うん、覚えてる。",
  ui_story_5020_50201001_71_dialog_content = "お墓がどこにあるかも…覚えてる。",
  ui_story_5020_50201001_72_dialog_content = "何！？",
  ui_story_5020_50201001_73_dialog_content = "それは真か？",
  ui_story_5020_50201001_73X1_dialog_content = "え！？",
  ui_story_5020_50201001_73X2_dialog_content = "そんなことが分かるなんて…ひょっとして…",
  ui_story_5020_50201001_73X3_dialog_content = "記憶を取り戻したってこと？",
  ui_story_5020_50201001_73X4_dialog_content = "そう。アタシ、全部思い出した。",
  ui_story_5020_50201001_73X5_dialog_content = "よかった！！！",
  ui_story_5020_50201001_73X6_dialog_content = "こんな状況になっちゃってるけど…",
  ui_story_5020_50201001_73X7_dialog_content = "雲島に来た目的は達成できたね。",
  ui_story_5020_50201001_73X8_dialog_content = "アハハ！そうね、\nそのためにわざわざ来たんだもの！",
  ui_story_5020_50201001_73X9_dialog_content = "でも、何だか…思ってたほど嬉しくないわ…",
  ui_story_5020_50201001_73X10_dialog_content = "江富城がこのありさまじゃね…",
  ui_story_5020_50201001_73X11_dialog_content = "それにしても…記憶が戻ったって、どうやって？",
  ui_story_5020_50201001_73X12_dialog_content = "師匠が封印されてた場所でタンスを見つけたの。",
  ui_story_5020_50201001_73X13_dialog_content = "それで思い出したの。\n10年前、アタシはあそこで記憶を失った。",
  ui_story_5020_50201001_73X14_dialog_content = "アタシ、タンスの中に隠れてて、\n師匠がツキお姉ちゃんを殺すところを見ていたの。",
  ui_story_5020_50201001_73X15_dialog_content = "怖くて、理解もできなくて、それでアタシ…",
  ui_story_5020_50201001_73X16_dialog_content = "何もかも全部、忘れちゃったみたいね。",
  ui_story_5020_50201001_73X17_dialog_content = "それで、思ってたほど嬉しくないって言ったんだね…",
  ui_story_5020_50201001_73X18_dialog_content = "アタシはただ、ずっと探し続けてきたものが、\n実はアタシを苦しめてて、アタシが捨てたものだったって分かって…",
  ui_story_5020_50201001_73X19_dialog_content = "今までやってきたことが全部…\nむなしく思えてきちゃったの。",
  ui_story_5020_50201001_73X20_dialog_content = "そうではないぞ。",
  ui_story_5020_50201001_73X21_dialog_content = "その時のおぬしは、\n記憶を十年後のおぬしに託したのだ。",
  ui_story_5020_50201001_73X22_dialog_content = "おぬしが強くなって故郷に戻り、\n十年前に降りかかった運命と改めて向き合えるように。",
  ui_story_5020_50201001_73X23_dialog_content = "えっ？",
  ui_story_5020_50201001_73X24_dialog_content = "アメモリ…けっこう口が上手ね。",
  ui_story_5020_50201001_73X25_dialog_content = "…",
  ui_story_5020_50201001_73X26_dialog_content = "ツキの墓のことも、その時聞いたのか？",
  ui_story_5020_50201001_74_dialog_content = "うん…",
  ui_story_5020_50201001_75_dialog_content = "記憶の中で将軍が言ってたわ。\nツキは江富城の<color=#FFB400>西の山のふもと</color>に葬るって。",
  ui_story_5020_50201001_76_dialog_content = "江富城、西の山麓…",
  ui_story_5020_50201001_77_dialog_content = "あの辺りか。",
  ui_story_5020_50201001_78_dialog_content = "付いてこい。ここを出るぞ。",
  ui_story_5020_50201001_79_dialog_content = "出る？そう簡単には出られそうにないよ…",
  ui_story_5020_50201001_80_dialog_content = "あいつらが来てる。",
  ui_story_5020_50201001_81_dialog_content = "！！！",
  ui_story_5020_50201001_82_dialog_content = "<color=#e8d9bb>バン！！</color>",
  ui_story_5020_50201001_83_dialog_content = "<anim type=Shake>…</anim>",
  ui_story_5020_50201001_84_dialog_content = "<anim type=Shake>何人たりとも…離れてはならん！</anim>",
  ui_story_5020_50201002_1_dialog_content = "父さん、父さん…",
  ui_story_5020_50201002_2_dialog_content = "<anim type=Shake>グゥ――</anim>",
  ui_story_5020_50201002_3_dialog_content = "うう…ぐすっ…",
  ui_story_5020_50201002_4_dialog_content = "え～い！",
  ui_story_5020_50201002_5_dialog_content = "行くよ！",
  ui_story_5020_50201002_6_dialog_content = "わあ！！",
  ui_story_5020_50201002_7_dialog_content = "勝手に走り回っちゃだめだよ、\nこんな状況なんだから！",
  ui_story_5020_50201002_8_dialog_content = "早く、列に戻って！",
  ui_story_5020_50201002_9_dialog_content = "うん、ありがとう！",
  ui_story_5020_50201002_10_dialog_content = "でも、お姉ちゃんたちは？",
  ui_story_5020_50201002_11_dialog_content = "わたしたちにはやることがあるの！",
  ui_story_5020_50201002_12_dialog_content = "おしゃべりしてるヒマはないよ、アンズ！\n急いで！",
  ui_story_5020_50201002_13_dialog_content = "<color=#e8d9bb>ガタン…ガタン…ガタン…</color>",
  ui_story_5020_50201002_14_dialog_content = "わ――！",
  ui_story_5020_50201002_15_dialog_content = "でっかい太鼓だ！",
  ui_story_5020_50201002_16_dialog_content = "へへ～、すごいでしょ？",
  ui_story_5020_50201002_17_dialog_content = "お姉ちゃんたち、\nどうして太鼓を押してるの？",
  ui_story_5020_50201002_18_dialog_content = "あたしたちのだからだよ！",
  ui_story_5020_50201002_19_dialog_content = "でも…今、すごく危ないんでしょ？",
  ui_story_5020_50201002_20_dialog_content = "そんな大きな太鼓、ジャマになるだけじゃ…",
  ui_story_5020_50201002_21_dialog_content = "ジャマなんかじゃないよ！\nこれでたくさん人を助けたんだから！",
  ui_story_5020_50201002_22_dialog_content = "そうそう！これからだって、\nもっとたくさん助けられるかもしれないもんね！",
  ui_story_5020_50201002_23_dialog_content = "<color=#e8d9bb>ガタン…ガタン…ガタン…</color>",
  ui_story_5020_50201002_24_dialog_content = "お頭、こっちの突破はできそうにありません！",
  ui_story_5020_50201002_25_dialog_content = "皆、疲れ切っています。\n正面から戦っても、もう勝ち目は…",
  ui_story_5020_50201002_26_dialog_content = "攻める方向を変えませんか？",
  ui_story_5020_50201002_27_dialog_content = "ダメだ。場所を変えたところで、\nすぐに敵に囲まれる。",
  ui_story_5020_50201002_28_dialog_content = "今この場で、血路を開くしかない。",
  ui_story_5020_50201002_29_dialog_content = "しかし…",
  ui_story_5020_50201002_30_dialog_content = "分かっている。\n一晩中戦い通しで、皆くたくただろう。",
  ui_story_5020_50201002_31_dialog_content = "だが、今日は今までと違う。",
  ui_story_5020_50201002_32_dialog_content = "この戦いには、我々の命だけではない。\n雲島の運命がかかっているのだ。",
  ui_story_5020_50201002_33_dialog_content = "ここで投げ出すわけには行かん。",
  ui_story_5020_50201002_34_dialog_content = "死んでも鬼となって、俺と共に戦い続けるのだ！",
  ui_story_5020_50201002_35_dialog_content = "<color=#e8d9bb>チリン――</color>",
  ui_story_5020_50201002_36_dialog_content = "鬼となってしまうことを\n許すわけにはまいりませんね――",
  ui_story_5020_50201002_37_dialog_content = "面倒ごとが増えてしまいます。",
  ui_story_5020_50201002_38_dialog_content = "巫女か！？",
  ui_story_5020_50201002_39_dialog_content = "なぜ来た！？",
  ui_story_5020_50201002_40_dialog_content = "PlayerName様の作った貸し…",
  ui_story_5020_50201002_41_dialog_content = "わたくしが返しにまいりました。",
  ui_story_5020_50201002_42_dialog_content = "…",
  ui_story_5020_50201002_43_dialog_content = "わかった。",
  ui_story_5020_50201002_44_dialog_content = "鬼をはらうことにかけては、\n巫女を信じる。",
  ui_story_5020_50201002_45_dialog_content = "でしたら、兵法については\nあなた方にお任せしますよ。",
  ui_story_5020_50201002_46_dialog_content = "俺たち幽燭の者が\n将軍より頼れるってところを、見せてやるさ。",
  ui_story_5020_50201002_47_dialog_content = "皆の者！！今こそ力を振り絞れ！\n敵の包囲を突破するぞ！！",
  ui_story_5020_50201002_48_dialog_content = "町の衆を連れ、「<color=#FFB400>港</color>」まで進むのだ！",
  ui_story_5020_50201002_49_dialog_content = "<anim type=Shake>ゲホッ…</anim>",
  ui_story_5020_50201002_50_dialog_content = "後悔しているか、ナギ。",
  ui_story_5020_50201002_51_dialog_content = "後悔？なじみのない言葉だ。",
  ui_story_5020_50201002_52_dialog_content = "おぬしほどの強さだ。\nいくさ場で死ぬことなど、想像したことすらなかろう？",
  ui_story_5020_50201002_53_dialog_content = "十年前に一度だけ、ある。",
  ui_story_5020_50201002_54_dialog_content = "私とツキが、共に死ぬ姿を。",
  ui_story_5020_50201002_55_dialog_content = "だが、ツキはおぬしを生かした。",
  ui_story_5020_50201002_56_dialog_content = "おぬしはツキに返しきれない借りを作った。",
  ui_story_5020_50201002_57_dialog_content = "来世では、ツキの妹になるでないぞ。",
  ui_story_5020_50201002_58_dialog_content = "ゴホッ…ハハ…",
  ui_story_5020_50201002_59_dialog_content = "来世のことなど…お前から聞くのは哀れなものだな。",
  ui_story_5020_50201002_60_dialog_content = "人としての心は残っているのか、藤雲の？",
  ui_story_5020_50201002_61_dialog_content = "お前の魂は腐りきっている。\nもはや誰にも救うことなどできはしない…",
  ui_story_5020_50201002_62_dialog_content = "…",
  ui_story_5020_50201002_63_dialog_content = "己の末路など、とうに覚悟しておる。",
  ui_story_5020_50201002_64_dialog_content = "人の心は、とうの昔にツキと死んだ。",
  ui_story_5020_50201002_65_dialog_content = "鬼に堕ちようと…\n人として守れるものに、未練などありはせぬ。",
  ui_story_5020_50201002_66_dialog_content = "それもそうだな…",
  ui_story_5020_50201002_67_dialog_content = "吹雪の楼閣に座して、寿命を全うするなど…\nお前にはふさわしくない末路だ。",
  ui_story_5020_50201002_68_dialog_content = "静かな死など、お前にはない。",
  ui_story_5020_50201002_69_dialog_content = "己を哀れとは思わぬ。",
  ui_story_5020_50201002_70_dialog_content = "戦士として、余は強大な別の戦士に打ち勝ったにすぎん。",
  ui_story_5020_50201002_71_dialog_content = "だがな…藤雲の…",
  ui_story_5020_50201002_72_dialog_content = "我々の戦いは…十年前のものでしかない…",
  ui_story_5020_50201002_73_dialog_content = "ツキに感謝するのだな。\n十年もの無駄な命を与えられたことに。",
  ui_story_5020_50201002_74_dialog_content = "忘れるな…\nなぜ今日、この戦いがもう一度起こったのか…",
  ui_story_5020_50201002_75_dialog_content = "…",
  ui_story_5020_50201002_76_dialog_content = "それはこの地に…\n新たな戦士が立ち上がったからだ！",
  ui_story_5020_50201002_77_dialog_content = "<anim type=Shake>ハハハ…ハハ…！</anim>",
  ui_story_5020_50201002_78_dialog_content = "<size=45><anim type=Shake>アーハッハハッハ！</anim></size>",
  ui_story_5020_50201101_1_dialog_content = "<anim type=Shake>グアア――</anim>",
  ui_story_5020_50201101_2_dialog_content = "ふぅ…",
  ui_story_5020_50201101_3_dialog_content = "全部鬼武者か…",
  ui_story_5020_50201101_4_dialog_content = "将軍め、今度こそ皆を根絶やしにするつもりか。",
  ui_story_5020_50201101_5_dialog_content = "将軍なんてどうでもいい！\n来たヤツ全部、やるだけよ！",
  ui_story_5020_50201101_6_dialog_content = "はあっ！石錘沉海！",
  ui_story_5020_50201101_7_dialog_content = "<anim type=Shake>グ…</anim>",
  ui_story_5020_50201101_8_dialog_content = "<size=45><anim type=Shake>グアアア――！！</anim></size>",
  ui_story_5020_50201101_9_dialog_content = "やはり…鬼を完全に倒すことは出来ぬか！",
  ui_story_5020_50201101_10_dialog_content = "鬼を打ちはらえるのは、リンネのみ…",
  ui_story_5020_50201101_11_dialog_content = "<size=45><anim type=Shake>グアアア――！！</anim></size>",
  ui_story_5020_50201101_12_dialog_content = "はぁああっ――",
  ui_story_5020_50201101_13_dialog_content = "倒せるかどうかは置いといて、\nまずは退かせることが先よ！",
  ui_story_5020_50201101_14_dialog_content = "天人合一、破竹のごとく！",
  ui_story_5020_50201101_15_dialog_content = "<anim type=Shake>グ…</anim>",
  ui_story_5020_50201101_16_dialog_content = "で、でも…",
  ui_story_5020_50201101_17_dialog_content = "PlayerName、お城の方を見て――",
  ui_story_5020_50201101_18_dialog_content = "！！！",
  ui_story_5020_50201101_19_dialog_content = "<size=45><anim type=Shake>グオオオ――！！</anim></size>",
  ui_story_5020_50201101_20_dialog_content = "ど、どういうこと…！？",
  ui_story_5020_50201101_21_dialog_content = "…こいつらは、城の火から逃れてきた鬼武者だ。",
  ui_story_5020_50201101_22_dialog_content = "あの将軍がたった1日の間に、\nこれほど多くの鬼を呼び出したというのか…？",
  ui_story_5020_50201101_23_dialog_content = "本当に何もかも滅ぼしてしまうつもりかもしれんな。",
  ui_story_5020_50201101_24_dialog_content = "セイッ！",
  ui_story_5020_50201101_25_dialog_content = "急ぎ界町を抜けるぞ、こいつらを振り切るのだ。",
  ui_story_5020_50201101_26_dialog_content = "<color=#e8d9bb>江富城郊外、霊園付近</color>",
  ui_story_5020_50201101_27_dialog_content = "わ…！",
  ui_story_5020_50201101_28_dialog_content = "PlayerName、\nアタシの記憶、また少し戻った！",
  ui_story_5020_50201101_29_dialog_content = "ここ、来たことある気がする！",
  ui_story_5020_50201101_30_dialog_content = "来たことあるのは間違いないよ…",
  ui_story_5020_50201101_31_dialog_content = "ここ、僕たちがリンネとアメモリに初めて会った場所だから。",
  ui_story_5020_50201101_32_dialog_content = "そうね。初めて雲島に来て、\n巨像を緊急着陸させて…",
  ui_story_5020_50201101_32X_dialog_content = "この先の竹林でリンネに出会ったのよ。\nそれから…",
  ui_story_5020_50201101_33_dialog_content = "あの時は知らなかったけど、\nアメモリと戦ったのよね！",
  ui_story_5020_50201101_34_dialog_content = "…",
  ui_story_5020_50201101_35_dialog_content = "あ！そっか。\n見覚えがあると思った！",
  ui_story_5020_50201101_36_dialog_content = "…「稲田村を流れる川にそって進めば、\n西に向かって山麓地帯に入り、霊園へとたどりつく」",
  ui_story_5020_50201101_37_dialog_content = "記憶の中で聞いた限り、\nこっちで間違いないはずよ！",
  ui_story_5020_50201101_38_dialog_content = "ねえ、アメモリ。\n今度はアタシの邪魔しないでよね。",
  ui_story_5020_50201101_39_dialog_content = "笑わせるな。それは拙者の台詞だ。",
  ui_story_5020_50201101_40_dialog_content = "「天雲斬」は鬼斬りの刃…\n鬼武者に対抗する切り札なのだ。",
  ui_story_5020_50201101_41_dialog_content = "拙者もおぬしの手助けなど望んでおらぬ。\n邪魔さえしなければ、それでいい。",
  ui_story_5020_50201101_42_dialog_content = "ちょっと待って…何するつもり？",
  ui_story_5020_50201101_43_dialog_content = "その剣を勝手に持ち出すつもりなの？",
  ui_story_5020_50201101_44_dialog_content = "そうだ。",
  ui_story_5020_50201101_45_dialog_content = "で、でも…キミの剣じゃないでしょ？天雲斬は…",
  ui_story_5020_50201101_46_dialog_content = "巫女のお姉ちゃんが残した物よ！",
  ui_story_5020_50201101_47_dialog_content = "それがどうしたというのだ。\n罪のない江富城の民の命がかかっているのだ。",
  ui_story_5020_50201101_48_dialog_content = "急にえらくなったみたいなこと言い出すわね！？",
  ui_story_5020_50201101_49_dialog_content = "師匠がその巫女のことを恨んでなかったとしても、\n同じことをするの？",
  ui_story_5020_50201101_50_dialog_content = "（弟子同士なのに、性格はまったく正反対なんだ…）",
  ui_story_5020_50201101_51_dialog_content = "2人とも…ケンカはやめて…",
  ui_story_5020_50201101_52_dialog_content = "…ん？",
  ui_story_5020_50201101_53_dialog_content = "これは…？",
  ui_story_5020_50201101_54_dialog_content = "わ…雪？",
  ui_story_5020_50201101_55_dialog_content = "いや、雪ではない…",
  ui_story_5020_50201101_56_dialog_content = "<color=#FFB400>白い桜</color>？",
  ui_story_5020_50201101_57_dialog_content = "真っ白な小さな花びらが舞うように散って…\n本当に雪が降ってるみたいね！",
  ui_story_5020_50201101_58_dialog_content = "「雲島の人々は、丸みのある、あでやかな色の花びらと\n枝いっぱいに咲く桜の姿を美しいものとして愛でる」…",
  ui_story_5020_50201101_59_dialog_content = "あれ？旅行ガイドの説明と違うよ？",
  ui_story_5020_50201101_60_dialog_content = "雲島中を探しても、このような桜は\n恐らく他では見られぬのだろう――",
  ui_story_5020_50201101_61_dialog_content = "墓地が近いな。",
  ui_story_5020_50201101_62_dialog_content = "やっぱり、今までより静かになったと思ったら…",
  ui_story_5020_50201101_63_dialog_content = "<anim type=Shake>グ…</anim>",
  ui_story_5020_50201101_64_dialog_content = "え…？\nまさか…",
  ui_story_5020_50201101_65_dialog_content = "<anim type=Shake>グオ――！！！</anim>",
  ui_story_5020_50201101_66_dialog_content = "静かな風景が台無しだわ！",
  ui_story_5020_50201101_67_dialog_content = "お墓の近くに鬼が出るのは、\n分からないでもないけど…",
  ui_story_5020_50201101_68_dialog_content = "ごちゃごちゃ言ってないで！\nまたアタシの腕の見せ所ね！",
  ui_story_5020_50201201_1_dialog_content = "速射感知！",
  ui_story_5020_50201201_2_dialog_content = "<anim type=Shake>グアア――</anim>",
  ui_story_5020_50201201_3_dialog_content = "まったく、面倒ね！",
  ui_story_5020_50201201_4_dialog_content = "「抜いた大根にドロがついてた」って、\nこういう事かしら。",
  ui_story_5020_50201201_5_dialog_content = "…何それ？ことわざ？",
  ui_story_5020_50201201_6_dialog_content = "義姉さんから教わったのよ。\n口が達者だから、リン家じゃ言い負かせる人はいないわ！",
  ui_story_5020_50201201_7_dialog_content = "もちろん、ケンカで勝てる人も\nほとんどいないけどね！",
  ui_story_5020_50201201_8_dialog_content = "なんだか、すごい人みたいだね…",
  ui_story_5020_50201201_9_dialog_content = "なるほど…がてんがいった。",
  ui_story_5020_50201201_10_dialog_content = "え？何が…？\nもしかしてアタシもすごいってこと！？",
  ui_story_5020_50201201_11_dialog_content = "おぬしが粗暴に育つわけだ。",
  ui_story_5020_50201201_12_dialog_content = "師匠の教えは身に残っていなかったようだな。",
  ui_story_5020_50201201_13_dialog_content = "何よ！？もう一度言ってみなさい！",
  ui_story_5020_50201201_14_dialog_content = "PlayerName、今の聞いた？\nこれでもアタシの姉弟子なのよ、ヒドイと思わない？",
  ui_story_5020_50201201_15_dialog_content = "まぁまぁ…ヨウ、君もほどほどにしないと…",
  ui_story_5020_50201201_16_dialog_content = "アメモリも、いちいち怒らせちゃだめだよ…",
  ui_story_5020_50201201_17_dialog_content = "え！？\n「怒らせる」って何よ？",
  ui_story_5020_50201201_18_dialog_content = "挑発されてるってこと！？",
  ui_story_5020_50201201_19_dialog_content = "アタシを怒らせて、何のつもり！？",
  ui_story_5020_50201201_20_dialog_content = "（言い方がまずかった…）",
  ui_story_5020_50201201_21_dialog_content = "先に言っておくが…",
  ui_story_5020_50201201_22_dialog_content = "墓に埋められた天雲斬を\n拙者は何としても手に入れる。",
  ui_story_5020_50201201_23_dialog_content = "おぬしがどのような理由で妨害しようとな。",
  ui_story_5020_50201201_24_dialog_content = "おぬしは始め、本当の師匠が誰であるかさえ忘れ、\nその義姉とやらを師と仰いでいたのだ。",
  ui_story_5020_50201201_25_dialog_content = "だが、拙者の師匠は幼い頃からただ一人。",
  ui_story_5020_50201201_26_dialog_content = "師匠が将軍を倒すのに天雲斬が必要とあらば、\n拙者は何が何でも手に入れる。",
  ui_story_5020_50201201_27_dialog_content = "（まぁ、師匠から直接口に出して頼まれたわけではないが…）",
  ui_story_5020_50201201_28_dialog_content = "城を燃やすことだって聞かされてなかったのに？",
  ui_story_5020_50201201_29_dialog_content = "む…",
  ui_story_5020_50201201_30_dialog_content = "師匠には師匠のお考えがあるのだ！",
  ui_story_5020_50201201_31_dialog_content = "そりゃ師匠には師匠の考えがあるわよ。\nでも、キミはどこまで師匠のことが分かってるの？",
  ui_story_5020_50201201_32_dialog_content = "！？",
  ui_story_5020_50201201_33_dialog_content = "もしや、拙者の知らない何かを思い出したというのか！？",
  ui_story_5020_50201201_34_dialog_content = "ううん…アタシの知ってることはもう全部しゃべったよ。",
  ui_story_5020_50201201_35_dialog_content = "でも、その剣の持ち主は師匠にとって、\nきっと特別な存在だったはず。",
  ui_story_5020_50201201_36_dialog_content = "…",
  ui_story_5020_50201201_37_dialog_content = "その通りだ。拙者には分からぬ。",
  ui_story_5020_50201201_37X_dialog_content = "師匠は名誉を重んじるし、慎重なお方だ。\nなぜ自分の手を汚してまで…",
  ui_story_5020_50201201_38_dialog_content = "ふん、それだけじゃないわ…",
  ui_story_5020_50201201_39_dialog_content = "記憶の中で、アタシは感じたんだ。\nあの巫女のお姉ちゃん、きっとすごく大事な人だったんだって。",
  ui_story_5020_50201201_40_dialog_content = "どうして分かる？",
  ui_story_5020_50201201_41_dialog_content = "…直感よ！",
  ui_story_5020_50201201_42_dialog_content = "…",
  ui_story_5020_50201201_43_dialog_content = "何、その顔！\nアタシの直感、すっごく当たるのよ！？",
  ui_story_5020_50201201_44_dialog_content = "まぁ、そこは…僕も保証するよ。",
  ui_story_5020_50201201_45_dialog_content = "キミが信じようと信じまいと、\n天雲斬はアタシが預かるから。",
  ui_story_5020_50201201_46_dialog_content = "それを見れば、きっとアタシは何か思いだせるわ。",
  ui_story_5020_50201201_47_dialog_content = "師匠とも関係のあることをね！",
  ui_story_5020_50201201_48_dialog_content = "とにかく、アタシもキミの手助けなんか要らないよ。\nただジャマしないで欲しいだけ！",
  ui_story_5020_50201201_49_dialog_content = "…",
  ui_story_5020_50201201_50_dialog_content = "…む？",
  ui_story_5020_50201201_51_dialog_content = "<color=#e8d9bb>ヒュウゥ…</color>",
  ui_story_5020_50201201_52_dialog_content = "フン！",
  ui_story_5020_50201201_53_dialog_content = "<anim type=Shake>グ…</anim>",
  ui_story_5020_50201201_54_dialog_content = "拙者に奇襲など、ヨウが十人いても通用せんぞ。",
  ui_story_5020_50201201_55_dialog_content = "ふっふ～ん、その通りよ！",
  ui_story_5020_50201201_55X_dialog_content = "…あれ？今のほめられてなくない？",
  ui_story_5020_50201201_56_dialog_content = "<anim type=Shake>ガアッ！！</anim>",
  ui_story_5020_50201201_57_dialog_content = "<size=45><anim type=Shake>グガア――！！</anim></size>",
  ui_story_5020_50201201_58_dialog_content = "お互い助けが必要かどうかは置いといて、\n今はまず――",
  ui_story_5020_50201201_59_dialog_content = "はぁああっ！",
  ui_story_5020_50201201_60_dialog_content = "<anim type=Shake>グアア――</anim>",
  ui_story_5020_50201201_61_dialog_content = "鬼をまとめて片づけちゃいましょ！",
  ui_story_5020_50201201_62_dialog_content = "ふん、言われずとも分かっている。",
  ui_story_5020_50201202_1_dialog_content = "<anim type=Shake>グガアア…</anim>",
  ui_story_5020_50201202_2_dialog_content = "ふん、大したことないわね！",
  ui_story_5020_50201202_3_dialog_content = "気を付けろ。\n墓の近くは今より多くの鬼がさまよっているはずだ。",
  ui_story_5020_50201202_4_dialog_content = "拙者が先に様子をうかがってくる。",
  ui_story_5020_50201202_5_dialog_content = "頼んだよ！",
  ui_story_5020_50201202_6_dialog_content = "セイッ！",
  ui_story_5020_50201202_7_dialog_content = "<color=#e8d9bb>ヒュー…ザワザワ…</color>",
  ui_story_5020_50201202_8_dialog_content = "なんだか不安になるわね…ここ、怖いくらい静かだわ。",
  ui_story_5020_50201202_9_dialog_content = "怖がることはないわ！\nアタシの拳に解決できないことはないもの！",
  ui_story_5020_50201202_10_dialog_content = "む…？",
  ui_story_5020_50201202_11_dialog_content = "…アメモリ！？",
  ui_story_5020_50201202_12_dialog_content = "おかしい…",
  ui_story_5020_50201202_13_dialog_content = "どうしたの？\nアメモリ、大丈夫？",
  ui_story_5020_50201202_14_dialog_content = "…入ってくるがいい。",
  ui_story_5020_50201202_15_dialog_content = "中には…鬼が1匹もいない。",
  ui_story_5020_50201202_16_dialog_content = "なんで…？",
  ui_story_5020_50201202_17_dialog_content = "安心するがいい。\nここは確実に安全だ。",
  ui_story_5020_50201202_18_dialog_content = "拙者がいかに集中し、\n息をひそめようとも…",
  ui_story_5020_50201202_19_dialog_content = "桜の花びらが落ちる音以外は\n何も聞こえなかった。",
  ui_story_5020_50201202_20_dialog_content = "桜は他の花と違って、「ぱっ」と花開くものではない…",
  ui_story_5020_50201202_21_dialog_content = "ほころびる瞬間の痛みと喜びをこらえながら、\n穏やかにゆったりと花びらを伸ばすのだ。",
  ui_story_5020_50201202_22_dialog_content = "散り落ちる時でさえ、他の花よりずっと静かなのだ…",
  ui_story_5020_50201202_23_dialog_content = "桜は辛抱強い花だ。\n師匠がお好きなわけだ。",
  ui_story_5020_50201202_24_dialog_content = "おお～…旅行ガイドには書いてなかったことだわ！",
  ui_story_5020_50201202_25_dialog_content = "なぜだかわからないけど、\nなんだか少し、もの悲しい気持ちになるわね…",
  ui_story_5020_50201202_26_dialog_content = "あれ？でも…",
  ui_story_5020_50201202_27_dialog_content = "ここ、人が全然来ないってわけじゃないみたいね…",
  ui_story_5020_50201202_28_dialog_content = "PlayerName、ほら、見て！",
  ui_story_5020_50201202_29_dialog_content = "あ…",
  ui_story_5020_50201202_30_dialog_content = "桜の花びらがきちんと掃かれて、道ができてる。",
  ui_story_5020_50201202_31_dialog_content = "…先に誰か来たのか！？",
  ui_story_5020_50201202_32_dialog_content = "まずい！まさか誰かに先を越されて…",
  ui_story_5020_50201202_33_dialog_content = "あ…",
  ui_story_5020_50201202_34_dialog_content = "これは…",
  ui_story_5020_50201202_35_dialog_content = "さすがは名にし負う、鬼を斬る剣…",
  ui_story_5020_50201202_36_dialog_content = "流れるような剣身…剣先も古い様式だ…",
  ui_story_5020_50201202_37_dialog_content = "長い年月を経てなお、\nこれほど形を保ってここに眠っていたとは…",
  ui_story_5020_50201202_38_dialog_content = "でも、一体誰が？",
  ui_story_5020_50201202_39_dialog_content = "この剣の置き方…",
  ui_story_5020_50201202_40_dialog_content = "どう見ても、おそなえ物みたいよね？",
  ui_story_5020_50201202_41_dialog_content = "あ、PlayerName、見て！",
  ui_story_5020_50201202_42_dialog_content = "剣の下に何かある…",
  ui_story_5020_50201202_43_dialog_content = "…拙者が調べよう。",
  ui_story_5020_50201202_44_dialog_content = "ここに罠が仕掛けられている可能性は低いが、\n万が一のため、やはり…",
  ui_story_5020_50201202_45_dialog_content = "わ、何するつもり！？",
  ui_story_5020_50201202_46_dialog_content = "…？",
  ui_story_5020_50201202_47_dialog_content = "そのまま逃げるつもりじゃない？",
  ui_story_5020_50201202_48_dialog_content = "…このような時に、ジャマをするでない。",
  ui_story_5020_50201202_49_dialog_content = "ちょっと、どうにかしてよ、PlayerName！",
  ui_story_5020_50201202_50_dialog_content = "え！？僕は二人の間に割って入るつもりは…",
  ui_story_5020_50201202_51_dialog_content = "PlayerNameが取って。",
  ui_story_5020_50201202_52_dialog_content = "ぼ…僕が？",
  ui_story_5020_50201202_53_dialog_content = "…",
  ui_story_5020_50201202_54_dialog_content = "ヨウがそれで大人しくするというのなら、\n拙者は構わぬぞ。",
  ui_story_5020_50201202_55_dialog_content = "PlayerName、拙者にムダにする時間はない。",
  ui_story_5020_50201202_56_dialog_content = "…分かったよ。",
  ui_story_5020_50201202_57_dialog_content = "えっ…？",
  ui_story_5020_50201202_58_dialog_content = "これは…",
  ui_story_5020_50201202_59_dialog_content = "剣と一緒に台に置いてあるのって…",
  ui_story_5020_50201202_60_dialog_content = "本が1冊…いや、<color=#FFB400>手記</color>かな？",
  ui_story_5020_50201202_61_dialog_content = "書いた人の名前は…",
  ui_story_5020_50201202_62_dialog_content = "…「<color=#FFB400>ツキ</color>」？",
  ui_story_5020_50201202_63_dialog_content = "！？",
  ui_story_5020_50201202_64_dialog_content = "…間違いない…",
  ui_story_5020_50201202_65_dialog_content = "それは先代の巫女のものだ。",
  ui_story_5020_50201202_66_dialog_content = "誰かがきちんと保管していたようだな。\n長い間ここに捨て置かれていた物には見えぬ。",
  ui_story_5020_50201202_67_dialog_content = "拙者らの前に訪れた者が置いていったのであろう。",
  ui_story_5020_50201202_68_dialog_content = "アタシたちより先に…\n一体誰がここに来るっていうの？",
  ui_story_5020_50201202_69_dialog_content = "…",
  ui_story_5020_50201202_70_dialog_content = "拙者にも確信はないが…",
  ui_story_5020_50201202_71_dialog_content = "先代の巫女との間に、\n何か深い関係があった者だろう。",
  ui_story_5020_50201202_72_dialog_content = "それじゃあ、この手記は…",
  ui_story_5020_50201202_73_dialog_content = "見る！",
  ui_story_5020_50201202_74_dialog_content = "きっと師匠に関わる過去のことが書かれているはずだ。",
  ui_story_5020_50201202_75_dialog_content = "アタシが忘れちゃったことも書かれてるはず！",
  ui_story_5020_50201202_76_dialog_content = "そうっと開いてね、PlayerName。",
  ui_story_5020_50201202_77_dialog_content = "まずは一番新しいページを見て！早く！\n後ろから順番にめくってみて！",
  ui_story_5020_50201202_78_dialog_content = "分かったよ。みんな、僕の側に寄って――",
  ui_story_5020_50201301_1_dialog_content = "巫女様、準備はよろしいですか？",
  ui_story_5020_50201301_2_dialog_content = "はい、ですが…少々お待ちください。",
  ui_story_5020_50201301_3_dialog_content = "これを祭りをとり行う神官に…",
  ui_story_5020_50201301_4_dialog_content = "ツキ、家臣どもの手をわずらわすことはない。",
  ui_story_5020_50201301_5_dialog_content = "余が行こう。",
  ui_story_5020_50201301_6_dialog_content = "あ…公方様、もう「春日祭」へ向かわれたはずでは？",
  ui_story_5020_50201301_7_dialog_content = "…祭りの段取りに少し問題があってな。",
  ui_story_5020_50201301_8_dialog_content = "雲照鏡を取りに戻ったのだ。",
  ui_story_5020_50201301_9_dialog_content = "…何が起こったのですか？",
  ui_story_5020_50201301_10_dialog_content = "気にせずともよい。\nそなたは己の神事の準備だけをしておれ。",
  ui_story_5020_50201301_11_dialog_content = "<color=#e8d9bb>ドカドカドカ――</color>",
  ui_story_5020_50201301_12_dialog_content = "おや…？",
  ui_story_5020_50201301_13_dialog_content = "何の音でしょう？",
  ui_story_5020_50201301_14_dialog_content = "ツキ、そなたは――",
  ui_story_5020_50201301_15_dialog_content = "…",
  ui_story_5020_50201301_16_dialog_content = "…",
  ui_story_5020_50201301_17_dialog_content = "これはこれは、雲島の裏切り者――\n巫女サマじゃないか。",
  ui_story_5020_50201301_18_dialog_content = "正装で着飾ってるあんたと戦ったら、\nまるで俺がいじめでもしてるように見えそうだな。",
  ui_story_5020_50201301_19_dialog_content = "ふん…だが、悪いな。\n今年の「春日祭」は中止だ！",
  ui_story_5020_50201301_20_dialog_content = "あなた方…望みは何ですか？",
  ui_story_5020_50201301_21_dialog_content = "…ツキ！",
  ui_story_5020_50201301_22_dialog_content = "ほう…？",
  ui_story_5020_50201301_23_dialog_content = "単刀直入だな…",
  ui_story_5020_50201301_24_dialog_content = "その点、あんたは藤雲よりずっと賢い。",
  ui_story_5020_50201301_25_dialog_content = "俺たちの望みは簡単だ。\n「春日祭」は二度とやらせない。",
  ui_story_5020_50201301_26_dialog_content = "本島の勢力を助ける\n一切の活動を、俺は止めねばならん！",
  ui_story_5020_50201301_27_dialog_content = "身のほど知らずめが。\nツキ、こやつらとは…",
  ui_story_5020_50201301_28_dialog_content = "そういうことですか。",
  ui_story_5020_50201301_29_dialog_content = "本島の文化が広まるのを止めたいということですね。",
  ui_story_5020_50201301_30_dialog_content = "ま、まぁ、そう言えなくもないな！",
  ui_story_5020_50201301_31_dialog_content = "雲島の港が本島に向けて開かれた日から、\n私たちは新たな時代を迎えたのです。",
  ui_story_5020_50201301_32_dialog_content = "すぐに受け入れることも、認めずに拒むことも、\nごく当然の考え方でございましょう。",
  ui_story_5020_50201301_33_dialog_content = "雲島自身に意志があったのなら、\nきっとこの世の移り変わりの速さに驚いていることでしょう…",
  ui_story_5020_50201301_34_dialog_content = "ですが、江富城が存在する限り、\nわたしもあなた方も共にこの時代を生きる者。",
  ui_story_5020_50201301_35_dialog_content = "その事実は「春日祭」を止めたからといって…\nそして仮に将軍を消したとしても、変えられることではございません。",
  ui_story_5020_50201301_36_dialog_content = "…",
  ui_story_5020_50201301_37_dialog_content = "祭を終わらせるよりも、いっそ…",
  ui_story_5020_50201301_38_dialog_content = "「春日祭」をいかに自分たちのやり方でやるか、\nお考えになってはいかがですか？",
  ui_story_5020_50201301_39_dialog_content = "……",
  ui_story_5020_50201301_40_dialog_content = "巫女様、民草どもは予想通り、\n祭りで騒ぎを続ける気はないようです。",
  ui_story_5020_50201301_41_dialog_content = "それでは…彼らの頭領は？",
  ui_story_5020_50201301_42_dialog_content = "頭領とは…\nあの「ナギ」という女のことですか？",
  ui_story_5020_50201301_43_dialog_content = "まだ行方は分かっておりません。\n目下、全力で探しております。",
  ui_story_5020_50201301_43X_dialog_content = "どうしてもとあらば、もっと人を割いて…",
  ui_story_5020_50201301_44_dialog_content = "いいえ。その必要はありません。",
  ui_story_5020_50201301_45_dialog_content = "また騒ぎが始まったら、\n公方様も頭を痛めてしまわれるでしょう。",
  ui_story_5020_50201301_46_dialog_content = "ナギには好きなように\n「春日祭」の桜を楽しませてあげましょう。",
  ui_story_5020_50201301_47_dialog_content = "巫女様…せんえつながら…",
  ui_story_5020_50201301_48_dialog_content = "先ほどおっしゃったことで、\n公方様がご気分を害されたようでございます。",
  ui_story_5020_50201301_49_dialog_content = "ああ…そうですね。",
  ui_story_5020_50201301_49X_dialog_content = "とはいえ、わたしが何も言わずに立ち去っていたとしたら、\n公方様はあの人たちを「片づけて」しまっていたでしょう。",
  ui_story_5020_50201301_50_dialog_content = "私はただ、この楽しげな雰囲気のあふれるこの日に…",
  ui_story_5020_50201301_51_dialog_content = "公方様が人を殺めるところを\n見たくなかった、ということかもしれません。",
  ui_story_5020_50201301_52_dialog_content = "…殺める？",
  ui_story_5020_50201301_53_dialog_content = "ええ…公方様は雲照鏡を取りに戻って来たのですから…",
  ui_story_5020_50201301_54_dialog_content = "雲照鏡を使って鬼を操り、\n民を無理にでも鎮めるおつもりだったのでしょう。",
  ui_story_5020_50201301_55_dialog_content = "これほど雲照鏡に頼ってしまわれるのは、\nよろしくない事です…",
  ui_story_5020_50201301_56_dialog_content = "何を心配なさっているのですか？あなた様には天雲斬がある。\n鬼などいくらでも斬れるでしょう？",
  ui_story_5020_50201301_57_dialog_content = "すべて収まった後に、\nあなた様が鬼を始末すればよいだけです。",
  ui_story_5020_50201301_58_dialog_content = "…",
  ui_story_5020_50201301_59_dialog_content = "天雲斬と雲照鏡、一つは鬼をはらい、一つは鬼を繰る。\nしかし、どちらも神のたまわりもの…",
  ui_story_5020_50201301_60_dialog_content = "祭の見せ物として使うのは構いません。\nしかし、本当に統治の道具として使うことは…",
  ui_story_5020_50201301_61_dialog_content = "私はあの神器が、制御のできない力――\nすなわち、人には受け止めきれない力を発揮してしまうことを恐れているのです。",
  ui_story_5020_50201301_62_dialog_content = "しかし、それがあなた様の使命でございましょう？",
  ui_story_5020_50201301_63_dialog_content = "天雲斬を手にとり、悪霊や鬼を斬り捨てる。\n本島から戻った歴代の巫女は皆、そうしてきました。",
  ui_story_5020_50201301_64_dialog_content = "しかし、それは己の矛で己の盾を突くと同じこと。",
  ui_story_5020_50201301_65_dialog_content = "天雲斬は鬼を斬ることができ、\n雲照鏡は鬼をよみがえらせることができる…",
  ui_story_5020_50201301_66_dialog_content = "2つの強大な力が互いに均衡を保つには、\n「使う者の意志」がきわめて大事なのです。",
  ui_story_5020_50201301_67_dialog_content = "けれど私は…公方様のお考えを動かすことができません…",
  ui_story_5020_50201301_68_dialog_content = "結局のところ、私も雲島の平和のための\n道具にすぎないのです。",
  ui_story_5020_50201301_69_dialog_content = "巫女様…拙者には…",
  ui_story_5020_50201301_70_dialog_content = "おっしゃることが全く分かりません！",
  ui_story_5020_50201301_71_dialog_content = "<color=#e8d9bb>チリン、チリン、チリン――</color>",
  ui_story_5020_50201301_72_dialog_content = "ふふ、ご覧なさい。\n鈴を一面に飾ったみこしに、公方様がお乗りになりましたよ。",
  ui_story_5020_50201301_73_dialog_content = "これは！…く、公方様！",
  ui_story_5020_50201301_74_dialog_content = "巫女様、我らは公方様の護衛に行ってまいります！",
  ui_story_5020_50201301_75_dialog_content = "<color=#e8d9bb>チリン、チリン、チリン――</color>",
  ui_story_5020_50201301_76_dialog_content = "来ないで！",
  ui_story_5020_50201301_77_dialog_content = "ふぅ、ふぅ…小娘が。\n早く神楽鈴をツキに返せ！",
  ui_story_5020_50201301_78_dialog_content = "ツキお姉ちゃんと鬼ごっこするの！\n追いつけたら、返してあげる！",
  ui_story_5020_50201301_79_dialog_content = "お前は…何度言えば分かるのだ。\nツキ様と呼ばんか！",
  ui_story_5020_50201301_80_dialog_content = "分かったわ、ツキお姉ちゃん！",
  ui_story_5020_50201301_81_dialog_content = "いいの、ナギ。\n子ども相手にそんなに怒っちゃだめよ。",
  ui_story_5020_50201301_82_dialog_content = "ヨウがお姉ちゃんって呼んでくれるということは、\n私はこの子に好かれているということでしょう？",
  ui_story_5020_50201301_83_dialog_content = "…ヨウは姉上が引き取った子ども、姉上の妹はこの私だ。",
  ui_story_5020_50201301_84_dialog_content = "分もわきまえさせず、姉上をお姉ちゃんなどと呼ばせていたら…\n私の立場がないではないか！",
  ui_story_5020_50201301_85_dialog_content = "くすくす…",
  ui_story_5020_50201301_86_dialog_content = "笑うな！",
  ui_story_5020_50201301_87_dialog_content = "はいはい、ヨウは少しおてんば過ぎるかもしれないけど、\nアメモリは言うことを聞くいい子ですね。",
  ui_story_5020_50201301_88_dialog_content = "あなたにこの子を任せたら、\nアメモリがあなたそっくりになってしまいました。",
  ui_story_5020_50201301_89_dialog_content = "ううむ…確かに筋はいいからな…",
  ui_story_5020_50201301_90_dialog_content = "どうしても色々と教えこみたくなってしまう。",
  ui_story_5020_50201301_91_dialog_content = "…ナギ？",
  ui_story_5020_50201301_92_dialog_content = "心配するな。お前の許しがない限り、\nこの子たちに「術」を教えるつもりはない。",
  ui_story_5020_50201301_93_dialog_content = "それに…アメモリは、\n背負わされているものが大きいようだ…",
  ui_story_5020_50201301_94_dialog_content = "まだ幼いというのに、\n年に似合わず感情が出ないように装っている…",
  ui_story_5020_50201301_95_dialog_content = "だからといって、\nまだ感情を消しきれるような歳ではない。",
  ui_story_5020_50201301_96_dialog_content = "確かに、その通りですね。",
  ui_story_5020_50201301_97_dialog_content = "引き取ってから、\n私はずっと自分の子どもだと思って接してきましたが…",
  ui_story_5020_50201301_98_dialog_content = "私には懐こうとせず、\nヨウとも一緒に遊びたがりません…",
  ui_story_5020_50201301_99_dialog_content = "けれど、あなたのことは好いているようですね。ナギ。",
  ui_story_5020_50201301_100_dialog_content = "私を？",
  ui_story_5020_50201301_101_dialog_content = "そうですよ。口数は少なくても、\nいつもあなたにくっついて、観察しています…",
  ui_story_5020_50201301_102_dialog_content = "好きな花まで、\nあなたの好みと全く一緒になってしまいました。",
  ui_story_5020_50201301_103_dialog_content = "あの年で、\n散る桜の美しさを愛でられるのですから。",
  ui_story_5020_50201301_104_dialog_content = "ん？",
  ui_story_5020_50201301_105_dialog_content = "ああ、もう桜が散る季節になったか。",
  ui_story_5020_50201301_106_dialog_content = "<size=33>…時が経つのは早いものですね。\n私ももうすぐ、本島に発たなければなりません。</size>",
  ui_story_5020_50201301_107_dialog_content = "何か言ったか？",
  ui_story_5020_50201301_108_dialog_content = "いいえ…何も。",
  ui_story_5020_50201301_109_dialog_content = "ナギ、私はしばらく雲島を離れます。",
  ui_story_5020_50201301_110_dialog_content = "私が帰ってきた時には、\nあなたは立派な頭領になっているでしょうね。",
  ui_story_5020_50201301_111_dialog_content = "なぜ今まで言わなかった？\nどこへ行く？何をしに？",
  ui_story_5020_50201301_112_dialog_content = "…アメモリとヨウを私に押しつけたのも、\nそれが理由か？",
  ui_story_5020_50201301_113_dialog_content = "ふふ…あの子たち、ずいぶんあなたに苦労させているようね…",
  ui_story_5020_50201301_114_dialog_content = "だからと言って、私を恨んでなどいないでしょう？",
  ui_story_5020_50201301_115_dialog_content = "…もちろん、恨んだりはするはずもない！",
  ui_story_5020_50201301_116_dialog_content = "それならよかった…",
  ui_story_5020_50201301_117_dialog_content = "これから先もそうであることを願います…",
  ui_story_5020_50201301_118_dialog_content = "姉上！？突然何を言い出すのだ。\n私が姉上を恨むことなど…",
  ui_story_5020_50201301_119_dialog_content = "どうでしょうね？",
  ui_story_5020_50201301_120_dialog_content = "今はまだ話せませんが、\n理由のないことでもありませんから…",
  ui_story_5020_50201301_121_dialog_content = "私がいない間、小さい頃に私たちが歌った歌を\n子どもたちに教えておいてくださいね。",
  ui_story_5020_50201301_122_dialog_content = "何をぼんやりしているんですか？\nまさか、忘れたんですか？",
  ui_story_5020_50201301_123_dialog_content = "も、もちろん、忘れてなどいない！",
  ui_story_5020_50201301_124_dialog_content = "確かに…今の季節にふさわしい歌だ。",
  ui_story_5020_50201301_125_dialog_content = "「手折りし花をわぎもに贈らん」…♪",
  ui_story_5020_50201301_126_dialog_content = "「玉雪の上に花落つる」…♪",
  ui_story_5020_50201301_127_dialog_content = "おや、ナギ…あなたの眉に桜の花びらが1枚、\n本当に落ちて来ましたよ。",
  ui_story_5020_50201301_128_dialog_content = "なに？取ってくれ、姉上…",
  ui_story_5020_50201301_129_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5020_50201301_130_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5020_50201401_1_dialog_content = "…",
  ui_story_5020_50201401_2_dialog_content = "…",
  ui_story_5020_50201401_3_dialog_content = "ツキお姉ちゃん…\nそういうことだったのね。",
  ui_story_5020_50201401_4_dialog_content = "だから、アタシが初めてリンネにあった時、\nすごく懐かしく感じたんだわ。",
  ui_story_5020_50201401_5_dialog_content = "なるほど、これで納得がいったわ。",
  ui_story_5020_50201401_6_dialog_content = "どこかで会ったことのあるような巫女、\n記憶の中に響く鈴の音…",
  ui_story_5020_50201401_7_dialog_content = "その時の記憶が、\n心のどこかに残ってたのね。",
  ui_story_5020_50201401_8_dialog_content = "でも、アタシ…",
  ui_story_5020_50201401_9_dialog_content = "…ヨウ？",
  ui_story_5020_50201401_10_dialog_content = "なんで、胸が苦しいの？",
  ui_story_5020_50201401_11_dialog_content = "記憶を取り戻すって、\n嬉しいことだと思ってたのに…",
  ui_story_5020_50201401_12_dialog_content = "アタシ、やっぱり…\n師匠のやり方は、理解できない。",
  ui_story_5020_50201401_13_dialog_content = "でも、アタシが師匠だったら、\nアタシはどうすればよかったんだろう…",
  ui_story_5020_50201401_14_dialog_content = "本島から帰って来た巫女は、\n雲島にとって裏切り者――",
  ui_story_5020_50201401_15_dialog_content = "もともと善悪の区別は簡単だったはずでしょ！？\nなのに、なんで…",
  ui_story_5020_50201401_16_dialog_content = "師匠より、アタシが辛い気持ちになるの…",
  ui_story_5020_50201401_17_dialog_content = "…この世界にはそもそも、\n白黒はっきりしないことがあふれてるからかもね。",
  ui_story_5020_50201401_18_dialog_content = "アストラ大陸でも、極東のこの島でも…",
  ui_story_5020_50201401_19_dialog_content = "誰もがそれぞれ自分の立場と信じるものがあって、\nそれぞれどうにもできないものを抱えているものよ。",
  ui_story_5020_50201401_20_dialog_content = "…そうなのかな。",
  ui_story_5020_50201401_21_dialog_content = "そうだ、最後に見た手記の…",
  ui_story_5020_50201401_22_dialog_content = "ええと…確か、この辺り…",
  ui_story_5020_50201401_22X_dialog_content = "あれ？",
  ui_story_5020_50201401_23_dialog_content = "すき間に<color=#FFB400>手紙</color>が入ってたわ？",
  ui_story_5020_50201401_24_dialog_content = "開封されてないみたいね。",
  ui_story_5020_50201401_25_dialog_content = "「拝啓、次代、の、巫女」…",
  ui_story_5020_50201401_26_dialog_content = "もしかして…リンネに宛てた手紙？",
  ui_story_5020_50201401_27_dialog_content = "PlayerName、後でリンネに渡しましょ。",
  ui_story_5020_50201401_28_dialog_content = "あ…それより、アタシが探してたのはここよ！",
  ui_story_5020_50201401_29_dialog_content = "巫女のお姉ちゃんが雲島を離れる前、\n師匠と別れる時…これって、一体どういう意味？",
  ui_story_5020_50201401_30_dialog_content = "その時、もう自分が巫女になることが分かってたのかな？",
  ui_story_5020_50201401_31_dialog_content = "師匠と雲島の人たちから、\n確実に恨まれるのに…",
  ui_story_5020_50201401_32_dialog_content = "それでも…選んだってことでしょうね。",
  ui_story_5020_50201401_33_dialog_content = "自分で選んだこと…？",
  ui_story_5020_50201401_34_dialog_content = "じゃあ、やっぱり――\nふっふ～ん…",
  ui_story_5020_50201401_35_dialog_content = "どう、アメモリ！？\n言ったでしょ、巫女のお姉ちゃん、絶対悪者じゃないって！",
  ui_story_5020_50201401_36_dialog_content = "雲島の平和を思ってた偉大な人だったのよ！",
  ui_story_5020_50201401_37_dialog_content = "…アメモリ？",
  ui_story_5020_50201401_38_dialog_content = "アメモリ…泣いてるの？",
  ui_story_5020_50201401_39_dialog_content = "泣いてなどおらぬ！",
  ui_story_5020_50201401_40_dialog_content = "（ヨウ、こういうことを煽るのはよくないよ…）",
  ui_story_5020_50201401_41_dialog_content = "拙者は…今まで知らなかった師匠のことを知り…",
  ui_story_5020_50201401_42_dialog_content = "そして初めて…師匠が他人に拙者のことをどう語っているか知った。",
  ui_story_5020_50201401_43_dialog_content = "かつて拙者は、自分のことを師匠とうり二つだと思っていた。",
  ui_story_5020_50201401_44_dialog_content = "幽燭の者にさえ、そう言われた。",
  ui_story_5020_50201401_45_dialog_content = "しかし、本当かどうかは、\n師匠にしか分からない。",
  ui_story_5020_50201401_46_dialog_content = "師匠は何年も修行をして、\n心も体も藤雲より強くなった…",
  ui_story_5020_50201401_47_dialog_content = "どのような力にも耐え、\n当時の藤雲と戦えるほどになった…",
  ui_story_5020_50201401_48_dialog_content = "外からの攻撃、ごますり、\n悪言、罵倒にも屈せず…",
  ui_story_5020_50201401_49_dialog_content = "しかし――封印の間に師匠を閉じ込めたのは、\n強くもないはずのツキの一撃だ。",
  ui_story_5020_50201401_50_dialog_content = "十年ぶりに師匠にまみえた時、\n最初に言われたことは…",
  ui_story_5020_50201401_51_dialog_content = "時として無情を装い、\n時として、あるべきでない同情と弱さを見せる。",
  ui_story_5020_50201401_52_dialog_content = "この世に生きるのなら、\n「情」など忘れてしまうことだ。",
  ui_story_5020_50201401_53_dialog_content = "師匠がご自身をいさめていたのかも知れぬ…",
  ui_story_5020_50201401_54_dialog_content = "…何言ってるの？キミと師匠は当然、違うでしょ。",
  ui_story_5020_50201401_55_dialog_content = "そんなこと、初めて師匠に会った時から分かってたわ。",
  ui_story_5020_50201401_56_dialog_content = "何…？",
  ui_story_5020_50201401_57_dialog_content = "じっくり聞きたい？オッホン…",
  ui_story_5020_50201401_58_dialog_content = "師匠は自分が何をしたいか、\nよく分かってる人でしょ。",
  ui_story_5020_50201401_59_dialog_content = "師匠だけじゃない、巫女のお姉ちゃんもそう…",
  ui_story_5020_50201401_60_dialog_content = "2人とも、その時やりたいことは何か、よく分かってた。",
  ui_story_5020_50201401_61_dialog_content = "でもアメモリ、師匠に言われたことをいったん忘れて、\nやりたくないけどやらされてることを抜きにしたら…",
  ui_story_5020_50201401_62_dialog_content = "<color=#FFB400>キミ自身</color>は、何がしたいの？",
  ui_story_5020_50201401_63_dialog_content = "…！？",
  ui_story_5020_50201401_64_dialog_content = "しかし、それを全部考えないとしたら、拙者には…",
  ui_story_5020_50201401_65_dialog_content = "何も…",
  ui_story_5020_50201401_66_dialog_content = "<color=#e8d9bb>ドンッ――！</color>",
  ui_story_5020_50201401_67_dialog_content = "<color=#e8d9bb>ドン、ドンドン、ドン――！</color>",
  ui_story_5020_50201401_68_dialog_content = "この音は…",
  ui_story_5020_50201401_69_dialog_content = "<color=#FFB400>太鼓の音</color>だわ。\nモモとアンズが叩いてるのよ！",
  ui_story_5020_50201401_70_dialog_content = "でも、どうして今になって…？\nもともと危うい状況ではあったけど…",
  ui_story_5020_50201401_71_dialog_content = "約束の合図だ！リンネたちが危ない！",
  ui_story_5020_50201401_72_dialog_content = "リンネ…！",
  ui_story_5020_50201401_73_dialog_content = "どこにいるの！？",
  ui_story_5020_50201401_74_dialog_content = "…幽燭の軍に助けを送るよう伝えて来る！",
  ui_story_5020_50201401_75_dialog_content = "いや、それは必要ないよ。",
  ui_story_5020_50201401_75X_dialog_content = "リンネは僕たちと別れてから、\nずっと幽燭軍と一緒に行動しているはずなんだ。",
  ui_story_5020_50201401_76_dialog_content = "つまり…みんなはたぶん、\n何か別の新しい戦いに巻き込まれてるんだ。",
  ui_story_5020_50201401_77_dialog_content = "巫女と幽燭の者が？\nそんなことが…",
  ui_story_5020_50201401_78_dialog_content = "アメモリ…「ほかに選べない」から仕方なくそれを選ぶ、\nっていうことも結構あるんだよ。",
  ui_story_5020_50201401_79_dialog_content = "とにかく…少なくとも、今この緊急事態で、\n自分が何をするべきかはよく分かってるはずだよね！",
  ui_story_5020_50201401_80_dialog_content = "…",
  ui_story_5020_50201401_81_dialog_content = "港の方角だ。",
  ui_story_5020_50201401_82_dialog_content = "ヨウ、手を出せ。",
  ui_story_5020_50201401_83_dialog_content = "ここに十年前の記憶が残っているというなら、\n我らはここで当時のことに決着を付けよう。",
  ui_story_5020_50201401_84_dialog_content = "フン、やっと息が合ったわね！",
  ui_story_5020_50201401_85_dialog_content = "行こう！太鼓の音がした――\n<color=#FFB400>港</color>を目指すよ！",
  ui_story_5020_50201401_86_dialog_content = "<color=#e8d9bb>江富城下町、とある街角</color>",
  ui_story_5020_50201401_87_dialog_content = "急いでください――皆様、しっかり付いて来てください！",
  ui_story_5020_50201401_88_dialog_content = "この川を下流に向かって進めば、港です。",
  ui_story_5020_50201401_89_dialog_content = "みんな急げ、急ぐんだ！\n指揮に従って、迅速に撤退しろ！",
  ui_story_5020_50201401_90_dialog_content = "港にさえ着けば、船で避難できるよう\n手はずは整えてある！",
  ui_story_5020_50201401_91_dialog_content = "江富の城からできるだけ遠くへ離れるんだ！",
  ui_story_5020_50201401_92_dialog_content = "何がどうなってるんだ…",
  ui_story_5020_50201401_93_dialog_content = "元頭領の兵士どもが将軍の巫女なんかと手を組むなんて…",
  ui_story_5020_50201401_93X_dialog_content = "…うわあっ！？",
  ui_story_5020_50201401_94_dialog_content = "尻をつついたのは誰だ！？",
  ui_story_5020_50201401_95_dialog_content = "ムダ話はつつしめ！\n次は柄じゃ済まんぞ！",
  ui_story_5020_50201401_96_dialog_content = "父さん…僕たちも早く巫女のお姉さんについて行こう。\n他の人たちが見てるよ…",
  ui_story_5020_50201401_97_dialog_content = "まだ燃えてる…僕、怖い…",
  ui_story_5020_50201401_98_dialog_content = "お、俺たちがなんで巫女に\nついていかないといけないんだ！",
  ui_story_5020_50201401_99_dialog_content = "裏切り者なんかについて行けば、船に乗るようだまされて…\n本島にさらわれてしまうぞ！",
  ui_story_5020_50201401_100_dialog_content = "藤雲みたいなヤツが百人はいるに違いない！",
  ui_story_5020_50201401_100X_dialog_content = "…うわぁ――！！！",
  ui_story_5020_50201401_101_dialog_content = "イテテ…あああああ！\n肩が、俺の肩が――",
  ui_story_5020_50201401_102_dialog_content = "と、父さん！？",
  ui_story_5020_50201401_103_dialog_content = "刀を持った犬のくせに、\n雲島の人間を助けたいのか、殺したいのか――",
  ui_story_5020_50201401_104_dialog_content = "…え？",
  ui_story_5020_50201401_105_dialog_content = "<anim type=Shake>グゥ…グオ――！！！</anim>",
  ui_story_5020_50201401_106_dialog_content = "お、鬼…！？\nもう界町まで鬼が――",
  ui_story_5020_50201401_107_dialog_content = "町の衆は避難の隊列に付いていけ！\nはぐれるんじゃないぞ！",
  ui_story_5020_50201401_108_dialog_content = "巫女、あんたが皆を先導しろ！\n俺がしんがりを務める！",
  ui_story_5020_50201401_109_dialog_content = "<anim type=Shake>グゥ！</anim>",
  ui_story_5020_50201401_110_dialog_content = "<size=45><anim type=Shake>グガア――！！</anim></size>",
  ui_story_5020_50201401_111_dialog_content = "<size=50><anim type=Shake>グガア――！！</anim></size>",
  ui_story_5020_50201401_112_dialog_content = "皆の者、刀をとれ！",
  ui_story_5020_50201401_113_dialog_content = "こいつらの魂ごとぶった斬れ！",
  ui_story_5020_50201401_114_dialog_content = "はあっ――！",
  ui_story_5020_50201501_1_dialog_content = "<color=#e8d9bb>江富城の港、埠頭近く</color>",
  ui_story_5020_50201501_2_dialog_content = "<color=#e8d9bb>ドン、ドンドン、ドン――！</color>",
  ui_story_5020_50201501_3_dialog_content = "人がたくさん…リンネはどこ！？",
  ui_story_5020_50201501_4_dialog_content = "仕方ないわね――",
  ui_story_5020_50201501_5_dialog_content = "リンネ！！",
  ui_story_5020_50201501_6_dialog_content = "どこ！？",
  ui_story_5020_50201501_7_dialog_content = "…ヨウ？",
  ui_story_5020_50201501_8_dialog_content = "ヨウ！！",
  ui_story_5020_50201501_9_dialog_content = "おや、アメモリにバイス様、\nPlayerName様まで…",
  ui_story_5020_50201501_10_dialog_content = "太鼓の音をお聞きになったのですね？",
  ui_story_5020_50201501_11_dialog_content = "PlayerNameの決断が速かったおかげよ！\n太鼓を聞いてすぐに来たの。",
  ui_story_5020_50201501_12_dialog_content = "状況はどう？ケガはない？",
  ui_story_5020_50201501_13_dialog_content = "つつがなく。\n江富城付近の民はほぼ移動を終えました。",
  ui_story_5020_50201501_14_dialog_content = "幽燭の方たちがすでに、\n一部を船で避難させています…",
  ui_story_5020_50201501_15_dialog_content = "じゃあ、リンネ自身は？大丈夫？\nあの人たちにイジメられたりしてない？",
  ui_story_5020_50201501_16_dialog_content = "ふふ…わたくしを心配して\nくださっているのですね。",
  ui_story_5020_50201501_17_dialog_content = "ご心配なく…こうして元気に立っております。\n皆様の方こそ、ご無事でしたか？",
  ui_story_5020_50201501_18_dialog_content = "アタシたちに何かあるワケないでしょ？\nPlayerName、早く<color=#FFB400>アレ</color>を出して！",
  ui_story_5020_50201501_19_dialog_content = "なんでしょう？",
  ui_story_5020_50201501_20_dialog_content = "「アレ」？ああ…分かったよ。",
  ui_story_5020_50201501_21_dialog_content = "リンネ。\nこれ、受け取って。",
  ui_story_5020_50201501_22_dialog_content = "これは…手紙ですか？",
  ui_story_5020_50201501_23_dialog_content = "わたくしに、でございますか？\n手紙の送り主は存じ上げませんが…",
  ui_story_5020_50201501_24_dialog_content = "「ツキ」は江富城の先代の巫女さんだよ。",
  ui_story_5020_50201501_25_dialog_content = "…分かりました。",
  ui_story_5020_50201501_26_dialog_content = "「拝啓　次代の巫女様…」",
  ui_story_5020_50201501_27_dialog_content = "最期を待つ間に\n何を書こうかずいぶん迷いました。",
  ui_story_5020_50201501_28_dialog_content = "私には見ることのできない未来がどうしても、\n少し不安に思えてなりません…",
  ui_story_5020_50201501_29_dialog_content = "あれこれ考えた果てに、\nいつか巫女を継ぐあなたのことが一番心配だと思い至りました。",
  ui_story_5020_50201501_30_dialog_content = "先達の導きがないということは、\nいささか難しいものです。",
  ui_story_5020_50201501_31_dialog_content = "「巫女」となった以上、その立場がもたらす\n数多くの困難と戦うことは、定めだと分かっていても…",
  ui_story_5020_50201501_32_dialog_content = "この手紙をお読みになっている時、\n雲島は、どのような季節でしょうか…",
  ui_story_5020_50201501_33_dialog_content = "雲島の桜の木は、満開の季節には燃え上がる雲のような\nあでやかさを見せ――",
  ui_story_5020_50201501_33X_dialog_content = "散り落ちる時には、まるで雪のよう――",
  ui_story_5020_50201501_34_dialog_content = "――雲島の人の多くからすれば、\n巫女もそのように美しく、はかない存在でしかないのでしょう。",
  ui_story_5020_50201501_35_dialog_content = "しかし私は、雲島の巫女は太陽のようであるべきだと、\nひとり輝き、この世界を守るべきだと思うのです…",
  ui_story_5020_50201501_36_dialog_content = "私たちは夜の闇と対等に立ち向かう。\nそれが、本島という雲にさえぎられることがあってもなりません。",
  ui_story_5020_50201501_37_dialog_content = "私たちの過去について知るのなら、\n同じ巫女であるあなたには説明するべきだと思いました。",
  ui_story_5020_50201501_38_dialog_content = "公方様は決して、空を覆う雨雲ではありません。\n少なくとも、私にとっては。",
  ui_story_5020_50201501_39_dialog_content = "雨雲ほど高くも遠くもない。\n私たちの頭上に掲げられた、傘にすぎません。",
  ui_story_5020_50201501_40_dialog_content = "公方様は決して善人ではありませんし、善事をしているわけでもありません。\nこの島に多くの不幸をもたらしたことも、事実…",
  ui_story_5020_50201501_41_dialog_content = "しかし、これはあの方が江富城にもたらすことのできる、\n最良の未来なのです。",
  ui_story_5020_50201501_42_dialog_content = "「最後に、この手紙を会ったこともない\nあなたに宛てる失礼をお許しください」",
  ui_story_5020_50201501_43_dialog_content = "「拝啓と書いたあと、一体誰の名を書くべきか、\n迷いに迷いました…」",
  ui_story_5020_50201501_44_dialog_content = "「このような時に書くものですから、\nどうしても感傷にひたった別れの手紙となってしまいます。」",
  ui_story_5020_50201501_45_dialog_content = "「ですから、この手紙は未来のあなたに\n開いていただくこととしました」",
  ui_story_5020_50201501_46_dialog_content = "「私の願いと共に、太陽のように生きてください」",
  ui_story_5020_50201501_47_dialog_content = "「あなたの先輩より　恐惶敬白」",
  ui_story_5020_50201501_48_dialog_content = "…",
  ui_story_5020_50201501_49_dialog_content = "不思議なことでございますね…",
  ui_story_5020_50201501_50_dialog_content = "江富城の巫女は、孤独だけが唯一の友と言える存在でございます。",
  ui_story_5020_50201501_51_dialog_content = "ですが、わたくしは先輩から力を頂いた気がいたします…",
  ui_story_5020_50201501_52_dialog_content = "今までの江富城の巫女は、\n確かにそうだったかも知れないね…",
  ui_story_5020_50201501_53_dialog_content = "でも、リンネ。君が変えたんだよ。\n気づいてない？",
  ui_story_5020_50201501_54_dialog_content = "わたくしが…？",
  ui_story_5020_50201501_55_dialog_content = "み、巫女様…船に乗る前に、\nこれをお受け取りください…",
  ui_story_5020_50201501_56_dialog_content = "袋いっぱいに入ってるよ。\nぜ～んぶ、お姉ちゃんにあげる！",
  ui_story_5020_50201501_57_dialog_content = "これは…魔除けと福招きの<color=#FFB400>福豆</color>？",
  ui_story_5020_50201501_58_dialog_content = "みんなが持っていた豆を全部集めたんだ。\nみんなで招いた福、全部この袋の中に入れたんだよ！",
  ui_story_5020_50201501_59_dialog_content = "お姉ちゃん、早くこの豆を使って、\n悪者たちをやっつけちゃって！",
  ui_story_5020_50201501_60_dialog_content = "俺たちの福が、巫女様を守ってくれますように…",
  ui_story_5020_50201501_61_dialog_content = "巫女様、この豆を戦いに持って行ってください。",
  ui_story_5020_50201501_62_dialog_content = "皆様…",
  ui_story_5020_50201501_63_dialog_content = "皆様…わたくしを信じてください。",
  ui_story_5020_50201501_64_dialog_content = "巫女、次の船が準備出来たぞ！\nこれで残りの全員、船に乗れる！",
  ui_story_5020_50201501_65_dialog_content = "分かりました。\nこの方たちを連れて、船にお乗りください。",
  ui_story_5020_50201501_66_dialog_content = "んん～？アメモリ、どうしたの？\nずいぶん静かじゃない？",
  ui_story_5020_50201501_67_dialog_content = "このままだと、\n幽燭軍に新しいお頭ができちゃうかもよ～？",
  ui_story_5020_50201501_68_dialog_content = "…拙者とリンネの間に、\n今さら交わすべき言葉などない。",
  ui_story_5020_50201501_69_dialog_content = "おや、冷たいではございませんか…",
  ui_story_5020_50201501_70_dialog_content = "しばらくぶりなのです。\nわたくしのことが恋しくなったりはしませんでしたか？",
  ui_story_5020_50201501_71_dialog_content = "…そ、それほどしばらくでもなかろう…",
  ui_story_5020_50201501_72_dialog_content = "とにかく、このような時に\n昔話をしているヒマはない！",
  ui_story_5020_50201501_73_dialog_content = "おおっ、頭領！？\nこちらにおられましたか！",
  ui_story_5020_50201501_74_dialog_content = "<size=45>アメモリ様ー！</size>",
  ui_story_5020_50201501_75_dialog_content = "言っただろう、頭領は拙者ではない！",
  ui_story_5020_50201501_76_dialog_content = "幽燭の方々はとてもしっかりしていらっしゃいました。\nあなたのお教えが行き届いておりますね、頭・領・様？",
  ui_story_5020_50201501_77_dialog_content = "おかげで、ここまで無事に協力することができました。",
  ui_story_5020_50201501_78_dialog_content = "ほらほら、リンネもアメモリも、\n争うなら堂々とやらないと！",
  ui_story_5020_50201501_79_dialog_content = "どっちが幽燭軍のお頭になるか競争――",
  ui_story_5020_50201501_80_dialog_content = "あいたた！頭が！",
  ui_story_5020_50201501_81_dialog_content = "おいたはほどほどに…／ふざけるな！",
  ui_story_5020_50201501_82_dialog_content = "世間話はここまでといたしましょう――",
  ui_story_5020_50201501_83_dialog_content = "鬼たちの速さからして、\nそろそろ港まで追いついて来るはずです。",
  ui_story_5020_50201501_84_dialog_content = "その前に、わたくしたちも\n手分けして備えましょう。PlayerName様？",
  ui_story_5020_50201501_85_dialog_content = "ええと、じゃあ…もう考えてあるの？",
  ui_story_5020_50201501_86_dialog_content = "アメモリとヨウは、幽燭の方々も連れて、\n界町から埠頭へ抜ける道の入口を守ってください。",
  ui_story_5020_50201501_87_dialog_content = "バイス様、PlayerName様はここで。\nアメモリたちの守りを抜けてきた鬼を片付けてください。",
  ui_story_5020_50201501_88_dialog_content = "わたくしは埠頭で、\n背後から包囲を狙う武士たちを迎え撃ちます。",
  ui_story_5020_50201501_89_dialog_content = "一人で大丈夫？",
  ui_story_5020_50201501_90_dialog_content = "まだお疑いになるのですか、PlayerName様？",
  ui_story_5020_50201501_91_dialog_content = "（リンネ…本当に、初めて会った時とはすっかり変わった…）",
  ui_story_5020_50201501_92_dialog_content = "じゃあ、すぐに行動しよう！",
  ui_story_5020_50201501_93_dialog_content = "うん！／了解！／承知！",
  ui_story_5020_50201501_94_dialog_content = "<anim type=Shake>グ…</anim>",
  ui_story_5020_50201501_95_dialog_content = "もう迫って来ているようだぞ。",
  ui_story_5020_50201501_96_dialog_content = "アタシの拳がうずいて仕方ないわ！",
  ui_story_5020_50201501_97_dialog_content = "どうやら、わたくしも急ぎ埠頭に向かわねばならないようですね。",
  ui_story_5020_50201501_98_dialog_content = "皆様、どうかこの戦いを乗り切ってくださいませ！",
  ui_story_5020_50201601_1_dialog_content = "<color=#e8d9bb>江富城の港、入口</color>",
  ui_story_5020_50201601_2_dialog_content = "<color=#e8d9bb>…ボゥ…メラメラ…</color>",
  ui_story_5020_50201601_3_dialog_content = "はぁ…はぁ…",
  ui_story_5020_50201601_4_dialog_content = "うっ…ゴホ、ゴホ！",
  ui_story_5020_50201601_5_dialog_content = "アメモリ様！",
  ui_story_5020_50201601_6_dialog_content = "ケガをされている！\n早く、アメモリ様を連れて退け！",
  ui_story_5020_50201601_7_dialog_content = "その必要はない。\nおぬしらは界町へ向けてこのまま進め…",
  ui_story_5020_50201601_8_dialog_content = "足を止めて守るばかりでは、\n負け戦を招く。",
  ui_story_5020_50201601_9_dialog_content = "兵力は分散せぬように固めろ。\nザコども相手でも、気を許すな。",
  ui_story_5020_50201601_10_dialog_content = "手強い相手がいたら、\n見逃してここまで来させるがいい…",
  ui_story_5020_50201601_11_dialog_content = "我らの手に託された天雲斬で片付ける！",
  ui_story_5020_50201601_12_dialog_content = "しかしアメモリ様、もう…",
  ui_story_5020_50201601_13_dialog_content = "おぬしら――命令が聞けぬというのか！？",
  ui_story_5020_50201601_14_dialog_content = "はっ…！",
  ui_story_5020_50201601_15_dialog_content = "<color=#e8d9bb>ガタガタガタ…</color>",
  ui_story_5020_50201601_16_dialog_content = "ぜぇ…ぜぇ…",
  ui_story_5020_50201601_17_dialog_content = "気を付けて！",
  ui_story_5020_50201601_18_dialog_content = "<anim type=Shake>グワアッ！！！</anim>",
  ui_story_5020_50201601_19_dialog_content = "セイッ…！うっ…",
  ui_story_5020_50201601_20_dialog_content = "アメモリ！！！",
  ui_story_5020_50201601_21_dialog_content = "油断した…拙者が甘かった。",
  ui_story_5020_50201601_22_dialog_content = "ヨウ…後ろを頼めるか？",
  ui_story_5020_50201601_23_dialog_content = "わ、分かったけど、どうして…",
  ui_story_5020_50201601_24_dialog_content = "いや、そういうことね…",
  ui_story_5020_50201601_25_dialog_content = "小さい頃、リン家で教わったわ。\n真の戦士は真正面から敵を迎え撃つもの、って。",
  ui_story_5020_50201601_26_dialog_content = "忍者の戦い方も同じなの？",
  ui_story_5020_50201601_27_dialog_content = "戦っている時、\n敵に背中を取られるわけにはいかん。",
  ui_story_5020_50201601_28_dialog_content = "忍びはいかなる方向からの奇襲もはね返せる…",
  ui_story_5020_50201601_29_dialog_content = "しかし、今のように、力及ばぬ時には…",
  ui_story_5020_50201601_30_dialog_content = "おぬしに背中を任せても、構うまいな？",
  ui_story_5020_50201601_31_dialog_content = "フフン、聞く必要ある？",
  ui_story_5020_50201601_32_dialog_content = "キミがケガしてなかったとしても、\nアタシたちの間に「斥鬼凌人の玉」の絆がなかったとしても…",
  ui_story_5020_50201601_33_dialog_content = "キミがアタシと一緒に戦う仲間なら――",
  ui_story_5020_50201601_34_dialog_content = "助けない理由なんてないでしょ！",
  ui_story_5020_50201601_35_dialog_content = "ふん…きれいごとを言っている時ではなくなりそうだ。",
  ui_story_5020_50201601_36_dialog_content = "次の敵がすぐにくるぞ…",
  ui_story_5020_50201601_37_dialog_content = "準備はいいか？<color=#FFB400>妹弟子</color>よ。",
  ui_story_5020_50201601_38_dialog_content = "もちろん、まだまだ余裕よ！",
  ui_story_5020_50201601_39_dialog_content = "はぁああっ――",
  ui_story_5020_50201601_40_dialog_content = "はあ…はあ…",
  ui_story_5020_50201601_41_dialog_content = "アメモリ、もう少しのガマンよ…",
  ui_story_5020_50201601_42_dialog_content = "はぁ…はぁ……無論だ…",
  ui_story_5020_50201601_43_dialog_content = "…ヨウ、天雲斬を持て！",
  ui_story_5020_50201601_44_dialog_content = "辺りの空気がおかしい…",
  ui_story_5020_50201601_45_dialog_content = "わかったわ！",
  ui_story_5020_50201601_46_dialog_content = "何がおかしいの…？\nアタシたちはどうする？",
  ui_story_5020_50201601_47_dialog_content = "…まず界町だ。\n埠頭のリンネと民の安全を少しでも確実にする。",
  ui_story_5020_50201601_48_dialog_content = "常に回りの物音に気を配れ…",
  ui_story_5020_50201601_49_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5020_50201601_50_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5020_50201601_51_dialog_content = "（2時の方向で幽燭の軍と鬼の戦闘…）",
  ui_story_5020_50201601_52_dialog_content = "（10時の方向に人の足音…）",
  ui_story_5020_50201601_53_dialog_content = "（7時の方向、森の中…飛び立った鳥が、6羽…）",
  ui_story_5020_50201601_54_dialog_content = "（おかしい。音に異常はない！\nどういうことだ…）",
  ui_story_5020_50201601_55_dialog_content = "…",
  ui_story_5020_50201601_56_dialog_content = "え！？アメモリ、あれ！見て！！早く！！",
  ui_story_5020_50201601_57_dialog_content = "あれって…",
  ui_story_5020_50201601_58_dialog_content = "逃げ遅れた人？",
  ui_story_5020_50201601_59_dialog_content = "でも、まだこんな所にいるなんて…",
  ui_story_5020_50201601_60_dialog_content = "…ヨウ！気を付けろ！",
  ui_story_5020_50201601_61_dialog_content = "え！？",
  ui_story_5020_50201601_62_dialog_content = "<anim type=Shake>…グ…ガア…</anim>",
  ui_story_5020_50201601_63_dialog_content = "い…いま、なんて…？",
  ui_story_5020_50201601_64_dialog_content = "<anim type=Shake>グ…</anim>",
  ui_story_5020_50201601_65_dialog_content = "<size=50><anim type=Shake>グオオオ――！！！</anim></size>",
  ui_story_5020_50201601_66_dialog_content = "まさか…将軍！？",
  ui_story_5020_50201601_67_dialog_content = "…いかん！",
  ui_story_5020_50201601_68_dialog_content = "（師匠とやり合った藤雲が、\n当然のように港までやって来られるとは…）",
  ui_story_5020_50201601_69_dialog_content = "（まさか、まさか師匠が…）",
  ui_story_5020_50201601_70_dialog_content = "な、何よ、この化け物！？",
  ui_story_5020_50201601_71_dialog_content = "<anim type=Shake>放せ…</anim>",
  ui_story_5020_50201601_72_dialog_content = "<anim type=Shake>それを…放せ…</anim>",
  ui_story_5020_50201601_73_dialog_content = "ヨウ、天雲斬を手放すな…",
  ui_story_5020_50201601_74_dialog_content = "今、奴と戦っても、勝ち目はない…",
  ui_story_5020_50201601_75_dialog_content = "だが、天雲斬だけは渡してはならん！",
  ui_story_5020_50201601_76_dialog_content = "師匠はどうした！？",
  ui_story_5020_50201601_77_dialog_content = "<anim type=Shake>殺…</anim>",
  ui_story_5020_50201601_78_dialog_content = "<anim type=Shake>…殺…し…</anim>",
  ui_story_5020_50201601_79_dialog_content = "な…！？",
  ui_story_5020_50201601_80_dialog_content = "……",
  ui_story_5020_50201601_81_dialog_content = "貴様、よくも…！",
  ui_story_5020_50201601_82_dialog_content = "うっ！ゲホ、ゴホ…",
  ui_story_5020_50201601_83_dialog_content = "（どうする…もう…限界だ…）",
  ui_story_5020_50201601_84_dialog_content = "<color=#e8d9bb>シュン！</color>",
  ui_story_5020_50201601_85_dialog_content = "速射感知！",
  ui_story_5020_50201601_86_dialog_content = "神域を――ここに！",
  ui_story_5020_50201601_87_dialog_content = "みんな…",
  ui_story_5020_50201601_88_dialog_content = "2人とも、もう大丈夫よ！",
  ui_story_5020_50201601_89_dialog_content = "私たちの方は、もうきれいに片付いたわ。\nあとは全力で道を守るだけよ！",
  ui_story_5020_50201601_90_dialog_content = "お二人とも、とにかく急いで結界の中へ。\nわたくしが…",
  ui_story_5020_50201601_91_dialog_content = "あ…",
  ui_story_5020_50201601_92_dialog_content = "こ、これは…",
  ui_story_5020_50201601_93_dialog_content = "<size=45><anim type=Shake>グオオ！！！</anim></size>",
  ui_story_5020_50201601_94_dialog_content = "<anim type=Shake>リン…ネ…</anim>",
  ui_story_5020_50201601_95_dialog_content = "<anim type=Shake>そなたは………</anim>",
  ui_story_5020_50201601_96_dialog_content = "<size=50><anim type=Shake>グオオオ――！！！</anim></size>",
  ui_story_5020_50201601_97_dialog_content = "まさか、将軍！？\n自分自身も…こんな姿に！？",
  ui_story_5020_50201601_98_dialog_content = "ゴホッ…奴がどのような姿になろうと、\n今さらどうでもよい！",
  ui_story_5020_50201601_99_dialog_content = "急げ！天雲斬で奴を…",
  ui_story_5020_50201601_100_dialog_content = "リンネ！受け取って！",
  ui_story_5020_50201601_101_dialog_content = "これは…！",
  ui_story_5020_50201601_102_dialog_content = "（巫女が代々受け継いできた神器…）",
  ui_story_5020_50201601_103_dialog_content = "（本来巫女が持っているべきものでありながら、\n公方様が隠した鬼斬りの剣…）",
  ui_story_5020_50201601_104_dialog_content = "<color=#e8d9bb>ザッ…ザッ…</color>",
  ui_story_5020_50201601_105_dialog_content = "（ああ…将軍、公方様…\n最後とあれば、お父上とお呼びするべきでしょうか…）",
  ui_story_5020_50201601_106_dialog_content = "（剣を握る手が、どうしても震えて…）",
  ui_story_5020_50201601_107_dialog_content = "（怖れ、緊張、高ぶり…入り交じったこの心を、どうすれば…）",
  ui_story_5020_50201601_108_dialog_content = "（…そのことは…教わっておりませんでしたね…）",
  ui_story_5020_50201601_109_dialog_content = "<size=50><anim type=Shake>グオオオ――！！！</anim></size>",
  ui_story_5020_50201601_110_dialog_content = "お父上…",
  ui_story_5020_50201601_111_dialog_content = "受けて――くださいませ！！",
  ui_story_5020_50201602_1_dialog_content = "<anim type=Shake>グ…！</anim>",
  ui_story_5020_50201602_2_dialog_content = "はあ…はあ…",
  ui_story_5020_50201602_3_dialog_content = "リンネ、今だ！",
  ui_story_5020_50201602_4_dialog_content = "はあっ――！",
  ui_story_5020_50201602_5_dialog_content = "<size=50><anim type=Shake>グガアアアアアアアアアアア！！！</anim></size>",
  ui_story_5020_50201602_6_dialog_content = "<anim type=Shake>うう――</anim>",
  ui_story_5020_50201602_7_dialog_content = "<anim type=Shake>はぁ…はぁ…</anim>",
  ui_story_5020_50201602_8_dialog_content = "…",
  ui_story_5020_50201602_9_dialog_content = "やったわ！",
  ui_story_5020_50201602_10_dialog_content = "鬼の形のみをはらい、再び人に戻した…",
  ui_story_5020_50201602_11_dialog_content = "これが天雲斬の力…",
  ui_story_5020_50201602_12_dialog_content = "リンネ…そなたら…\nやはり、天雲斬まで持ち出したか…",
  ui_story_5020_50201602_13_dialog_content = "見事…誉めてつかわす…",
  ui_story_5020_50201602_14_dialog_content = "こちらへ…",
  ui_story_5020_50201602_15_dialog_content = "あなたは…",
  ui_story_5020_50201602_16_dialog_content = "決して許されないことに\n多く手をお染めになりました…",
  ui_story_5020_50201602_17_dialog_content = "やむを得ない事情があったとしても、それは…\n力と引き換えにされるべきものではございません。",
  ui_story_5020_50201602_18_dialog_content = "江富城の火は、もう鎮まります…",
  ui_story_5020_50201602_19_dialog_content = "…あなたもお休みになられてください…",
  ui_story_5020_50201602_20_dialog_content = "やむを得ない、か。ハハハ…",
  ui_story_5020_50201602_21_dialog_content = "そなた…手紙を読んだな。",
  ui_story_5020_50201602_22_dialog_content = "今見えている「やむを得ない」ことの他にも、\nそなたが理解できないことなど、山とある…",
  ui_story_5020_50201602_23_dialog_content = "…だが、「やむを得ない」などという言葉は、\nそもそも子どもの口から出るものではない…",
  ui_story_5020_50201602_24_dialog_content = "リンネ…大きくなったのだな。",
  ui_story_5020_50201602_25_dialog_content = "もう…「公方様」とさえ呼んではくれぬのか。",
  ui_story_5020_50201602_26_dialog_content = "…",
  ui_story_5020_50201602_27_dialog_content = "フン、アンタにはふさわしくないわ！",
  ui_story_5020_50201602_28_dialog_content = "お前の命運もここまでだ。",
  ui_story_5020_50201602_29_dialog_content = "周りをよく見るがいい。",
  ui_story_5020_50201602_30_dialog_content = "ぺっ！当然の報いだ。",
  ui_story_5020_50201602_31_dialog_content = "ひざまずけ…そうだそうだ、もっと頭を下げろ…ハハハ！\nあの藤雲大将軍サマに、こんな日がくるとはな！",
  ui_story_5020_50201602_32_dialog_content = "何をムダ話している！さっさと斬るのだ。\n皆の者、そいつを一刀のもとに斬り捨てて、春日祭に奉げよう！",
  ui_story_5020_50201602_33_dialog_content = "そうだ――やってしまえ！…",
  ui_story_5020_50201602_34_dialog_content = "ハハ……ハハハハ……",
  ui_story_5020_50201602_35_dialog_content = "無礼者！",
  ui_story_5020_50201602_36_dialog_content = "愚かな民草どもめ！\n公方様を殺せば、本島に牙を剥いたとみなされるぞ！",
  ui_story_5020_50201602_37_dialog_content = "ぺっ、本島が何だ！",
  ui_story_5020_50201602_38_dialog_content = "お前の後ろを見るがいい。まともな人のなりをした武士が何人いる？\n当然の報いだ！",
  ui_story_5020_50201602_39_dialog_content = "やってしまえ！",
  ui_story_5020_50201602_40_dialog_content = "<color=#e8d9bb>ザァアア――</color>",
  ui_story_5020_50201602_41_dialog_content = "無礼者めが！",
  ui_story_5020_50201602_42_dialog_content = "さがれ…ゴホ、ゴホ…さがるのだ…",
  ui_story_5020_50201602_43_dialog_content = "藤雲様が死ねば、雲島がよくなるのか！？",
  ui_story_5020_50201602_44_dialog_content = "…",
  ui_story_5020_50201602_45_dialog_content = "お前たちが今の将軍を殺したとて…",
  ui_story_5020_50201602_46_dialog_content = "半月もせずに、本島から新しい将軍が\n引き継ぎに来るだけだ！",
  ui_story_5020_50201602_47_dialog_content = "その時、おぬしらの恨みを\nどうするというのだ！？",
  ui_story_5020_50201602_48_dialog_content = "お前たち逆賊にとって、\n公方様は目ざわりなよそ者の仲間かもしれん！",
  ui_story_5020_50201602_49_dialog_content = "しかし、公方様とて、\nそのよそ者に操られているにすぎんのだ！",
  ui_story_5020_50201602_50_dialog_content = "誰か…誰かある！\nそこのやかましい者を…黙らせろ…",
  ui_story_5020_50201602_51_dialog_content = "（違う、将軍は、この人は…）",
  ui_story_5020_50201602_52_dialog_content = "いいえ、公方様！\n続けさせてください！",
  ui_story_5020_50201602_53_dialog_content = "公方様は本島と雲島との間で、\n何とか安定を保とうと苦心し…",
  ui_story_5020_50201602_54_dialog_content = "雲島の平和のために尽くしてきたのだ。\nそのお心がおぬしらに分かるというのか！？",
  ui_story_5020_50201602_55_dialog_content = "お前たちの言う通り、やり方は歪んでいたかもしれない…\n公方様の御心も、歪んでいたかもしれん…",
  ui_story_5020_50201602_56_dialog_content = "だが、公方様が追い求めた物まで、\n本当に間違っていたというのか！？",
  ui_story_5020_50201602_57_dialog_content = "…",
  ui_story_5020_50201602_58_dialog_content = "言ってることが正しいとは思わねぇが…",
  ui_story_5020_50201602_59_dialog_content = "まぁ、筋は通ってるよな…",
  ui_story_5020_50201602_60_dialog_content = "俺も今までずっとそう思ってたんだ。\n周りの庶民は、上の奴らのやってることなんざ、分かるはずもない…",
  ui_story_5020_50201602_61_dialog_content = "もし俺が雲島を統治できるなら、\nこの藤雲なんかより何百倍もうまくやってみせるぜ！",
  ui_story_5020_50201602_62_dialog_content = "おい、どういう意味だ？簡単に乗せられやがって！",
  ui_story_5020_50201602_63_dialog_content = "敵に寝返る前に、まず俺を倒してみろ！\n一番気に食わねえのは、お前みたいな安っぽい裏切り者だ！",
  ui_story_5020_50201602_64_dialog_content = "<color=#e8d9bb>ガヤガヤ…ザワザワ…</color>",
  ui_story_5020_50201602_65_dialog_content = "ああ…公方様はおぬしらの理解など望んでおらぬ。",
  ui_story_5020_50201602_66_dialog_content = "おぬしらに理解されることなど、\n公方様への侮辱以外のなにものでもない！",
  ui_story_5020_50201602_67_dialog_content = "黙れ…黙れ！！",
  ui_story_5020_50201602_68_dialog_content = "その通りだ、全員黙れ！",
  ui_story_5020_50201602_69_dialog_content = "公方様のことを理解できる者など、\nこの世に一握りとおらぬ…",
  ui_story_5020_50201602_70_dialog_content = "公方様、それがしはこの世で誰よりも\nあなた様のお考えを理解しております！",
  ui_story_5020_50201602_71_dialog_content = "もういい！",
  ui_story_5020_50201602_72_dialog_content = "口を閉じろ。バカが漏れるぞ。",
  ui_story_5020_50201602_73_dialog_content = "な…何者だ！？無礼な！？",
  ui_story_5020_50201602_74_dialog_content = "…",
  ui_story_5020_50201602_75_dialog_content = "来たか…",
  ui_story_5020_50201701_1_dialog_content = "あ、あの女は…",
  ui_story_5020_50201701_2_dialog_content = "まだ生きていたのか？",
  ui_story_5020_50201701_3_dialog_content = "父さん…あの人は誰――",
  ui_story_5020_50201701_4_dialog_content = "シーッ！",
  ui_story_5020_50201701_5_dialog_content = "やたらに聞くもんじゃない、黙ってろ！",
  ui_story_5020_50201701_6_dialog_content = "（師匠！？）",
  ui_story_5020_50201701_7_dialog_content = "まったく…",
  ui_story_5020_50201701_8_dialog_content = "大したご高説じゃないか。",
  ui_story_5020_50201701_9_dialog_content = "お前の家臣にこれほどお前をバカにすることが\n上手い者がいたとはな？",
  ui_story_5020_50201701_10_dialog_content = "何ぃ…！？",
  ui_story_5020_50201701_11_dialog_content = "うぐっ！？",
  ui_story_5020_50201701_12_dialog_content = "邪魔立てするな。",
  ui_story_5020_50201701_13_dialog_content = "…",
  ui_story_5020_50201701_14_dialog_content = "この時をずっと待っていたのだろう、藤雲の。",
  ui_story_5020_50201701_15_dialog_content = "遅かったな。",
  ui_story_5020_50201701_16_dialog_content = "もうずいぶん前から、来てはいた。",
  ui_story_5020_50201701_17_dialog_content = "余計に痛めつけられるところを眺めているのも、\nなかなか悪くないと思ってな。",
  ui_story_5020_50201701_18_dialog_content = "お前は誰かに認められることなど望んではいない。\nやることはやった。もう後はまもなく訪れる、死を待つのみ。",
  ui_story_5020_50201701_19_dialog_content = "どうだ、違うか？",
  ui_story_5020_50201701_20_dialog_content = "…フハハ…",
  ui_story_5020_50201701_21_dialog_content = "戦場で死ぬことは余にとって、悲劇ではない…\nそれが英雄のあるべき末路だ。",
  ui_story_5020_50201701_22_dialog_content = "さっさと終わらせるがいい…",
  ui_story_5020_50201701_23_dialog_content = "おぬしの手にかかるのなら…",
  ui_story_5020_50201701_24_dialog_content = "藤雲の。お前は下劣なまねばかりしてきた…",
  ui_story_5020_50201701_25_dialog_content = "最期になって、\n今さら面目を保ちたいとでもいうのか？",
  ui_story_5020_50201701_26_dialog_content = "ハハハ…ゴホ、ゴホ…",
  ui_story_5020_50201701_27_dialog_content = "ナギ、おぬしの刀さばきは鋭いが…",
  ui_story_5020_50201701_28_dialog_content = "振る時は迷うことなく振るがいい。\nおぬし自身を辱めることがないようにな。",
  ui_story_5020_50201701_29_dialog_content = "ふん、心配無用だ。",
  ui_story_5020_50201701_30_dialog_content = "<color=#e8d9bb>ザッ…ザッ…</color>",
  ui_story_5020_50201701_31_dialog_content = "…",
  ui_story_5020_50201701_32_dialog_content = "言い残すことはあるか？",
  ui_story_5020_50201701_33_dialog_content = "…",
  ui_story_5020_50201701_34_dialog_content = "ツキ…",
  ui_story_5020_50201701_35_dialog_content = "今の江富城は、そなたが見たかった江富城か…？",
  ui_story_5020_50201701_36_dialog_content = "…",
  ui_story_5020_50201701_37_dialog_content = "……",
  ui_story_5020_50201701_38_dialog_content = "し…死んだのか…？",
  ui_story_5020_50201701_39_dialog_content = "死んだんだよな？",
  ui_story_5020_50201701_40_dialog_content = "もう息をしてない…",
  ui_story_5020_50201701_41_dialog_content = "死んだ！死んだぞ…本当に…！",
  ui_story_5020_50201701_42_dialog_content = "藤雲が死んだ！\n雲島にはもう将軍なんかいないんだ！！",
  ui_story_5020_50201701_43_dialog_content = "<size=50><anim type=Shake>おぉぉぉぉ！！！</anim></size>",
  ui_story_5020_50201701_44_dialog_content = "<size=50><anim type=Shake>将軍が死んだ――！！！</anim></size>",
  ui_story_5020_50201701_45_dialog_content = "<size=50><anim type=Shake>雲島万歳――！！！</anim></size>",
  ui_story_5020_50201701_46_dialog_content = "<anim type=Shake>うおおぉぉぉ…</anim>",
  ui_story_5020_50201701_47_dialog_content = "…",
  ui_story_5020_50201701_48_dialog_content = "と…頭領！",
  ui_story_5020_50201701_49_dialog_content = "い、生きていらしたのですか！？",
  ui_story_5020_50201701_50_dialog_content = "本当に、あのナギ様ですか？",
  ui_story_5020_50201701_51_dialog_content = "頭領？ど…どこへ行くのです！？",
  ui_story_5020_50201701_52_dialog_content = "待って！",
  ui_story_5020_50201701_53_dialog_content = "…？",
  ui_story_5020_50201701_54_dialog_content = "お前らか…",
  ui_story_5020_50201701_55_dialog_content = "何か言いたいのなら、早く言え。",
  ui_story_5020_50201701_56_dialog_content = "師匠、待って！",
  ui_story_5020_50201701_57_dialog_content = "師匠、アタシ…お礼を言いたいの！",
  ui_story_5020_50201701_58_dialog_content = "…どういうつもりだ？",
  ui_story_5020_50201701_59_dialog_content = "アタシは雲島に来て、いろいろ大変な目に遭いました。\nそれもこれも師匠のおかげです！",
  ui_story_5020_50201701_60_dialog_content = "（…それ、お礼って言うの？）",
  ui_story_5020_50201701_61_dialog_content = "師匠のおかげで、アタシは師匠たちの代の人たちが経験した、\n立場が違う者同士の争いを、身をもって知りました。",
  ui_story_5020_50201701_62_dialog_content = "どれもこれも…アタシの今までの人生の中で、\n経験したことのないものでした。",
  ui_story_5020_50201701_63_dialog_content = "だから、そのことだけでも…師匠と呼ばせてください。",
  ui_story_5020_50201701_64_dialog_content = "あと、これから先、何か困ったことがあったら、\nアストラ大陸、影ノ街にあるリン家商会に連絡してください！",
  ui_story_5020_50201701_65_dialog_content = "どこにいようと、アタシが絶対\n師匠の所に飛んで行ってお助けします！",
  ui_story_5020_50201701_66_dialog_content = "ハハ…感謝する、ヨウ。",
  ui_story_5020_50201701_67_dialog_content = "ただ、この先の道は、\n私ひとりで歩まねばならんのだ。",
  ui_story_5020_50201701_68_dialog_content = "この手で雲島を本当の統治から解き放ってようやく、\n我らの恨みが果たされる。",
  ui_story_5020_50201701_69_dialog_content = "…本島に向かわれるおつもりですか？",
  ui_story_5020_50201701_70_dialog_content = "師匠、どうか…",
  ui_story_5020_50201701_71_dialog_content = "お身体を大切になさってください。\nそして、雲島のために新たな世界を拓いてください…",
  ui_story_5020_50201701_72_dialog_content = "拙者と幽燭の軍が、永遠に力となります…",
  ui_story_5020_50201701_73_dialog_content = "ほう？アメモリ…",
  ui_story_5020_50201701_74_dialog_content = "ようやく成長したな。",
  ui_story_5020_50201701_75_dialog_content = "私よりも、お前の方が\n幽燭の軍をうまくまとめられるだろう。",
  ui_story_5020_50201701_76_dialog_content = "ナギ様、どうかご自愛を！\n凱旋をお待ち申し上げます！",
  ui_story_5020_50201701_77_dialog_content = "…",
  ui_story_5020_50201701_78_dialog_content = "では、さらばだ。",
  ui_story_5020_50201701_79_dialog_content = "あ！待ってください…",
  ui_story_5020_50201701_80_dialog_content = "PlayerName、あれを渡しましょう。",
  ui_story_5020_50201701_81_dialog_content = "あ…そ、そうだね！",
  ui_story_5020_50201701_82_dialog_content = "何だ？",
  ui_story_5020_50201701_83_dialog_content = "この手記を受け取って。",
  ui_story_5020_50201701_84_dialog_content = "お言葉をじかに残されたわけではございませんが…",
  ui_story_5020_50201701_85_dialog_content = "先代の巫女様の形見とあれば、\nあなた様にとって大切なものでございましょう。",
  ui_story_5020_50201701_86_dialog_content = "お持ちになってください。",
  ui_story_5020_50201701_87_dialog_content = "ツキ…日記をつけていたのか…",
  ui_story_5020_50201701_88_dialog_content = "知らなかった…",
  ui_story_5020_50201701_89_dialog_content = "だが、私はもう振り返らず、\n本島に向かうと決めたのだ。",
  ui_story_5020_50201701_90_dialog_content = "代わりに持っていてくれ。",
  ui_story_5020_50201701_91_dialog_content = "本当に…読んでみる気はないの？",
  ui_story_5020_50201701_92_dialog_content = "過去を振り払うってことは、目を背けて逃げることじゃないよ。\n向き合って、受け止めないと。",
  ui_story_5020_50201701_93_dialog_content = "これを読めば、抱いていた疑問にも、\n恨みにも、きっと答えが出るはず。",
  ui_story_5020_50201701_94_dialog_content = "…",
  ui_story_5020_50201701_95_dialog_content = "…そうだな。",
  ui_story_5020_50201701_96_dialog_content = "…",
  ui_story_5020_50201701_97_dialog_content = "…",
  ui_story_5020_50201701_98_dialog_content = "<size=30>姉上…</size>",
  ui_story_5020_50201701_99_dialog_content = "姉上…",
  ui_story_5020_50201701_100_dialog_content = "<color=#e8d9bb>江富城下町、とある街角</color>",
  ui_story_5020_50201701_101_dialog_content = "おや、実になごやかな景色でございますね…",
  ui_story_5020_50201701_102_dialog_content = "舞台の色あざやかな幕、開催の時を待ちわびる太鼓、\n桜の下で金魚すくいを楽しむ人々…",
  ui_story_5020_50201701_103_dialog_content = "それから、わたくしの側に大人しく座り、\n場を乱すこともない忍者殿…",
  ui_story_5020_50201701_104_dialog_content = "…その呼び方は止めてもらいたい。",
  ui_story_5020_50201701_105_dialog_content = "モモとアンズの気持ちをむげにしてはいけません。\n本当においしいお茶でございますよ？",
  ui_story_5020_50201701_106_dialog_content = "…味の濃いものは好かん。\nこの店の物は、何一つ口にするつもりはない。",
  ui_story_5020_50201701_107_dialog_content = "（グウゥ…）",
  ui_story_5020_50201701_108_dialog_content = "うっ…！",
  ui_story_5020_50201701_109_dialog_content = "は～い、どうぞ、お待たせしました～！",
  ui_story_5020_50201701_110_dialog_content = "当店自信の新作――\nカニ家式、流しそうめんをどうぞ！",
  ui_story_5020_50201701_111_dialog_content = "ヨウに何度も試食してもらってやっとできた、\n当店だけのレシピだよ！",
  ui_story_5020_50201701_112_dialog_content = "ゲフッ…ああ、お腹いっぱい…",
  ui_story_5020_50201701_113_dialog_content = "（あのヨウが…満腹！？）",
  ui_story_5020_50201701_114_dialog_content = "そ…そうか…",
  ui_story_5020_50201701_115_dialog_content = "ならば、拙者も少しは食わんでもない…",
  ui_story_5020_50201701_116_dialog_content = "新メニューが出来たからには、\nセットでお話する物語も決めておかなきゃ！",
  ui_story_5020_50201701_117_dialog_content = "同じ話ばっかりじゃ、\nお客さんに飽きられちゃうわ！",
  ui_story_5020_50201701_118_dialog_content = "PlayerName、どんな話がいいと思う？",
  ui_story_5020_50201701_119_dialog_content = "え！？僕に聞くの？",
  ui_story_5020_50201701_120_dialog_content = "僕の好みで言うなら…",
  ui_story_5020_50201701_121_option_content = "「3人の旧友」なんてどうかな",
  ui_story_5020_50201701_122_dialog_content = "生涯切っても切れない縁でつながっていた3人が、\nそれぞれの方法で一つの場所を守ろうとした。",
  ui_story_5020_50201701_123_dialog_content = "姉は巫女になり、妹は剣士になった。やがて決別するしかなくなってしまったけど、\n二人の歌はそれでもこの土地に長く伝わってる。",
  ui_story_5020_50201701_124_dialog_content = "人々から理解されることのなかった巫女と将軍は、\n立場が違いながらも、互いを少し信用するようになった。",
  ui_story_5020_50201701_125_dialog_content = "敵同士になる定めだった将軍と剣士は、\n互いに相手を理解し、最後の戦いで永遠の別れを告げた。",
  ui_story_5020_50201701_126_dialog_content = "そして三人とも、これからこの地は自分の思い描いた\n平和に向かっていくと考えている…",
  ui_story_5020_50201701_127_dialog_content = "ううん…ここに伝わる話として、\n食事しながら聞くのによさそうね。",
  ui_story_5020_50201701_128_option_content = "「3人の子供」なんてどうかな",
  ui_story_5020_50201701_129_dialog_content = "3人の子供たちがそれぞれ違う理由で、\n妖怪退治の旅に出た…",
  ui_story_5020_50201701_130_dialog_content = "けれど、その旅の中で、\nそれぞれが勝利よりも大切なものを手に入れた。",
  ui_story_5020_50201701_131_dialog_content = "顔を隠したブリキの木こりは、\n「友情に満たされた心」を…",
  ui_story_5020_50201701_132_dialog_content = "かつて海に沈んだカカシの子は、\n「思い出の詰まった頭」を…",
  ui_story_5020_50201701_133_dialog_content = "お芝居の衣装を身にまとった小さなライオンは、\n「運命に抗う勇気」を得た…",
  ui_story_5020_50201701_134_dialog_content = "まるきり北境のおとぎ話じゃない！\nここで聞くには場違いでしょ！？",
  ui_story_5020_50201701_135_dialog_content = "ううん…なかなかいい発想だね～。",
  ui_story_5020_50201701_136_dialog_content = "それじゃ、言われた通りの話にしよっと！",
  ui_story_5020_50201701_137_dialog_content = "あ、その前に、雲島の伝説の結末、\n話しておかなきゃ…",
  ui_story_5020_50201701_138_dialog_content = "結末？…まだ私たちの知らないことがあったの？",
  ui_story_5020_50201701_139_dialog_content = "ふふん…なんと、\nさっきバイトさんから聞いたばかりの情報だよ！",
  ui_story_5020_50201701_140_dialog_content = "聞きたいなら、また注文を…",
  ui_story_5020_50201701_141_dialog_content = "おかわり。",
  ui_story_5020_50201701_142_dialog_content = "いいタイミングだね～！\nそれじゃ、この前は――",
  ui_story_5020_50201701_143_dialog_content = "「将軍様は不死身で血も涙もないと言われていた」まで話したかな？\n雲島には誰も、弱点を知っている人がいなかったの。たった一人を除いて…",
  ui_story_5020_50201701_144_dialog_content = "ジャジャ～ン！\nその一人がなんと、うちのカヤノ！",
  ui_story_5020_50201701_145_dialog_content = "え？な、なんですか、急に？\n私、呼ばれましたか…？",
  ui_story_5020_50201701_146_dialog_content = "こっちでPlayerNameに聞かせてあげて。\n仕事サボった日に、何を見たか。",
  ui_story_5020_50201701_147_dialog_content = "わ、私は…あの日は郊外の<color=#FFB400>霊園</color>でお花見をしていただけで…\nちょうど、今は白桜の散る季節なので…",
  ui_story_5020_50201701_148_dialog_content = "でも、入口に着いたら…中にもう、人がいたんです…",
  ui_story_5020_50201701_149_dialog_content = "！？",
  ui_story_5020_50201701_150_dialog_content = "（我々より先に霊園にいた、何者かのことだ！）",
  ui_story_5020_50201701_151_dialog_content = "だ…誰なの！？",
  ui_story_5020_50201701_152_dialog_content = "ひえぇ…PlayerName様…\nそんなに急に迫ってこないでください…",
  ui_story_5020_50201701_153_dialog_content = "ご、ごめん…",
  ui_story_5020_50201701_154_dialog_content = "気づかれていなかったようですが、\n私からははっきり見えました…",
  ui_story_5020_50201701_155_dialog_content = "あれは…<color=#FFB400>将軍様</color>でした…",
  ui_story_5020_50201701_156_dialog_content = "…",
  ui_story_5020_50201701_157_dialog_content = "誰のお墓か分かりませんが、静かに前に立っていて…\n後ろにお付きもなく…",
  ui_story_5020_50201701_158_dialog_content = "墓前に金色の剣があったので、持っていくのだろうと思ったのですが…\nそうはしませんでした…",
  ui_story_5020_50201701_159_dialog_content = "それどころか、立ち去る前に…\n何か大切そうな、本のようなものを置いていきました…",
  ui_story_5020_50201701_160_dialog_content = "そ…それから、気付かれそうになったので…\n驚いてすぐに逃げてしまいました…",
  ui_story_5020_50201701_161_dialog_content = "…",
  ui_story_5020_50201701_162_dialog_content = "やはり、将軍だったか…",
  ui_story_5020_50201701_163_dialog_content = "その通り！あの冷酷無慈悲で知られた先代の将軍様が、\n誰もいない霊園に墓参りをしていた…",
  ui_story_5020_50201701_164_dialog_content = "ふふふ、この話が広まれば…\n新しいお客さんが増やせそう！",
  ui_story_5020_50201701_165_dialog_content = "でも、その話は…",
  ui_story_5020_50201701_166_dialog_content = "よいのです、PlayerName様。",
  ui_story_5020_50201701_167_dialog_content = "それが…先代の将軍と巫女が\n雲島に残していった最後の面影であるなら…",
  ui_story_5020_50201701_168_dialog_content = "2人のその姿をもって、\n雲島の昔話の終わりといたしましょう。",
  ui_story_5020_50201701_169_dialog_content = "もう、新しい時代は…",
  ui_story_5020_50201701_170_dialog_content = "始まっているのでございますから――",
  ui_story_5020_50201701_171_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5020_50201701_172_dialog_content = "道を開けろ、こんな所で屋台を出すな！\n主城に向かう道を塞ぐんじゃない！",
  ui_story_5020_50201701_173_dialog_content = "主城？まだそんなものがあるのか？\nあんた、どこから来た？",
  ui_story_5020_50201701_174_dialog_content = "…",
  ui_story_5020_50201701_175_dialog_content = "本島がもう動いたようですね。\nあの方たちの服の御紋は、本島のものです。",
  ui_story_5020_50201701_176_dialog_content = "やはり、雲島を手放すつもりは\nないようでございますね。",
  ui_story_5020_50201701_177_dialog_content = "リンネさん、このまま…\nこの地に留まるつもりですか？",
  ui_story_5020_50201701_178_dialog_content = "ふふ、どうするかはもう決めております。\nそういうあなた方は…",
  ui_story_5020_50201701_179_dialog_content = "どうやってお帰りになるのでございますか？",
  ui_story_5020_50201701_180_dialog_content = "心配いらないよ。\n巨像で来た道を戻るだけだから。",
  ui_story_5020_50201701_181_dialog_content = "そういえば…ソラヴァン、\nちゃんと修理してあげなきゃ…",
  ui_story_5020_50201701_182_dialog_content = "巨像？…ソラ…？",
  ui_story_5020_50201701_183_dialog_content = "聞いたことのない言葉ばかりでございますね…",
  ui_story_5020_50201701_184_dialog_content = "やはり、外の世界も見るべきでございましょうか…",
  ui_story_5020_50201701_185_dialog_content = "<color=#e8d9bb>江富城の港、埠頭</color>",
  ui_story_5020_50201701_186_dialog_content = "いいからいいから！\n見送りはここまででいいよ！",
  ui_story_5020_50201701_187_dialog_content = "迎えの船ももうすぐ来るから。",
  ui_story_5020_50201701_188_dialog_content = "フン…",
  ui_story_5020_50201701_189_dialog_content = "見送りなどするつもりはない…",
  ui_story_5020_50201701_190_dialog_content = "拙者は雲島の礼儀に従い、\n顔を出しに来ただけのことだ。",
  ui_story_5020_50201701_191_dialog_content = "ア、アメモリ…",
  ui_story_5020_50201701_192_dialog_content = "アタシ…",
  ui_story_5020_50201701_193_dialog_content = "<size=45>うえええ～ん！</size>",
  ui_story_5020_50201701_194_dialog_content = "な、なんだ！？突然どうした！？",
  ui_story_5020_50201701_195_dialog_content = "うえええ～ん…アメモリが別れを惜しんでくれるなんて！\nアタシ…",
  ui_story_5020_50201701_196_dialog_content = "<size=50><anim type=Shake>みんなとお別れするの、超悲しいよお――</anim></size>",
  ui_story_5020_50201701_197_dialog_content = "ほら、ヨウ…いい子ですから、泣いてはいけませんよ。",
  ui_story_5020_50201701_198_dialog_content = "またお会いできますから。",
  ui_story_5020_50201701_199_dialog_content = "え、ほ…ほんとに…？",
  ui_story_5020_50201701_200_dialog_content = "リンネ…",
  ui_story_5020_50201701_201_dialog_content = "<size=50><anim type=Shake>うええええ～ん！\nほんとにアタシと一緒に来てくれないの！？</anim></size>",
  ui_story_5020_50201701_202_dialog_content = "<size=55><anim type=Shake>うえええ～ん…</anim></size>",
  ui_story_5020_50201701_203_dialog_content = "あらあら…困りましたね…",
  ui_story_5020_50201701_204_dialog_content = "ヨウ、よく聞いてください――",
  ui_story_5020_50201701_205_dialog_content = "わたくしには、この雲島でやらねばならないことが\nたくさんあるのです…",
  ui_story_5020_50201701_206_dialog_content = "本島の者たちがすでに動いています。\n誰かがこの地で、けん制していかなければなりません。",
  ui_story_5020_50201701_207_dialog_content = "雲照鏡と天雲斬は…\nわたくしがきちんと預かっています。",
  ui_story_5020_50201701_208_dialog_content = "ですが、これから先は、わたくし自身の力で、\nこの雲島に平和をもたらしてご覧にいれます。",
  ui_story_5020_50201701_209_dialog_content = "もちろん…アメモリと幽燭の方たちも、\n手助けをしてくださいますね？",
  ui_story_5020_50201701_210_dialog_content = "無論。",
  ui_story_5020_50201701_211_dialog_content = "おぬしに言われずとも、\n本島に抗うことが幽燭の者の使命だ。",
  ui_story_5020_50201701_212_dialog_content = "ですから…ヨウ、わたくしが雲島に\n変化をもたらさなければならないのです。",
  ui_story_5020_50201701_213_dialog_content = "信じてくれますね？",
  ui_story_5020_50201701_214_dialog_content = "うえええ～ん…\nもちろん、リンネなら絶対大丈夫よ…",
  ui_story_5020_50201701_215_dialog_content = "それじゃ…リンネ、アメモリ…\nカヤノ、モモ、アンズも…",
  ui_story_5020_50201701_216_dialog_content = "みんな、元気でね！！！",
  ui_story_5020_50201701_217_dialog_content = "それから…PlayerNameとバイス！",
  ui_story_5020_50201701_218_dialog_content = "え、なに？",
  ui_story_5020_50201701_219_dialog_content = "ありがとう。大変な依頼だったのに引き受けてくれて。\nアタシをここまで連れてきてくれて。",
  ui_story_5020_50201701_220_dialog_content = "アタシ、記憶と同じくらい大切な友だちができた…",
  ui_story_5020_50201701_221_dialog_content = "この島に来て、やっぱり\nアタシにとって一生の宝物が手に入ったわ。",
  ui_story_5020_50201701_222_dialog_content = "…ぐすっ…",
  ui_story_5020_50201701_223_dialog_content = "（どうしよう…なぐさめた方がいいかな…）",
  ui_story_5020_50201701_224_dialog_content = "だから…",
  ui_story_5020_50201701_225_dialog_content = "リン家に戻ったら、お礼をキミの口座に振り込んでおくね！！\n7ケタなんかじゃ足りないわ！！",
  ui_story_5020_50201701_226_dialog_content = "ええ！！？",
  ui_story_5020_50201701_227_dialog_content = "…アタシ、それ以外に感謝の仕方、思いつかないから！",
  ui_story_5020_50201701_228_dialog_content = "約束通りで十分よ！？",
  ui_story_5020_50201701_229_dialog_content = "ああ…でも、どうやって使うかしっかり計画を立てなきゃ。\nとにかくまずは巨像を修理して、それから…",
  ui_story_5020_50201701_230_dialog_content = "（もう使い道を考え始めてる…）",
  ui_story_5020_50201701_231_dialog_content = "む？妙に遅い船だな…",
  ui_story_5020_50201701_232_dialog_content = "<color=#e8d9bb>ポーゥ…</color>",
  ui_story_5020_50201701_233_dialog_content = "うう…おえっ――",
  ui_story_5020_50201701_234_dialog_content = "これが…海の力ってやつかしら…",
  ui_story_5020_50201701_235_dialog_content = "ね、義姉さん、大丈夫…！？\nアタシまでビックリしたじゃない！",
  ui_story_5020_50201701_236_dialog_content = "絶対人に知られちゃだめだよ、\nリン家にその人ありとまで言われたイン姉が…船が苦手なんて！",
  ui_story_5020_50201701_237_dialog_content = "お、大声出さないで…うえっ…",
  ui_story_5020_50201701_238_dialog_content = "うえええ～ん――",
  ui_story_5020_50201701_239_dialog_content = "お得意さん…1食7杯のお得意さん…",
  ui_story_5020_50201701_240_dialog_content = "絶対また雲島に来てね…！",
  ui_story_5020_50201701_241_dialog_content = "またカニ家ラーメンに食べに来てね…！",
  ui_story_5020_50201701_242_dialog_content = "うえええ～ん…",
  ui_story_5020_50201701_243_dialog_content = "な、泣かないでください…",
  ui_story_5020_50201701_244_dialog_content = "ヨウさんの試食してくれた新メニュー…\nきっと、たくさん売れますよ…",
  ui_story_5020_50201701_245_dialog_content = "だから、そんなに悲しまないでください…",
  ui_story_5020_50201701_246_dialog_content = "あっ、確かに！",
  ui_story_5020_50201701_247_dialog_content = "ヨウ――",
  ui_story_5020_50201701_248_dialog_content = "道中お気を付けて――",
  ui_story_5020_50201701_249_dialog_content = "次に会う時まで、腕をなまらせるのではないぞ。",
  ui_story_5020_50201701_250_dialog_content = "あ…",
  ui_story_5020_50201701_251_dialog_content = "みんな…",
  ui_story_5020_50201701_252_dialog_content = "さようなら――！",
  ui_story_5020_50201701_253_dialog_content = "ヨウが船に乗って、リンネは手を振り続けてる。\nアメモリはその後ろに立って、遠くをじっと見つめている。",
  ui_story_5020_50201701_254_dialog_content = "船が地平線の向こうに消えてしまうまでの時間を、\nみんな惜しんでるんだろうな。",
  ui_story_5020_50201701_255_dialog_content = "――十年前、三人の少女たちの運命が、ある人の死によって引き裂かれた。",
  ui_story_5020_50201701_256_dialog_content = "その十年後、また別の人が死に、彼女たちは再び別れた。",
  ui_story_5020_50201701_257_dialog_content = "雲島に咲く薄紅色の雪のような花が、\n十年越しの出会いと別れをずっと見守ってきた。",
  ui_story_5020_50201701_258_dialog_content = "そして、すでにこの世を去った人たちが長い時と生死の境を越え、\n島と人の新たな門出を見守っていた。",
  ui_story_5020_50201701_259_dialog_content = "<color=#e8d9bb>紅に雪の散る如く　終</color>"
}
return config
